-- Reproductive and Sexual Health System question bank: exactly 500 hand-written NCLEX-style
-- questions (single-best-answer + select-all-that-apply), 50 per note. Every answer is grounded in
-- (and its rationale limited to) the source note listed for its topic:
--   Notes/ReproductiveHealth/Sexual-Health-Nursing.html
--   Notes/ReproductiveHealth/Priapism.html
--   Notes/ReproductiveHealth/Infertility.html
--   Notes/ReproductiveHealth/TURP-Prostatectomy.html
--   Notes/ReproductiveHealth/Contraception-Family-Planning.html
--   Notes/ReproductiveHealth/Reproductive-Anatomy.html
--   Notes/ReproductiveHealth/STI-STD.html
--   Notes/ReproductiveHealth/Reproductive-Complications.html
--   Notes/ReproductiveHealth/BPH.html
--   Notes/ReproductiveHealth/Reproductive-Health-Overview.html
--
-- Maps each source path through note_catalog.note_id to the published test_topics
-- row(s) for that note (matching test.html's note-level topic grouping). All
-- missing/ambiguous mappings are reported before any deletion or insertion.
-- Safe to rerun: only rows carrying this script's category labels are replaced,
-- and the transaction aborts unless exactly 50 rows per topic (500) exist after insert.
BEGIN;

CREATE TEMP TABLE _repro_sources (
  source_key text PRIMARY KEY,
  source_path text NOT NULL UNIQUE,
  category text NOT NULL UNIQUE
) ON COMMIT DROP;

INSERT INTO _repro_sources (source_key, source_path, category) VALUES
  ('sexual', 'Notes/ReproductiveHealth/Sexual-Health-Nursing.html', 'Reproductive and Sexual Health NCLEX seed v1 - sexual health nursing'),
  ('priapism', 'Notes/ReproductiveHealth/Priapism.html', 'Reproductive and Sexual Health NCLEX seed v1 - priapism'),
  ('infertility', 'Notes/ReproductiveHealth/Infertility.html', 'Reproductive and Sexual Health NCLEX seed v1 - infertility'),
  ('turp', 'Notes/ReproductiveHealth/TURP-Prostatectomy.html', 'Reproductive and Sexual Health NCLEX seed v1 - turp prostatectomy'),
  ('contraception', 'Notes/ReproductiveHealth/Contraception-Family-Planning.html', 'Reproductive and Sexual Health NCLEX seed v1 - contraception family planning'),
  ('anatomy', 'Notes/ReproductiveHealth/Reproductive-Anatomy.html', 'Reproductive and Sexual Health NCLEX seed v1 - reproductive anatomy'),
  ('sti', 'Notes/ReproductiveHealth/STI-STD.html', 'Reproductive and Sexual Health NCLEX seed v1 - sti std'),
  ('complications', 'Notes/ReproductiveHealth/Reproductive-Complications.html', 'Reproductive and Sexual Health NCLEX seed v1 - reproductive complications'),
  ('bph', 'Notes/ReproductiveHealth/BPH.html', 'Reproductive and Sexual Health NCLEX seed v1 - bph'),
  ('overview', 'Notes/ReproductiveHealth/Reproductive-Health-Overview.html', 'Reproductive and Sexual Health NCLEX seed v1 - reproductive health overview');

CREATE TEMP TABLE _repro_seed_map (
  source_key text PRIMARY KEY,
  source_path text NOT NULL,
  category text NOT NULL,
  note_id uuid NOT NULL,
  note_title text NOT NULL,
  topic_id uuid NOT NULL,
  topic_aliases text[] NOT NULL
) ON COMMIT DROP;

CREATE TEMP TABLE _repro_seed_config (test_id bigint NOT NULL) ON COMMIT DROP;

DO $$
DECLARE
  v_subject_id uuid;
  v_subject_count integer;
  v_note_count integer;
  v_topic_count integer;
  v_note_id uuid;
  v_note_title text;
  v_topic_id uuid;
  v_aliases text[];
  v_test_id bigint;
  v_errors text[] := ARRAY[]::text[];
  r record;
BEGIN
  SELECT count(*)
    INTO v_subject_count
    FROM test_subjects
   WHERE lower(btrim(name)) = 'reproductive and sexual health system'
     AND is_active = true;
  IF v_subject_count <> 1 THEN
    v_errors := array_append(v_errors,
      format('Expected exactly one active test_subjects row named "Reproductive and Sexual Health System"; found %s.', v_subject_count));
  ELSE
    SELECT id INTO v_subject_id
      FROM test_subjects
     WHERE lower(btrim(name)) = 'reproductive and sexual health system'
       AND is_active = true;
  END IF;

  SELECT id INTO v_test_id
    FROM tests
   WHERE is_active = true
   ORDER BY id
   LIMIT 1;
  IF v_test_id IS NULL THEN
    v_errors := array_append(v_errors, 'No active tests row is available for test_questions.test_id.');
  END IF;

  FOR r IN SELECT source_key, source_path, category FROM _repro_sources ORDER BY source_key LOOP
    SELECT count(*)
      INTO v_note_count
      FROM note_catalog
     WHERE path = r.source_path
       AND is_active = true;

    IF v_note_count = 0 THEN
      v_errors := array_append(v_errors,
        format('Missing active note_catalog mapping for %s.', r.source_path));
      CONTINUE;
    ELSIF v_note_count > 1 THEN
      v_errors := array_append(v_errors,
        format('Ambiguous active note_catalog mapping for %s (%s rows).', r.source_path, v_note_count));
      CONTINUE;
    END IF;

    SELECT note_id, title
      INTO v_note_id, v_note_title
      FROM note_catalog
     WHERE path = r.source_path
       AND is_active = true;

    IF v_subject_count <> 1 THEN
      v_errors := array_append(v_errors,
        format('Cannot resolve test_topics aliases for %s because the active Reproductive and Sexual Health System subject mapping is not unique.',
               r.source_path));
      CONTINUE;
    END IF;

    SELECT count(*)
      INTO v_topic_count
      FROM test_topics
     WHERE subject_id = v_subject_id
       AND note_id = v_note_id
       AND (status = 'published' OR status IS NULL);

    IF v_topic_count = 0 THEN
      v_errors := array_append(v_errors,
        format('No published test_topics row in Reproductive and Sexual Health System points to note %s (%s).',
               v_note_title, r.source_path));
      CONTINUE;
    END IF;

    -- Sibling topics are expected aliases in test.html's note-level merged row.
    -- Insert all 50 for this source under one deterministic sibling topic_id.
    SELECT t.id
      INTO v_topic_id
      FROM test_topics t
     WHERE t.subject_id = v_subject_id
       AND t.note_id = v_note_id
       AND (t.status = 'published' OR t.status IS NULL)
     ORDER BY t.display_order NULLS LAST, t.created_at, t.name, t.id
     LIMIT 1;

    -- Collect the actual underlying aliases for the mapping check/report context.
    SELECT array_agg(t.name ORDER BY t.display_order NULLS LAST, t.name, t.id)
      INTO v_aliases
      FROM test_topics t
     WHERE t.subject_id = v_subject_id
       AND t.note_id = v_note_id
       AND (t.status = 'published' OR t.status IS NULL);

    INSERT INTO _repro_seed_map
      (source_key, source_path, category, note_id, note_title, topic_id, topic_aliases)
    VALUES
      (r.source_key, r.source_path, r.category, v_note_id, v_note_title, v_topic_id, v_aliases);
  END LOOP;

  IF cardinality(v_errors) > 0 THEN
    RAISE EXCEPTION E'Reproductive seed mapping validation failed before any deletion/insertion:\n - %',
      array_to_string(v_errors, E'\n - ');
  END IF;

  IF (SELECT count(*) FROM _repro_seed_map) <> 10 THEN
    RAISE EXCEPTION 'Internal mapping check failed: expected 10 note mappings, found %.',
      (SELECT count(*) FROM _repro_seed_map);
  END IF;

  INSERT INTO _repro_seed_config (test_id) VALUES (v_test_id);
END $$;

-- Only rows from this script's unique category names are replaced.
DELETE FROM test_questions q
 USING _repro_seed_map m
 WHERE q.category = m.category;

INSERT INTO test_questions
  (test_id, topic_id, question, question_stem, options, correct_answer, rationale,
   category, is_multiple_choice, display_order, points, is_active)
SELECT c.test_id, m.topic_id, v.stem, v.stem, v.options, v.correct_answer, v.rationale,
       m.category, v.is_multi, v.display_order, 1, true
  FROM (VALUES
  ('sexual', 1, 'A 22-year-old client comes to the clinic requesting STI screening and appears tense. The nurse is beginning the sexual health assessment in a private exam room. Which question by the nurse is BEST?', '[{"id": "a", "text": "\"You always use condoms with every partner, don''t you?\""}, {"id": "b", "text": "\"Can you tell me about your sexual activity and protection use?\""}, {"id": "c", "text": "\"Are you having sex only with your girlfriend, or with others too?\""}, {"id": "d", "text": "\"How many partners have you had, and why have there been so many?\""}]'::jsonb, '["b"]', 'The nurse assesses sexual activity, protection use, and STI risks using open-ended, nonjudgmental questions. A leading yes/no question, an assumption about the partner''s gender, and a judgmental question about the number of partners all violate this.', false),
  ('sexual', 2, 'A 34-year-old client in a semi-private hospital room needs a sexual health history before a pelvic exam. Her roommate has three visitors at the bedside, and the curtain is open. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Ask open-ended questions about her protection use and STI risks"}, {"id": "b", "text": "Assess her readiness to learn about STI prevention"}, {"id": "c", "text": "Provide privacy for the sexual health discussion"}, {"id": "d", "text": "Educate her that only condoms prevent STIs"}]'::jsonb, '["c"]', 'The nurse must provide privacy for sexual health discussions before any questions are asked; open-ended assessment, assessing readiness to learn, and education are appropriate only after privacy is ensured.', false),
  ('sexual', 3, 'A nurse is preparing to complete a sexual health assessment and teaching session for a 28-year-old client who was just treated for an STI. Which actions are appropriate? Select all that apply.', '[{"id": "a", "text": "Use yes/no questions to keep the visit brief"}, {"id": "b", "text": "Provide privacy for the discussion"}, {"id": "c", "text": "Ask her partner to stay and help answer"}, {"id": "d", "text": "Use open-ended, nonjudgmental questions"}, {"id": "e", "text": "Assess readiness to learn before teaching"}]'::jsonb, '["b", "d", "e"]', '(b) Correct: the nurse provides privacy for sexual health discussions. (d) Correct: the nurse asks about sexual activity, protection use, and STI risks with open-ended, nonjudgmental questions. (e) Correct: always assess readiness to learn before teaching. (a) Wrong: yes/no questions are not open-ended. (c) Wrong: having another person present removes the privacy the nurse must provide.', true),
  ('sexual', 4, 'A 26-year-old client has just learned she has an STI. She is tearful and says, "I can''t believe this is happening to me." The nurse had planned to teach partner notification and condom use. Which action is BEST at this time?', '[{"id": "a", "text": "Assess her readiness to learn before beginning the teaching"}, {"id": "b", "text": "Give her the complete written partner notification teaching now"}, {"id": "c", "text": "Explain that abstinence is 100% effective against STIs"}, {"id": "d", "text": "Tell her that STIs are common, so there is nothing to worry about"}]'::jsonb, '["a"]', 'Always assess readiness to learn before teaching and use therapeutic communication. Delivering full teaching to a distressed client ignores readiness, and false reassurance is not therapeutic communication.', false),
  ('sexual', 5, 'A 41-year-old client who speaks limited English arrives for contraception counseling with her 13-year-old daughter, who is fluent in English and offers to interpret. Which action by the nurse is BEST?', '[{"id": "a", "text": "Allow the daughter to interpret because she knows her mother''s history"}, {"id": "b", "text": "Speak slowly in English and use gestures to explain the methods"}, {"id": "c", "text": "Use a certified interpreter for the contraception discussion"}, {"id": "d", "text": "Ask the client''s husband to interpret by phone instead"}]'::jsonb, '["c"]', 'The nurse uses certified interpreters only, never family members or children. The daughter is a child and the husband is a family member, so neither is appropriate.', false),
  ('sexual', 6, 'During STI screening, a 19-year-old client says, "I''m transgender, and I''m worried you''re going to judge me." Which response by the nurse BEST reflects the nurse''s role in sexual health?', '[{"id": "a", "text": "\"We can talk about your identity later, after the screening is done.\""}, {"id": "b", "text": "\"I support all gender identities, and you can talk with me safely here.\""}, {"id": "c", "text": "\"Your identity is not related to sexual health, so let''s focus on risks.\""}, {"id": "d", "text": "\"Many transgender patients are high-risk, so I''ll add extra screening.\""}]'::jsonb, '["b"]', 'The nurse''s support role is to be affirming of all gender identities and sexual orientations, using therapeutic, nonjudgmental communication. Assuming risk based on identity is a stereotype; the nurse must assess each patient individually.', false),
  ('sexual', 7, 'A nurse is observing a nursing student obtain a sexual history from a 45-year-old male client at a clinic. Which question by the student requires follow-up by the nurse?', '[{"id": "a", "text": "\"What do you use for protection during sexual activity?\""}, {"id": "b", "text": "\"Do you have any concerns about your STI risks?\""}, {"id": "c", "text": "\"Can you tell me about your sexual partners?\""}, {"id": "d", "text": "\"Does your wife use any type of contraception?\""}]'::jsonb, '["d"]', 'Asking about a wife assumes the client''s partner and sexual orientation; nurses avoid assumptions and stereotypes and are affirming of all sexual orientations. The other questions are open-ended and nonjudgmental.', false),
  ('sexual', 8, 'A 31-year-old client who takes combined oral contraceptive pills calls the clinic. Which reports require the nurse to tell her to seek care IMMEDIATELY? Select all that apply.', '[{"id": "a", "text": "Sudden chest pain"}, {"id": "b", "text": "Severe leg pain in one calf"}, {"id": "c", "text": "Severe headache"}, {"id": "d", "text": "Asking which condoms to buy"}, {"id": "e", "text": "Vision changes since morning"}]'::jsonb, '["a", "b", "c", "e"]', 'These are ACHES hormonal contraceptive warning signs that must be reported immediately. (a) Correct: chest pain may signal PE (pulmonary embolism). (b) Correct: severe leg pain may signal DVT. (c) Correct: headache may signal stroke. (e) Correct: eye problems (vision changes) may signal stroke or HTN. (d) Wrong: asking about condoms is an STI prevention question, not a warning sign.', true),
  ('sexual', 9, 'A 30-year-old client who practices Islam is scheduled for a pelvic exam. She quietly asks whether a female caregiver can perform the exam instead of the male nurse assigned. Which action is BEST?', '[{"id": "a", "text": "Explain that the male nurse is professional, so her request is not necessary"}, {"id": "b", "text": "Proceed with the exam while keeping her covered to respect modesty"}, {"id": "c", "text": "Honor the same-gender caregiver request and ask permission before touching"}, {"id": "d", "text": "Ask her husband to decide which caregiver would be acceptable"}]'::jsonb, '["c"]', 'Culturally competent care includes asking about and honoring same-gender caregiver requests, and the nurse avoids touching without permission. Dismissing the request is cultural imposition, and deferring to the husband is an assumption rather than assessing the patient individually.', false),
  ('sexual', 10, 'A 52-year-old client who is Orthodox Jewish is recovering after gynecologic surgery. She tells the nurse she has not eaten because the hospital tray contains foods she cannot eat. Which action by the nurse is BEST?', '[{"id": "a", "text": "Encourage her to eat what she can, because nutrition is needed for healing"}, {"id": "b", "text": "Arrange meals that respect her kosher dietary restrictions"}, {"id": "c", "text": "Explain that dietary practices are set aside during hospital stays"}, {"id": "d", "text": "Ask her family to bring all of her meals so staff need not adjust"}]'::jsonb, '["b"]', 'Kosher dietary restrictions are a cultural consideration for Orthodox Jewish clients, and culturally competent care includes asking about and honoring food preferences. Telling her to set aside her practices or eat foods she cannot eat is cultural imposition.', false),
  ('sexual', 11, 'A 50-year-old client declines a recommended gynecologic treatment, telling the nurse that it conflicts with her cultural beliefs. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Document the refusal and notify the provider"}, {"id": "b", "text": "Explain that the treatment is required for her health"}, {"id": "c", "text": "Ask a family member to help convince her"}, {"id": "d", "text": "Ask open-ended questions about her beliefs"}]'::jsonb, '["d"]', 'If a patient refuses treatment due to cultural belief, the nurse asks open-ended questions, educates respectfully, then documents. Documentation comes after exploring the belief, and pressuring her is cultural imposition.', false),
  ('sexual', 12, 'A nurse is caring for a 36-year-old client who recently immigrated and is being seen for contraception counseling. Which actions demonstrate culturally competent care? Select all that apply.', '[{"id": "a", "text": "Asking about her food, modesty, and spiritual preferences"}, {"id": "b", "text": "Telling her to stop her traditional remedies"}, {"id": "c", "text": "Assessing her individually instead of assuming"}, {"id": "d", "text": "Using certified interpreters only"}, {"id": "e", "text": "Using her bilingual 10-year-old son to interpret"}]'::jsonb, '["a", "c", "d"]', '(a) Correct: culturally competent care includes asking about patient preferences (food, modesty, spiritual practices). (c) Correct: avoid assumptions and stereotypes; assess each patient individually. (d) Correct: use certified interpreters only. (e) Wrong: never use family members or children as interpreters. (b) Wrong: traditional or alternative medicine is respected alongside standard treatment; forcing your own beliefs is cultural imposition.', true),
  ('sexual', 13, 'A nurse using the LEARN model has just listened to a 44-year-old client''s perspective on using an herbal tea for menstrual cramps along with her prescribed treatment. Which action should the nurse take NEXT?', '[{"id": "a", "text": "Recommend care options for managing her cramps now"}, {"id": "b", "text": "Negotiate an agreement on the plan"}, {"id": "c", "text": "Explain the nurse''s perception of the situation"}, {"id": "d", "text": "Acknowledge differences and similarities in views"}]'::jsonb, '["c"]', 'LEARN proceeds Listen, Explain, Acknowledge, Recommend, Negotiate. After listening to the patient''s perspective, the NEXT step is to explain your perception of the situation; acknowledging differences comes after explaining.', false),
  ('sexual', 14, 'A nurse and a 39-year-old client have discussed her traditional remedy, acknowledged their differences, and reviewed care options. The client now agrees to use the remedy alongside prescribed medication. Which LEARN step has the nurse completed MOST recently?', '[{"id": "a", "text": "Negotiate an agreement"}, {"id": "b", "text": "Recommend care options"}, {"id": "c", "text": "Listen to the patient''s perspective"}, {"id": "d", "text": "Explain your perception"}]'::jsonb, '["a"]', 'The final LEARN step is Negotiate an agreement, which follows Recommend care options. Reaching a mutually accepted plan is negotiation, not recommendation.', false),
  ('sexual', 15, 'A 24-year-old client has received STI prevention teaching after treatment for an STI. Which statements by the client indicate understanding? Select all that apply.', '[{"id": "a", "text": "\"Condoms reduce my risk, but they don''t eliminate all STI risk.\""}, {"id": "b", "text": "\"Using a condom makes sex safe during a herpes outbreak.\""}, {"id": "c", "text": "\"My birth control pill also protects me from STIs.\""}, {"id": "d", "text": "\"Partner notification and treatment will prevent reinfection.\""}, {"id": "e", "text": "\"One drink with my metronidazole should be fine.\""}]'::jsonb, '["a", "d"]', '(a) Correct: condoms reduce but do not eliminate all STI risk. (d) Correct: partner notification and treatment prevent reinfection. (b) Wrong: avoid sexual activity during active herpes outbreaks. (c) Wrong: only condoms prevent STIs; pills are hormonal contraception. (e) Wrong: avoid alcohol with metronidazole (Flagyl) because of a severe vomiting reaction.', true),
  ('sexual', 16, 'While charting, a nurse says to a coworker about a client from another country, "Our way of doing things is just better than her culture''s way." The coworker recognizes this as which concept, which requires follow-up?', '[{"id": "a", "text": "Acculturation"}, {"id": "b", "text": "Cultural competence"}, {"id": "c", "text": "Ethnocentrism"}, {"id": "d", "text": "Cultural imposition"}]'::jsonb, '["c"]', 'Ethnocentrism is believing one''s own culture is superior and should be avoided. Cultural imposition is forcing one''s own beliefs on patients; the nurse expressed a belief of superiority but did not force it on the client.', false),
  ('sexual', 17, 'A 27-year-old client being treated for an STI tells the nurse she also drinks a traditional herbal remedy recommended by her grandmother. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"You need to stop the remedy right away; it is not real medicine.\""}, {"id": "b", "text": "\"I respect your traditional remedy; let''s use it alongside standard treatment.\""}, {"id": "c", "text": "\"The remedy can replace your prescribed medication if it helps you feel better.\""}, {"id": "d", "text": "\"Your grandmother''s beliefs should not affect your care here.\""}]'::jsonb, '["b"]', 'Culturally competent care includes respecting traditional or alternative medicine alongside standard treatment. Telling her to stop it is cultural imposition, and replacing standard treatment is not what the nurse supports.', false),
  ('sexual', 18, 'A 29-year-old client is being discharged after insertion of a Paragard IUD. Which teaching points should the nurse include? Select all that apply.', '[{"id": "a", "text": "The IUD prevents STIs"}, {"id": "b", "text": "Paragard contains hormones"}, {"id": "c", "text": "Report fever, pain, and discharge"}, {"id": "d", "text": "Check the strings monthly"}, {"id": "e", "text": "Monitor for signs of infection"}]'::jsonb, '["c", "d", "e"]', '(d) Correct: IUD users check strings monthly. (c) Correct: after IUD insertion, report fever, pain, and discharge (infection signs). (e) Correct: monitor for infection. (b) Wrong: Paragard is the copper IUD; Mirena is hormonal. (a) Wrong: only condoms prevent STIs.', true),
  ('sexual', 19, 'A 24-year-old client who uses a hormonal vaginal ring tells the nurse she has started a relationship with a new partner. Which statement by the nurse is BEST?', '[{"id": "a", "text": "\"Your ring prevents pregnancy and also protects you from STIs.\""}, {"id": "b", "text": "\"A copper IUD would protect you from STIs better than the ring.\""}, {"id": "c", "text": "\"A diaphragm is a barrier, so it will prevent STIs like condoms.\""}, {"id": "d", "text": "\"Condoms are the method that prevents STIs, so use them with the ring.\""}]'::jsonb, '["d"]', 'Only condoms prevent STIs. The ring is hormonal contraception, and although the diaphragm is a barrier method, only condoms prevent STIs.', false),
  ('sexual', 20, 'Four clients at a women''s health clinic request combined hormonal contraceptive pills. Which client''s information requires follow-up with the provider before the prescription is filled?', '[{"id": "a", "text": "A 37-year-old who smokes cigarettes daily"}, {"id": "b", "text": "A 33-year-old who smokes cigarettes daily"}, {"id": "c", "text": "A 38-year-old who has never smoked"}, {"id": "d", "text": "A 22-year-old with a new sexual partner"}]'::jsonb, '["a"]', 'Hormonal contraception is contraindicated in smokers older than 35, so the 37-year-old smoker needs follow-up. The 33-year-old smoker is under 35, and the 38-year-old does not smoke.', false),
  ('sexual', 21, 'A 28-year-old client using the contraceptive patch calls the clinic reporting severe pain and swelling in her left calf that began yesterday. Which instruction by the nurse is BEST?', '[{"id": "a", "text": "\"Elevate the leg and call back if the pain continues next week.\""}, {"id": "b", "text": "\"Seek care immediately; severe leg pain can be a sign of DVT.\""}, {"id": "c", "text": "\"Remove the patch and use condoms until your next clinic visit.\""}, {"id": "d", "text": "\"This is an expected effect of the patch and should pass soon.\""}]'::jsonb, '["b"]', 'Severe leg pain is the S in ACHES and may signal DVT (deep vein thrombosis); ACHES warning signs are reported immediately. Waiting or self-managing at home delays care for a potential DVT.', false),
  ('sexual', 22, 'A 33-year-old client taking hormonal contraceptive pills reports a sudden, severe headache and new blurred vision. Which complication should the nurse suspect and report IMMEDIATELY?', '[{"id": "a", "text": "Stroke"}, {"id": "b", "text": "Gallbladder disease"}, {"id": "c", "text": "Ectopic pregnancy"}, {"id": "d", "text": "Pulmonary embolism"}]'::jsonb, '["a"]', 'Headache and eye problems (vision changes) are ACHES warning signs of stroke. Pulmonary embolism is linked to chest pain, and gallbladder and ectopic pregnancy are linked to abdominal pain.', false),
  ('sexual', 23, 'A 23-year-old client who has multiple partners and reports IV drug use asks how to lower STI risk. Which teaching points should the nurse include? Select all that apply.', '[{"id": "a", "text": "Get regular STI screening"}, {"id": "b", "text": "Hormonal pills prevent STIs"}, {"id": "c", "text": "HPV (Gardasil) and hepatitis B vaccinations"}, {"id": "d", "text": "Condoms reduce but do not eliminate all STI risk"}, {"id": "e", "text": "Partner notification and treatment"}]'::jsonb, '["a", "c", "d", "e"]', '(a) Correct: regular STI screening is recommended, especially for high-risk individuals such as those with multiple partners or IV drug use. (c) Correct: HPV (Gardasil) and hepatitis B vaccinations are part of STI prevention. (d) Correct: condoms reduce but do not eliminate all STI risk. (e) Correct: partner notification and treatment prevent reinfection. (b) Wrong: only condoms prevent STIs.', true),
  ('sexual', 24, 'A nurse at a reproductive health clinic has four phone messages. Which client should the nurse call back FIRST?', '[{"id": "a", "text": "A client with an IUD asking how often to check the strings"}, {"id": "b", "text": "A client on metronidazole asking about wine at a dinner next week"}, {"id": "c", "text": "A client taking contraceptive pills who reports sudden chest pain"}, {"id": "d", "text": "A client asking whether the HPV vaccine (Gardasil) is available"}]'::jsonb, '["c"]', 'Chest pain in a hormonal contraceptive user is an ACHES warning sign of PE (pulmonary embolism) and must be reported immediately. The string-check, metronidazole, and vaccine questions are teaching needs that can wait.', false),
  ('sexual', 25, 'A 30-year-old client who has taken hormonal contraceptive pills for 2 years reports new, persistent abdominal pain. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "It is an expected effect of hormonal pills and only needs monitoring"}, {"id": "b", "text": "It may signal liver, ectopic pregnancy, or gallbladder problems"}, {"id": "c", "text": "It suggests an IUD infection that requires checking the strings"}, {"id": "d", "text": "It suggests a DVT that should be reported at the next routine visit"}]'::jsonb, '["b"]', 'Abdominal pain is the A in ACHES and can signal liver, ectopic pregnancy, or gallbladder problems; ACHES signs are reported immediately. DVT is associated with severe leg pain, not abdominal pain, and it would not wait for a routine visit.', false),
  ('sexual', 26, 'A 47-year-old client refuses a recommended treatment because of her cultural beliefs. Which actions by the nurse are appropriate? Select all that apply.', '[{"id": "a", "text": "Insist she follow the plan the nurse believes in"}, {"id": "b", "text": "Ask open-ended questions about her beliefs"}, {"id": "c", "text": "Have her adult son consent on her behalf"}, {"id": "d", "text": "Document her refusal of treatment"}, {"id": "e", "text": "Educate her respectfully about the treatment"}]'::jsonb, '["b", "d", "e"]', '(b) Correct: when a patient refuses treatment due to cultural belief, ask open-ended questions. (e) Correct: educate respectfully. (d) Correct: document. (a) Wrong: forcing one''s own beliefs on patients is cultural imposition and never appropriate. (c) Wrong: having a family member override her decision does not respect her as an individual.', true),
  ('sexual', 27, 'A 25-year-old client with a Mirena IUD is reviewing her teaching with the nurse. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I will monitor for signs of infection.\""}, {"id": "b", "text": "\"Mirena is the hormonal type of IUD.\""}, {"id": "c", "text": "\"I should check the strings once a year.\""}, {"id": "d", "text": "\"This IUD does not protect me from STIs.\""}]'::jsonb, '["c"]', 'IUD strings are checked monthly, not yearly. Mirena is the hormonal IUD, clients monitor for infection, and only condoms prevent STIs, so those statements are correct.', false),
  ('sexual', 28, 'A 26-year-old client calls 3 days after IUD insertion. Which finding requires IMMEDIATE follow-up by the nurse?', '[{"id": "a", "text": "She can feel the strings when she checks"}, {"id": "b", "text": "She has fever, pelvic pain, and discharge"}, {"id": "c", "text": "She wants to know if she still needs condoms"}, {"id": "d", "text": "She asks whether the IUD is hormonal or copper"}]'::jsonb, '["b"]', 'After IUD insertion, fever, pain, and discharge are infection signs to report. Feeling the strings is expected with monthly string checks, and the condom and IUD-type questions are teaching needs.', false),
  ('sexual', 29, 'A 21-year-old client is starting a combined hormonal contraceptive patch. Which risks should the nurse include in the teaching? Select all that apply.', '[{"id": "a", "text": "Deep vein thrombosis (DVT)"}, {"id": "b", "text": "Need to check strings monthly"}, {"id": "c", "text": "Irreversible loss of fertility"}, {"id": "d", "text": "HTN"}, {"id": "e", "text": "Increased risk of STIs"}]'::jsonb, '["a", "d"]', '(a) Correct: DVT is a risk of hormonal contraception. (d) Correct: HTN is a risk of hormonal contraception. (b) Wrong: checking strings monthly applies to IUDs. (c) Wrong: irreversible describes permanent methods such as vasectomy and tubal ligation. (e) Wrong: the patch does not change STI risk; only condoms prevent STIs.', true),
  ('sexual', 30, 'A 38-year-old client who smokes asks the nurse about long-term contraception that does not contain hormones. Which option is the nurse MOST likely to expect the provider to discuss?', '[{"id": "a", "text": "Mirena IUD"}, {"id": "b", "text": "Paragard IUD"}, {"id": "c", "text": "Contraceptive patch"}, {"id": "d", "text": "Vaginal ring"}]'::jsonb, '["b"]', 'Paragard is the copper IUD, while Mirena is hormonal. The patch and ring are hormonal methods, which are contraindicated in smokers older than 35.', false),
  ('sexual', 31, 'A 27-year-old client scheduled for a vasectomy says, "We aren''t ready for kids now, but we can reverse it in a few years when we are." Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Vasectomy is a surgical method that is irreversible, so let''s talk about that.\""}, {"id": "b", "text": "\"That''s right; many people reverse it once they are ready for children.\""}, {"id": "c", "text": "\"Hormonal pills for your partner are also irreversible, so either is fine.\""}, {"id": "d", "text": "\"A vasectomy is temporary, like a diaphragm, so that plan will work.\""}]'::jsonb, '["a"]', 'Vasectomy and tubal ligation are permanent, surgical, irreversible methods that require informed consent. The client''s belief that it can be reversed shows he needs clarification before consent.', false),
  ('sexual', 32, 'A 17-year-old client is seen at a school-based clinic for a sexual health visit. Which actions reflect core nursing responsibilities in sexual health? Select all that apply.', '[{"id": "a", "text": "Ask open-ended questions about sexual activity"}, {"id": "b", "text": "Provide accurate information about consent"}, {"id": "c", "text": "Assume her partners are male when asking"}, {"id": "d", "text": "Be affirming of all sexual orientations"}, {"id": "e", "text": "Provide accurate information about contraception"}]'::jsonb, '["a", "b", "d", "e"]', '(a) Correct: assess sexual activity, protection use, and STI risks with open-ended questions. (b) Correct: educate with accurate information about consent. (d) Correct: support by being affirming of all gender identities and sexual orientations. (e) Correct: educate with accurate information about contraception. (c) Wrong: assuming partner gender is an assumption the nurse must avoid.', true),
  ('sexual', 33, 'A 35-year-old client is scheduled for a tubal ligation tomorrow. During the preoperative visit she says she has "some questions about whether this can be undone." What is the nurse''s PRIORITY action?', '[{"id": "a", "text": "Teach her to check her IUD strings monthly"}, {"id": "b", "text": "Review the ACHES warning signs with her"}, {"id": "c", "text": "Notify the provider; informed consent requires understanding"}, {"id": "d", "text": "Tell her the procedure also prevents STIs"}]'::jsonb, '["c"]', 'Tubal ligation is surgical and irreversible and requires informed consent; her uncertainty about reversibility means informed consent must be addressed with the provider before surgery. String checks and ACHES apply to IUDs and hormonal methods.', false),
  ('sexual', 34, 'A 16-year-old client at a teen clinic asks, "If I use condoms every time, I''m totally safe from STIs, right?" Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Yes; condoms remove all STI risk when used every time.\""}, {"id": "b", "text": "\"Condoms reduce but do not eliminate all STI risk.\""}, {"id": "c", "text": "\"Condoms only work well if you also take hormonal pills.\""}, {"id": "d", "text": "\"Condoms do not help with STIs, so abstinence is your only option.\""}]'::jsonb, '["b"]', 'Abstinence is 100% effective, and condoms reduce but do not eliminate all STI risk. Saying condoms remove all risk is inaccurate, and saying they do not help ignores that they reduce risk.', false),
  ('sexual', 35, 'A charge nurse overhears staff talking with clients on a reproductive health unit. Which statements require follow-up by the charge nurse? Select all that apply.', '[{"id": "a", "text": "\"Our culture is superior to yours, so trust our way.\""}, {"id": "b", "text": "\"What practices are important to you during your care?\""}, {"id": "c", "text": "\"You must accept my beliefs and stop that traditional remedy.\""}, {"id": "d", "text": "\"Your son can be one of the interpreters; family members are fine.\""}, {"id": "e", "text": "\"Would you prefer a same-gender caregiver?\""}]'::jsonb, '["a", "c", "d"]', '(a) Requires follow-up: believing one''s own culture is superior is ethnocentrism, which must be avoided. (c) Requires follow-up: forcing one''s own beliefs on patients is cultural imposition, which is never appropriate. (d) Requires follow-up: use certified interpreters only, never family members or children. (b) Appropriate: asking about patient preferences and spiritual practices is culturally competent care. (e) Appropriate: asking about same-gender caregiver requests is culturally competent care.', true),
  ('sexual', 36, 'A nurse at a community health fair is reviewing four clients'' risk histories. Which client is MOST important to encourage to get regular STI screening?', '[{"id": "a", "text": "A 30-year-old who has practiced abstinence for 5 years"}, {"id": "b", "text": "A 26-year-old with multiple partners who reports IV drug use"}, {"id": "c", "text": "A 34-year-old who completed the HPV vaccine series"}, {"id": "d", "text": "A 41-year-old who uses a copper IUD and checks strings monthly"}]'::jsonb, '["b"]', 'Regular STI screening is especially important for high-risk individuals, including those with multiple partners and IV drug use. Abstinence is 100% effective, and vaccination or an IUD does not identify a client as high-risk.', false),
  ('sexual', 37, 'A 20-year-old client who is sexually active asks the nurse whether any vaccines can lower her risk of STIs. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Metronidazole (Flagyl) before sex works like a vaccine.\""}, {"id": "b", "text": "\"No vaccines exist for STIs, so condoms are the only protection.\""}, {"id": "c", "text": "\"The HPV (Gardasil) and hepatitis B vaccines are recommended.\""}, {"id": "d", "text": "\"Only the HPV vaccine helps; hepatitis B is not an STI concern.\""}]'::jsonb, '["c"]', 'STI prevention teaching includes vaccinations for HPV (Gardasil) and hepatitis B. Metronidazole is a medication, not a vaccine, and saying no vaccines exist or that only HPV applies contradicts this teaching.', false),
  ('sexual', 38, 'A nurse is reviewing teaching with a couple considering permanent contraception. Which statements by the couple indicate a need for further teaching? Select all that apply.', '[{"id": "a", "text": "\"We will sign an informed consent before surgery.\""}, {"id": "b", "text": "\"Either option is a surgical procedure.\""}, {"id": "c", "text": "\"A vasectomy is not irreversible; it can be undone.\""}, {"id": "d", "text": "\"Tubal ligation is meant to be irreversible.\""}, {"id": "e", "text": "\"A tubal ligation will also protect us from STIs.\""}]'::jsonb, '["c", "e"]', '(c) Needs teaching: vasectomy and tubal ligation are irreversible. (e) Needs teaching: only condoms prevent STIs. (b) Correct statement: both permanent methods are surgical. (a) Correct statement: permanent methods require informed consent. (d) Correct statement: tubal ligation is irreversible.', true),
  ('sexual', 39, 'A 23-year-old client completing treatment for an STI asks, "Do I really have to tell my partner? I already took the medicine." Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Partner notification and treatment help prevent reinfection.\""}, {"id": "b", "text": "\"No; once you finish the medicine, you cannot be reinfected.\""}, {"id": "c", "text": "\"Only tell your partner if you have an active herpes outbreak.\""}, {"id": "d", "text": "\"Your partner is protected if you used a hormonal method.\""}]'::jsonb, '["a"]', 'Partner notification and treatment are part of STI prevention because they prevent reinfection. Finishing treatment does not protect against reinfection from an untreated partner, and hormonal methods do not prevent STIs.', false),
  ('sexual', 40, 'A 29-year-old client with genital herpes reports that painful lesions appeared yesterday. She says, "We''ll just use a condom this weekend." Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Condoms prevent all STI spread, so that plan is safe.\""}, {"id": "b", "text": "\"Using a diaphragm along with the condom will be safest.\""}, {"id": "c", "text": "\"That''s fine as long as your partner is not having symptoms.\""}, {"id": "d", "text": "\"Avoid sexual activity during an active herpes outbreak.\""}]'::jsonb, '["d"]', 'STI prevention teaching includes avoiding sexual activity during active herpes outbreaks. Condoms reduce but do not eliminate all STI risk, so a condom does not make sex safe during an outbreak.', false),
  ('sexual', 41, 'A nurse reviews STI teaching with a 30-year-old client prescribed metronidazole (Flagyl) who also has a history of herpes and a new IUD. Which statements by the client indicate a need for further teaching? Select all that apply.', '[{"id": "a", "text": "\"I''ll avoid alcohol while I take metronidazole.\""}, {"id": "b", "text": "\"Alcohol with Flagyl won''t cause a severe reaction.\""}, {"id": "c", "text": "\"Sexual activity during active herpes outbreaks is fine with condoms.\""}, {"id": "d", "text": "\"I''ll report fever, pain, or discharge after my IUD insertion.\""}, {"id": "e", "text": "\"I will check strings yearly, not monthly.\""}]'::jsonb, '["b", "c", "e"]', '(b) Needs teaching: avoid alcohol with metronidazole (Flagyl) because of a severe vomiting reaction. (c) Needs teaching: avoid sexual activity during active herpes outbreaks. (e) Needs teaching: IUD strings are checked monthly. (a) Correct statement: avoid alcohol with metronidazole. (d) Correct statement: after IUD insertion, report fever, pain, and discharge.', true),
  ('sexual', 42, 'A 25-year-old client is prescribed metronidazole (Flagyl) and says she is going to a wedding reception this weekend. Which teaching is the nurse''s PRIORITY?', '[{"id": "a", "text": "\"Take the medicine with the wedding meal to prevent nausea.\""}, {"id": "b", "text": "\"Use condoms at the reception, since Flagyl prevents pregnancy.\""}, {"id": "c", "text": "\"Stop the medicine on the day of the wedding and restart it the day after.\""}, {"id": "d", "text": "\"Avoid alcohol while taking metronidazole; it can cause severe vomiting.\""}]'::jsonb, '["d"]', 'Alcohol must be avoided with metronidazole (Flagyl) because it causes a severe vomiting reaction. Stopping the medicine is not the teaching, and only condoms prevent STIs; Flagyl is not a contraceptive.', false),
  ('sexual', 43, 'A 38-year-old client with no STIs says, "I don''t have any diseases, but I''ve felt down and isolated since my divorce." The nurse is assessing her sexual health. Which areas should the nurse include? Select all that apply.', '[{"id": "a", "text": "Absence of disease alone"}, {"id": "b", "text": "Emotional well-being"}, {"id": "c", "text": "Physical well-being"}, {"id": "d", "text": "Mental well-being"}, {"id": "e", "text": "Social well-being"}]'::jsonb, '["b", "c", "d", "e"]', 'Sexual health includes physical, emotional, mental, and social well-being related to sexuality, and it encompasses respectful, safe, and positive sexual experiences. (b), (c), (d), (e) Correct: each is part of sexual health. (a) Wrong: sexual health is not just the absence of disease.', true),
  ('sexual', 44, 'A 42-year-old client says, "My STI tests were negative, so my sexual health must be fine," but adds that she does not feel respected or safe in her relationship. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Negative tests mean your sexual health is fine, so there is nothing more to discuss.\""}, {"id": "b", "text": "\"Relationship concerns are not part of a sexual health visit.\""}, {"id": "c", "text": "\"Let''s repeat the STI tests to be sure there is no disease.\""}, {"id": "d", "text": "\"Sexual health also includes respectful, safe, and positive sexual experiences.\""}]'::jsonb, '["d"]', 'Sexual health is not just the absence of disease; it encompasses respectful, safe, and positive sexual experiences, so her concerns are part of sexual health. Negative tests address only disease.', false),
  ('sexual', 45, 'A 19-year-old client tells the nurse that the clinic schedules sexual health visits in a shared hallway and that she cannot get a referral for the services she needs. Which nursing action BEST reflects the advocate role?', '[{"id": "a", "text": "Provide accurate information about contraception and STIs"}, {"id": "b", "text": "Ask open-ended questions about her sexual activity"}, {"id": "c", "text": "Be affirming of her gender identity and orientation"}, {"id": "d", "text": "Ensure her privacy and access to appropriate services"}]'::jsonb, '["d"]', 'The advocate role is to ensure patient privacy and access to appropriate services. Providing information is the educator role, open-ended questioning is assessment, and affirming identities is the support role.', false),
  ('sexual', 46, 'A 33-year-old client who practices Islam is admitted for a gynecologic procedure and says modesty is very important to her. Which actions by the nurse are appropriate? Select all that apply.', '[{"id": "a", "text": "Honor her same-gender caregiver request"}, {"id": "b", "text": "Ask permission before touching her"}, {"id": "c", "text": "Ask about her spiritual practices"}, {"id": "d", "text": "Expose her fully to speed the exam"}, {"id": "e", "text": "Assume her husband makes all decisions"}]'::jsonb, '["a", "b", "c"]', '(a) Correct: same-gender caregiver is preferred, and asking about these requests is culturally competent care. (b) Correct: avoid touching without permission. (c) Correct: ask about patient preferences, including spiritual practices. (d) Wrong: modesty is important and exposure disregards it. (e) Wrong: the nurse avoids assumptions and assesses each patient individually.', true),
  ('sexual', 47, 'During an STI screening visit, a 60-year-old client who identifies as Asian American avoids eye contact while answering the nurse''s questions. Which interpretation by the nurse is MOST appropriate?', '[{"id": "a", "text": "The client is likely not being honest about her risks"}, {"id": "b", "text": "The client is not interested in the teaching being offered"}, {"id": "c", "text": "The client needs a family member present to interpret"}, {"id": "d", "text": "This may be a sign of respect; assess her individually"}]'::jsonb, '["d"]', 'Avoiding eye contact may be a sign of respect, and the nurse avoids assumptions and stereotypes by assessing each patient individually. Concluding she is dishonest or uninterested is an assumption, and family members are never used as interpreters.', false),
  ('sexual', 48, 'A 34-year-old Hispanic client who speaks fluent English tells the nurse she wants to talk with her family before choosing a contraception method. A float nurse has already requested a Spanish interpreter without asking her. Which action by the nurse is BEST?', '[{"id": "a", "text": "Respect family-centered decision-making and ask about her language preference"}, {"id": "b", "text": "Explain that contraception decisions should be made by the patient alone today"}, {"id": "c", "text": "Keep the interpreter because Hispanic patients need language support"}, {"id": "d", "text": "Ask her mother to decide so that the family''s elders are respected"}]'::jsonb, '["a"]', 'Hispanic culture often values family-centered decision-making and respect for elders, and the nurse avoids assuming language proficiency. Keeping the interpreter assumes her language needs, and having her mother decide replaces the patient''s own decision.', false),
  ('sexual', 49, 'A nurse in a reproductive health clinic reviews calls from clients using contraception. Which reports require IMMEDIATE follow-up? Select all that apply.', '[{"id": "a", "text": "Chest pain in a client taking hormonal pills"}, {"id": "b", "text": "A question about how to check IUD strings"}, {"id": "c", "text": "Fever and discharge 2 days after IUD insertion"}, {"id": "d", "text": "A request for condoms to prevent STIs"}, {"id": "e", "text": "Severe leg pain in a client using the patch"}]'::jsonb, '["a", "c", "e"]', '(a) Correct: chest pain is an ACHES warning sign of PE that must be reported immediately. (c) Correct: fever, pain, and discharge after IUD insertion are infection signs to report. (e) Correct: severe leg pain is an ACHES warning sign of DVT. (b) Wrong: string checks are routine monthly teaching. (d) Wrong: a condom request is STI prevention, not a warning sign.', true),
  ('sexual', 50, 'A 29-year-old client who is a Jehovah''s Witness is alert, oriented, and hemorrhaging after a gynecologic procedure. She refuses blood transfusions. Which actions by the nurse are appropriate? Select all that apply.', '[{"id": "a", "text": "Transfuse because this is an emergency"}, {"id": "b", "text": "Have her spouse consent to a transfusion"}, {"id": "c", "text": "Document her refusal"}, {"id": "d", "text": "Respect her refusal of blood transfusions"}, {"id": "e", "text": "Tell her the refusal is not valid now"}]'::jsonb, '["c", "d"]', '(d) Correct: a Jehovah''s Witness''s refusal of blood transfusions must be respected even in emergencies when the patient is a competent adult. (c) Correct: the nurse documents the refusal. (a) Wrong: an emergency does not override a competent adult''s refusal. (b) Wrong: a family member cannot override her decision. (e) Wrong: the refusal must be respected even in emergencies.', true),
  ('priapism', 1, 'A 9-year-old boy with sickle cell disease is brought to the emergency department by his mother. He has had a painful erection for 5 hours that began without any sexual arousal. What is the nurse''s PRIORITY action?', '[{"id": "a", "text": "Apply ice packs and pressure to the perineum, then reassess in one hour"}, {"id": "b", "text": "Call the provider STAT because this is a urological emergency"}, {"id": "c", "text": "Reassure the mother that this often resolves without emergency treatment"}, {"id": "d", "text": "Arrange observation and follow-up with the urology clinic next week"}]'::jsonb, '["b"]', 'Sickle cell disease plus priapism is a priority emergency, and a painful erection lasting more than 4 hours means calling the provider STAT. Ice packs, perineal pressure, and observation are measures for the non-ischemic type, not for a painful erection in a child with sickle cell disease.', false),
  ('priapism', 2, 'A 46-year-old client who takes trazodone calls the nurse advice line at 0330. He reports a painful erection that began at 2300 without sexual stimulation and asks what he should do. Which instruction by the nurse is BEST?', '[{"id": "a", "text": "\"Wait until it has lasted 6 hours, then call back if it has not resolved.\""}, {"id": "b", "text": "\"Skip tonight''s trazodone dose and call back in the morning if the erection has not gone away.\""}, {"id": "c", "text": "\"Seek emergency treatment now; delayed treatment can cause permanent erectile dysfunction.\""}, {"id": "d", "text": "\"A painful erection is usually the high-flow type, so it is safe to monitor it at home.\""}]'::jsonb, '["c"]', 'From 2300 to 0330 is 4.5 hours, so this painful erection without sexual stimulation now exceeds 4 hours and is a urological emergency; time = tissue, and delayed treatment causes permanent erectile dysfunction. A painful erection points to the ischemic type, not the usually painless high-flow type.', false),
  ('priapism', 3, 'A 27-year-old client arrives at the emergency department with an erection that has persisted for 5 hours without sexual arousal. His cavernosal blood gas is hypoxic and acidotic. Which additional findings would the nurse expect with this type of priapism? Select all that apply.', '[{"id": "a", "text": "Painful, rigid erection"}, {"id": "b", "text": "Usually painless or less painful erection"}, {"id": "c", "text": "Rigid shaft but soft glans"}, {"id": "d", "text": "Unregulated arterial blood flow on Doppler"}, {"id": "e", "text": "Blood trapped in corpora cavernosa with no outflow"}]'::jsonb, '["a", "c", "e"]', 'A hypoxic, acidotic cavernosal blood gas indicates ischemic (low-flow) priapism. (a) Correct: the ischemic type is a painful, rigid erection. (c) Correct: a rigid shaft but soft glans is a sign of priapism. (e) Correct: in the ischemic type blood is trapped in the corpora cavernosa with no outflow. (b) Wrong: usually painless or less painful describes the non-ischemic (high-flow) type. (d) Wrong: unregulated arterial blood flow is the non-ischemic mechanism.', true),
  ('priapism', 4, 'The emergency department triage nurse receives four clients at the same time. Which client should the nurse see FIRST?', '[{"id": "a", "text": "A 30-year-old with a less painful erection for 6 hours after a straddle injury to the perineum"}, {"id": "b", "text": "A 58-year-old who took sildenafil 1 hour ago and has had an erection for 45 minutes"}, {"id": "c", "text": "A 41-year-old whose painful erection of 3 hours resolved on its own before arrival"}, {"id": "d", "text": "A 12-year-old with sickle cell disease and a painful, rigid erection for 4.5 hours"}]'::jsonb, '["d"]', 'Sickle cell plus priapism is a priority emergency, and a painful, rigid erection over 4 hours is the ischemic type with tissue hypoxia. The less painful erection after trauma fits the non-ischemic type, which is not immediately life-threatening.', false),
  ('priapism', 5, 'A 44-year-old client with a spinal cord injury has had an erection for 6 hours that began without sexual stimulation. The cavernosal blood gas shows low O₂ and low pH. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Blood is trapped in the corpora cavernosa, and tissue hypoxia makes this an emergency"}, {"id": "b", "text": "Unregulated arterial inflow is present, so the erection is not immediately life-threatening"}, {"id": "c", "text": "This is the high-flow type, which often resolves without emergency treatment"}, {"id": "d", "text": "These values are expected with spinal cord injury and need only observation and follow-up"}]'::jsonb, '["a"]', 'A cavernosal blood gas with low O₂ and low pH means ischemic priapism: blood is trapped in the corpora cavernosa and tissue hypoxia is a medical emergency. Unregulated arterial flow that is not immediately life-threatening describes the non-ischemic type, which would not produce hypoxic, acidotic blood.', false),
  ('priapism', 6, 'A pediatric nurse is completing the admission history for a 13-year-old client with a painful erection that has lasted 5 hours. Which history findings are risk factors for this condition? Select all that apply.', '[{"id": "a", "text": "Sexual arousal shortly before the erection began"}, {"id": "b", "text": "Sickle cell disease diagnosed in infancy"}, {"id": "c", "text": "Recent intracavernosal phenylephrine injection"}, {"id": "d", "text": "Leukemia with hyperviscosity"}, {"id": "e", "text": "Trauma to the genitals or pelvis"}]'::jsonb, '["b", "d", "e"]', '(b) Correct: sickle cell disease is the most common cause in children. (d) Correct: leukemia causes priapism through hyperviscosity. (e) Correct: trauma to the genitals or pelvis is a listed cause. (a) Wrong: priapism occurs without sexual stimulation; no sexual arousal is involved. (c) Wrong: intracavernosal phenylephrine is a treatment for ischemic priapism, not a cause.', true),
  ('priapism', 7, 'A 38-year-old client with ischemic priapism lasting 6 hours has just had aspiration of blood from the corpora cavernosa using a sterile needle, but the erection persists. Which treatment does the nurse anticipate NEXT?', '[{"id": "a", "text": "Preparation for an emergency surgical shunt"}, {"id": "b", "text": "Intracavernosal injection of phenylephrine"}, {"id": "c", "text": "Ice packs and pressure to the perineum"}, {"id": "d", "text": "Observation with a penile Doppler ultrasound"}]'::jsonb, '["b"]', 'Treatment of ischemic priapism is aspiration plus intracavernosal phenylephrine injection; a surgical shunt is used only if the erection is unresponsive to both. Ice packs and perineal pressure are measures for the non-ischemic type.', false),
  ('priapism', 8, 'A 17-year-old client with sickle cell disease had a painful erection for 5 hours. One hour after aspiration and an intracavernosal phenylephrine injection, the shaft remains rigid and painful. Which action should the nurse take NEXT?', '[{"id": "a", "text": "Apply ice packs and perineal pressure and reassess in 4 hours"}, {"id": "b", "text": "Explain that the erection often resolves without further treatment"}, {"id": "c", "text": "Notify the provider and prepare the client for a surgical shunt"}, {"id": "d", "text": "Discharge the client with observation and follow-up instructions"}]'::jsonb, '["c"]', 'A surgical shunt is indicated when ischemic priapism is unresponsive to aspiration and phenylephrine, and time = tissue. Spontaneous resolution, ice packs, and observation apply to the non-ischemic type, not to a persistent painful, rigid erection.', false),
  ('priapism', 9, 'A 52-year-old client who takes trazodone for depression is being discharged after treatment of a painful erection that lasted 7 hours. Which statements by the client indicate understanding of the discharge teaching? Select all that apply.', '[{"id": "a", "text": "\"Because no sexual arousal was involved, it was not dangerous.\""}, {"id": "b", "text": "\"My trazodone may be a possible cause of what happened.\""}, {"id": "c", "text": "\"Painful erections are the type that resolves without treatment.\""}, {"id": "d", "text": "\"Delayed treatment can cause permanent erectile dysfunction.\""}, {"id": "e", "text": "\"If it happens again, I can wait 8 hours before seeking care.\""}]'::jsonb, '["b", "d"]', '(b) Correct: trazodone is a possible cause of priapism. (d) Correct: time = tissue; delayed treatment causes permanent erectile dysfunction. (a) Wrong: priapism occurs with no sexual arousal involved, and it is still an emergency. (c) Wrong: the ischemic type is painful; it is the non-ischemic type that often resolves without emergency treatment. (e) Wrong: an erection lasting more than 4 hours is a urological emergency, so waiting 8 hours delays treatment.', true),
  ('priapism', 10, 'A 33-year-old client has had an erection for 5 hours after falling onto a bicycle crossbar. The provider orders a penile Doppler ultrasound, and the client asks what the test will do. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"It assesses blood flow in the penis to help determine the type of priapism.\""}, {"id": "b", "text": "\"It measures oxygen and pH in the trapped blood to show tissue hypoxia.\""}, {"id": "c", "text": "\"It removes trapped blood from the corpora cavernosa to relieve the erection.\""}, {"id": "d", "text": "\"It delivers a vasoconstrictor into the penis so the erection will go down.\""}]'::jsonb, '["a"]', 'A penile Doppler ultrasound assesses blood flow, which helps distinguish the ischemic and non-ischemic types. Measuring low O₂ and low pH is the cavernosal blood gas, removing blood is aspiration, and the vasoconstrictor is intracavernosal phenylephrine.', false),
  ('priapism', 11, 'A 35-year-old client has had an erection for 5 hours after a fall onto a fence rail and says it is only mildly uncomfortable. His cavernosal blood gas shows low O₂ and low pH. Which action is the nurse''s PRIORITY?', '[{"id": "a", "text": "Plan observation and follow-up because trauma suggests the high-flow type"}, {"id": "b", "text": "Apply ice packs and pressure to the perineum as the first treatment"}, {"id": "c", "text": "Reassure him that a less painful erection is not immediately life-threatening"}, {"id": "d", "text": "Prepare for aspiration and phenylephrine injection as an emergency"}]'::jsonb, '["d"]', 'Low O₂ and low pH on the cavernosal blood gas mean the erection is ischemic, which is an emergency treated with aspiration plus phenylephrine injection, regardless of the trauma history. Trauma and less pain suggest the non-ischemic type, but the blood gas determines ischemia.', false),
  ('priapism', 12, 'A 10-year-old client with sickle cell disease has had a painful erection for 6 hours, and the cavernosal blood gas is hypoxic and acidotic. Which treatments does the nurse anticipate for this client? Select all that apply.', '[{"id": "a", "text": "Ice packs and pressure to the perineum as the main treatment"}, {"id": "b", "text": "Aspiration of blood from corpora cavernosa using sterile needle"}, {"id": "c", "text": "Observation and follow-up until it resolves on its own"}, {"id": "d", "text": "Intracavernosal injection of phenylephrine"}, {"id": "e", "text": "Surgical shunt before any aspiration is attempted"}]'::jsonb, '["b", "d"]', 'A hypoxic, acidotic blood gas means ischemic priapism, an emergency. (b) Correct: aspiration of blood from the corpora cavernosa with a sterile needle is a treatment. (d) Correct: intracavernosal phenylephrine injection is a treatment. (e) Wrong: a surgical shunt is used only if the erection is unresponsive to aspiration and phenylephrine, not before them. (a) Wrong: ice packs and perineal pressure are for the non-ischemic type. (c) Wrong: observation and follow-up are for the non-ischemic type, which often resolves without emergency treatment.', true),
  ('priapism', 13, 'A 23-year-old client reports an erection for 6 hours that began after he fell and struck his perineum. He describes it as nearly painless, and the Doppler ultrasound shows unregulated arterial blood flow. Which statement about his condition is MOST accurate?', '[{"id": "a", "text": "Blood is trapped in the corpora cavernosa, causing tissue hypoxia"}, {"id": "b", "text": "It is not immediately life-threatening and often resolves on its own"}, {"id": "c", "text": "It is the more common type and requires aspiration with a sterile needle"}, {"id": "d", "text": "It requires a surgical shunt because it has already lasted more than 4 hours"}]'::jsonb, '["b"]', 'A nearly painless erection after trauma with unregulated arterial blood flow is non-ischemic (high-flow) priapism, which is not immediately life-threatening and often resolves without emergency treatment. Trapped blood with tissue hypoxia describes the ischemic type.', false),
  ('priapism', 14, 'A 29-year-old client has an erection for 5 hours after a pelvic injury. It is usually painless, the Doppler ultrasound shows unregulated arterial blood flow, and the cavernosal blood gas is not hypoxic. Which plan of care is MOST likely?', '[{"id": "a", "text": "Aspiration of the corpora cavernosa followed by phenylephrine"}, {"id": "b", "text": "Emergency surgical shunt to restore outflow from the penis"}, {"id": "c", "text": "Ice packs, pressure to the perineum, and observation and follow-up"}, {"id": "d", "text": "Intracavernosal phenylephrine injection repeated until it resolves"}]'::jsonb, '["c"]', 'These findings describe non-ischemic (high-flow) priapism, which is managed with ice packs, pressure to the perineum, and observation and follow-up. Aspiration, phenylephrine, and a surgical shunt are treatments for the ischemic type.', false),
  ('priapism', 15, 'A nurse in an urgent care center reviews the findings of several clients. Which findings require IMMEDIATE follow-up with the provider? Select all that apply.', '[{"id": "a", "text": "Painful erection for 4.25 hours in a client taking trazodone"}, {"id": "b", "text": "Painful erection lasting 5 hours in a child with sickle cell disease"}, {"id": "c", "text": "Painful, rigid erection for 4.5 hours in a client taking risperidone"}, {"id": "d", "text": "Painless erection after trauma that resolved with ice packs"}, {"id": "e", "text": "Cavernosal blood gas that is hypoxic and acidotic"}]'::jsonb, '["a", "b", "c", "e"]', '(a) Correct: a painful erection over 4 hours means call the provider STAT, and trazodone is a possible cause. (b) Correct: sickle cell plus priapism is a priority emergency. (c) Correct: a painful erection over 4 hours means call the provider STAT, and antipsychotics (risperidone) are a possible cause. (e) Correct: a hypoxic, acidotic blood gas means ischemia, a medical emergency. (d) Wrong: a painless erection after trauma that resolved fits the non-ischemic type, which often resolves without emergency treatment.', true),
  ('priapism', 16, 'The partner of a 40-year-old client with a painful, rigid erection lasting 5 hours asks, "Why can''t we just go home and wait for it to go away?" Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Most erections like this resolve with observation and follow-up, so waiting is reasonable.\""}, {"id": "b", "text": "\"The erection comes from too much arterial inflow, which is not immediately dangerous to the tissue.\""}, {"id": "c", "text": "\"Blood is trapped with no outflow, and delayed treatment can cause permanent erectile dysfunction.\""}, {"id": "d", "text": "\"It is safest to wait until the erection has lasted 8 hours before starting treatment.\""}]'::jsonb, '["c"]', 'A painful, rigid erection is the ischemic type: blood is trapped with no outflow, and time = tissue, so delayed treatment causes permanent erectile dysfunction. Arterial inflow that is not immediately dangerous describes the non-ischemic type.', false),
  ('priapism', 17, 'A charge nurse observes a newly hired nurse triaging a 26-year-old client who has had a painful erection for 5 hours without sexual stimulation. Which action by the new nurse requires IMMEDIATE intervention by the charge nurse?', '[{"id": "a", "text": "Preparing a sterile needle for aspiration of the corpora cavernosa"}, {"id": "b", "text": "Explaining that phenylephrine may be injected into the penis"}, {"id": "c", "text": "Reporting the hypoxic, acidotic blood gas result to the provider"}, {"id": "d", "text": "Telling the client the soft glans shows the erection is starting to resolve"}]'::jsonb, '["d"]', 'A rigid shaft but soft glans is a sign of priapism, not of resolution, and a painful erection lasting more than 4 hours is a urological emergency. Preparing for aspiration, explaining phenylephrine, and reporting a hypoxic blood gas are all appropriate.', false),
  ('priapism', 18, 'A 48-year-old client with a spinal cord injury presents with a painful erection that has lasted 5 hours. Which items in his history should the nurse identify as possible causes? Select all that apply.', '[{"id": "a", "text": "Trazodone (antidepressant) at bedtime"}, {"id": "b", "text": "Sildenafil (Viagra) last evening"}, {"id": "c", "text": "Phenylephrine (vasoconstrictor) injection"}, {"id": "d", "text": "Risperidone (an antipsychotic)"}, {"id": "e", "text": "Spinal cord injury from a fall"}]'::jsonb, '["a", "b", "d", "e"]', '(a) Correct: trazodone (an antidepressant) is a listed medication cause. (b) Correct: sildenafil (Viagra) is a listed medication cause. (d) Correct: antipsychotics such as risperidone are a listed cause. (e) Correct: spinal cord injury is a listed risk factor. (c) Wrong: intracavernosal phenylephrine is a treatment for ischemic priapism, not a cause.', true),
  ('priapism', 19, 'The mother of a 7-year-old boy with sickle cell disease asks the clinic nurse what she should do if her son ever develops a painful erection that will not go away. Which instruction is BEST?', '[{"id": "a", "text": "\"Treat a prolonged, painful erection as an emergency and get care right away.\""}, {"id": "b", "text": "\"Apply ice packs and pressure to the perineum and watch him at home overnight.\""}, {"id": "c", "text": "\"It usually resolves without treatment because it is often painless in children.\""}, {"id": "d", "text": "\"Call the provider only if the erection has lasted longer than 8 hours.\""}]'::jsonb, '["a"]', 'Sickle cell disease is the most common cause of priapism in children, and sickle cell plus priapism is a priority emergency; time = tissue. Ice packs, perineal pressure, and home observation are measures for the non-ischemic type.', false),
  ('priapism', 20, 'A 15-year-old client with sickle cell disease has had an erection for 5 hours. On assessment the nurse finds a rigid shaft but a soft glans, and the penis is tender. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "The soft glans shows the erection is resolving, so treatment can wait"}, {"id": "b", "text": "These are signs of priapism; it remains a urological emergency"}, {"id": "c", "text": "These findings indicate the high-flow type from unregulated arterial flow"}, {"id": "d", "text": "Tenderness suggests trauma, so ice packs and observation are needed"}]'::jsonb, '["b"]', 'A painful, tender penis with a rigid shaft but soft glans are signs of priapism, and in a client with sickle cell disease it is a priority emergency. A soft glans does not mean resolution; it is an expected sign.', false),
  ('priapism', 21, 'A 60-year-old client was treated for a painful erection that lasted 6 hours after he took sildenafil. Which statements by the client indicate a need for further teaching? Select all that apply.', '[{"id": "a", "text": "\"Sildenafil can be a possible cause of what happened to me.\""}, {"id": "b", "text": "\"A prolonged erection lasting 8 hours can be observed at home first.\""}, {"id": "c", "text": "\"A painless erection is the type that leads to permanent erectile dysfunction.\""}, {"id": "d", "text": "\"Waiting too long for treatment can cause permanent erectile dysfunction.\""}, {"id": "e", "text": "\"Ice packs are the treatment for a painful, rigid erection lasting 6 hours.\""}]'::jsonb, '["b", "c", "e"]', '(b) Needs teaching: an erection lasting more than 4 hours is a urological emergency; it should not be observed at home. (c) Needs teaching: the painful, rigid ischemic type causes tissue hypoxia and permanent erectile dysfunction; the painless type is not immediately life-threatening. (e) Needs teaching: ice packs are for the non-ischemic type; a painful, rigid erection needs aspiration and phenylephrine. (a) Correct statement: sildenafil is a possible cause. (d) Correct statement: delayed treatment causes permanent erectile dysfunction.', true),
  ('priapism', 22, 'A 31-year-old client with ischemic priapism received aspiration and an intracavernosal injection of phenylephrine. Which finding 30 minutes later requires IMMEDIATE follow-up by the nurse?', '[{"id": "a", "text": "The glans of the penis is soft to palpation"}, {"id": "b", "text": "The client reports the pain is much less than before"}, {"id": "c", "text": "The shaft remains rigid and the penis is still painful"}, {"id": "d", "text": "The client asks when his follow-up visit will be scheduled"}]'::jsonb, '["c"]', 'A shaft that remains rigid and painful after aspiration and phenylephrine means the erection is unresponsive, and a surgical shunt is used if unresponsive; time = tissue. A soft glans is expected even in priapism and does not indicate an emergency by itself.', false),
  ('priapism', 23, 'A nurse on an inpatient psychiatric unit is told by a 24-year-old client taking risperidone that he has had a painful erection since 0700 that started without sexual arousal. It is now 1130. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Hold the next risperidone dose and recheck the client in 1 hour"}, {"id": "b", "text": "Call the provider STAT to report a painful erection of 4.5 hours"}, {"id": "c", "text": "Offer ice packs and pressure to the perineum for comfort"}, {"id": "d", "text": "Document the finding and include it in the end-of-shift report"}]'::jsonb, '["b"]', 'From 0700 to 1130 is 4.5 hours; a painful erection lasting more than 4 hours means call the provider STAT, and antipsychotics such as risperidone are a possible cause. Holding the dose or using ice packs delays emergency treatment, and time = tissue.', false),
  ('priapism', 24, 'A nurse is caring for a 25-year-old client with a 5-hour erection that began without sexual stimulation. Which diagnostic measures does the nurse anticipate to determine the type of priapism? Select all that apply.', '[{"id": "a", "text": "History and physical exam"}, {"id": "b", "text": "Intracavernosal phenylephrine trial"}, {"id": "c", "text": "Cavernosal blood gas"}, {"id": "d", "text": "Ice pack trial to see if it resolves"}, {"id": "e", "text": "Penile Doppler ultrasound"}]'::jsonb, '["a", "c", "e"]', '(a) Correct: diagnosis begins with history and physical exam. (c) Correct: cavernosal blood gas determines ischemia (low O₂, low pH = ischemic). (e) Correct: penile Doppler ultrasound assesses blood flow. (b) Wrong: phenylephrine is a treatment for the ischemic type, not a diagnostic test. (d) Wrong: ice packs are a treatment for the non-ischemic type; delaying to see whether it resolves wastes time when time = tissue.', true),
  ('priapism', 25, 'A nursing student caring for a client with priapism states, "Most priapism comes from trauma, so it is usually not an emergency." Which response by the nurse BEST corrects the student?', '[{"id": "a", "text": "\"The ischemic, low-flow type is the most common, and it is a medical emergency.\""}, {"id": "b", "text": "\"Trauma causes the ischemic type, which is why it needs a surgical shunt first.\""}, {"id": "c", "text": "\"You are right; priapism often resolves without emergency treatment.\""}, {"id": "d", "text": "\"Only priapism in children with sickle cell disease is considered an emergency.\""}]'::jsonb, '["a"]', 'Ischemic (low-flow) priapism is the most common type and involves tissue hypoxia, a medical emergency. The type usually from trauma is non-ischemic (high-flow), which is rare.', false),
  ('priapism', 26, 'A 55-year-old client has had an erection for 6 hours that he describes as only mildly uncomfortable, and a cavernosal blood gas is drawn. Which result should the nurse report to the health care provider as confirming the ischemic type?', '[{"id": "a", "text": "High O₂ and high pH"}, {"id": "b", "text": "Low O₂ and high pH"}, {"id": "c", "text": "High O₂ and low pH"}, {"id": "d", "text": "Low O₂ and low pH"}]'::jsonb, '["d"]', 'The cavernosal blood gas determines ischemia: low O₂ and low pH means ischemic priapism, which is hypoxic and acidotic. Mild discomfort can suggest the less painful non-ischemic type, but the blood gas determines ischemia; a high O₂ or a high pH does not match the hypoxic, acidotic picture of trapped blood.', false),
  ('priapism', 27, 'A 14-year-old client with sickle cell disease has a painful erection that began 5 hours ago. Which actions should the emergency department nurse take? Select all that apply.', '[{"id": "a", "text": "Call the provider STAT"}, {"id": "b", "text": "Apply ice packs and wait for it to resolve"}, {"id": "c", "text": "Prepare a sterile needle for aspiration"}, {"id": "d", "text": "Advise observation and follow-up at home"}, {"id": "e", "text": "Anticipate a surgical shunt before aspiration"}]'::jsonb, '["a", "c"]', '(a) Correct: sickle cell plus priapism is a priority emergency, and a painful erection over 4 hours means call the provider STAT. (c) Correct: aspiration of blood from the corpora cavernosa with a sterile needle treats ischemic priapism. (e) Wrong: a surgical shunt is used only if unresponsive to aspiration and phenylephrine. (b) Wrong: ice packs are for the non-ischemic type; waiting delays treatment when time = tissue. (d) Wrong: observation and follow-up are for the non-ischemic type.', true),
  ('priapism', 28, 'A 34-year-old client was treated with aspiration and an intracavernosal phenylephrine injection for a painful erection lasting 6 hours. Which finding BEST indicates that treatment was effective?', '[{"id": "a", "text": "The glans of the penis is soft to palpation"}, {"id": "b", "text": "The shaft is no longer rigid or painful"}, {"id": "c", "text": "The cavernosal blood gas remains hypoxic and acidotic"}, {"id": "d", "text": "The client reports no sexual arousal during the episode"}]'::jsonb, '["b"]', 'The ischemic type is a painful, rigid erection, so a shaft that is no longer rigid or painful shows effective treatment. A soft glans is present even during priapism (rigid shaft but soft glans), so it does not show resolution.', false),
  ('priapism', 29, 'A 14-year-old client receiving care for leukemia reports a painful erection for 5 hours. His father says, "This must just be embarrassing for him; it will pass." Which response by the nurse is MOST appropriate?', '[{"id": "a", "text": "\"Leukemia can cause this through hyperviscosity, and it needs emergency treatment now.\""}, {"id": "b", "text": "\"It will usually pass on its own with ice packs and pressure to the perineum at home.\""}, {"id": "c", "text": "\"This is the high-flow type, which is not immediately life-threatening.\""}, {"id": "d", "text": "\"We can wait to call the provider until it has lasted 8 hours.\""}]'::jsonb, '["a"]', 'Leukemia causes priapism through hyperviscosity, and a painful erection over 4 hours means calling the provider STAT because delayed treatment causes permanent erectile dysfunction. Ice packs and observation apply to the non-ischemic type, which is usually painless.', false),
  ('priapism', 30, 'A 22-year-old client fell onto a metal bar 2 days ago and now has an erection lasting 6 hours. Which findings would support that this is the non-ischemic type? Select all that apply.', '[{"id": "a", "text": "Usually painless or less painful erection"}, {"id": "b", "text": "Cavernosal blood gas hypoxic and acidotic"}, {"id": "c", "text": "Unregulated arterial blood flow on Doppler"}, {"id": "d", "text": "Blood trapped in corpora cavernosa with no outflow"}, {"id": "e", "text": "Painful, rigid erection with tissue hypoxia"}]'::jsonb, '["a", "c"]', '(a) Correct: the non-ischemic (high-flow) type is usually painless or less painful. (c) Correct: it results from unregulated arterial blood flow, usually from trauma, which the Doppler ultrasound assesses. (b) Wrong: a hypoxic, acidotic blood gas means the ischemic type. (d) Wrong: trapped blood with no outflow is the ischemic type. (e) Wrong: a painful, rigid erection with tissue hypoxia is the ischemic type.', true),
  ('priapism', 31, 'A nurse on a spinal cord injury unit is told by an unlicensed assistive personnel (UAP) that a 39-year-old client has had an erection since the start of the shift, about 5 hours ago, without any stimulation. What is the nurse''s FIRST action?', '[{"id": "a", "text": "Tell the UAP to apply ice packs and pressure to the perineum"}, {"id": "b", "text": "Instruct the UAP to recheck the client at the end of the shift"}, {"id": "c", "text": "Document the finding as an expected effect of spinal cord injury"}, {"id": "d", "text": "Assess the client and call the provider STAT"}]'::jsonb, '["d"]', 'Spinal cord injury is a risk factor for priapism, and an erection lasting more than 4 hours without sexual stimulation is a urological emergency requiring the provider STAT. Ice packs and delayed rechecks are not appropriate for a probable emergency; time = tissue.', false),
  ('priapism', 32, 'A 37-year-old client reports a painful erection that began at 2215 without sexual stimulation. It is now 0145, and he is anxious about whether he has priapism. Which statement by the nurse is MOST accurate?', '[{"id": "a", "text": "\"You have priapism now; we will prepare for a surgical shunt.\""}, {"id": "b", "text": "\"Priapism is defined by 2 hours, so this is already an emergency.\""}, {"id": "c", "text": "\"It is 3.5 hours now; priapism is an erection lasting more than 4 hours.\""}, {"id": "d", "text": "\"A painful erection is never priapism unless genital or pelvic trauma is present.\""}]'::jsonb, '["c"]', 'From 2215 to 0145 is 3.5 hours, and priapism is a prolonged, painful erection lasting more than 4 hours without sexual stimulation. A surgical shunt is reserved for ischemic priapism unresponsive to aspiration and phenylephrine.', false),
  ('priapism', 33, 'The parent of an 8-year-old boy with sickle cell disease has received teaching about priapism. Which statements by the parent indicate understanding? Select all that apply.', '[{"id": "a", "text": "\"In children, this happens mostly after trauma to the pelvis.\""}, {"id": "b", "text": "\"A painful erection that will not go down is an emergency for him.\""}, {"id": "c", "text": "\"I should use ice packs at home and wait until morning first.\""}, {"id": "d", "text": "\"Waiting too long could leave him with permanent erectile dysfunction.\""}, {"id": "e", "text": "\"It only happens when there is sexual arousal, so it is unlikely in a child.\""}]'::jsonb, '["b", "d"]', '(a) Wrong: trauma is a cause, but sickle cell disease is the most common cause in children. (b) Correct: sickle cell plus priapism is a priority emergency. (d) Correct: time = tissue; delayed treatment leads to permanent erectile dysfunction. (c) Wrong: ice packs and observation are for the non-ischemic type and waiting delays emergency treatment. (e) Wrong: priapism occurs without sexual stimulation; no sexual arousal is involved.', true),
  ('priapism', 34, 'A nurse reviews the history of a 47-year-old client with a painful erection lasting 5 hours. Which information is MOST important for the nurse to report as a possible cause?', '[{"id": "a", "text": "He had sexual stimulation the evening before the erection began"}, {"id": "b", "text": "He used ice packs at home for an hour before he arrived"}, {"id": "c", "text": "He started taking trazodone for depression last week"}, {"id": "d", "text": "He had a normal penile Doppler ultrasound two years ago"}]'::jsonb, '["c"]', 'Trazodone (an antidepressant) is a possible medication cause of priapism. Priapism occurs without sexual stimulation, so sexual activity the evening before does not explain an erection that began without arousal.', false),
  ('priapism', 35, 'A 42-year-old client with a 7-hour painful erection is scheduled for aspiration. He asks, "What will happen if this isn''t fixed?" Which response by the nurse is BEST?', '[{"id": "a", "text": "\"The erection will often resolve on its own without any emergency treatment.\""}, {"id": "b", "text": "\"Without treatment, ischemia leads to permanent erectile dysfunction.\""}, {"id": "c", "text": "\"Without treatment, it will become the less painful high-flow type.\""}, {"id": "d", "text": "\"Without treatment, the glans will become rigid like the shaft.\""}]'::jsonb, '["b"]', 'Priapism is a urological emergency because ischemia leads to permanent erectile dysfunction if untreated. Spontaneous resolution without emergency treatment describes the non-ischemic type, not a painful 7-hour erection.', false),
  ('priapism', 36, 'A nurse is preparing a teaching plan for a 30-year-old client whose priapism was found to be non-ischemic after a perineal injury. Which interventions should the nurse include? Select all that apply.', '[{"id": "a", "text": "Ice packs and pressure to the perineum"}, {"id": "b", "text": "Repeat aspiration with a sterile needle"}, {"id": "c", "text": "Observation and follow-up"}, {"id": "d", "text": "Daily intracavernosal phenylephrine"}, {"id": "e", "text": "Surgical shunt to restore outflow"}]'::jsonb, '["a", "c"]', '(a) Correct: ice packs and pressure to the perineum are used for non-ischemic priapism. (c) Correct: observation and follow-up are part of non-ischemic management because it often resolves without emergency treatment. (b), (d), (e) Wrong: aspiration, intracavernosal phenylephrine, and a surgical shunt are treatments for the ischemic type.', true),
  ('priapism', 37, 'A 19-year-old client with sickle cell disease and a 32-year-old client with non-ischemic priapism after pelvic trauma both arrive with erections lasting 5 hours. Which explanation BEST supports seeing the client with sickle cell disease FIRST?', '[{"id": "a", "text": "Sickle cell disease causes unregulated arterial blood flow that resolves on its own"}, {"id": "b", "text": "Sickle cell plus priapism is a priority emergency with risk of tissue hypoxia"}, {"id": "c", "text": "The client with trauma has the most common type and can safely be observed"}, {"id": "d", "text": "Clients with sickle cell disease have a painless erection that hides the danger"}]'::jsonb, '["b"]', 'Sickle cell plus priapism is a priority emergency, and the ischemic type involves tissue hypoxia. Non-ischemic priapism after trauma is rare and not immediately life-threatening, so it is not the most common type.', false),
  ('priapism', 38, 'A 50-year-old client with ischemic priapism asks why the provider will inject medicine directly into his penis. The nurse explains that phenylephrine is given by intracavernosal injection. Which statement by the client indicates understanding?', '[{"id": "a", "text": "\"The injection is a vasoconstrictor used along with aspiration to treat this.\""}, {"id": "b", "text": "\"The injection is followed by ice packs and perineal pressure as the main treatment.\""}, {"id": "c", "text": "\"The injection is only given if a surgical shunt does not work first.\""}, {"id": "d", "text": "\"The injection is a test that measures blood flow in my penis.\""}]'::jsonb, '["a"]', 'Intracavernosal phenylephrine is a vasoconstrictor, and treatment of ischemic priapism is aspiration plus phenylephrine injection; a shunt is used only if these fail. Measuring blood flow is the penile Doppler ultrasound.', false),
  ('priapism', 39, 'A nurse is triaging four clients with prolonged erections. Which clients have findings consistent with ischemic priapism? Select all that apply.', '[{"id": "a", "text": "A client with a painful, rigid erection for 5 hours"}, {"id": "b", "text": "A client with a tender penis, rigid shaft, and soft glans"}, {"id": "c", "text": "A client with a painless erection after a straddle injury"}, {"id": "d", "text": "A client whose cavernosal gas shows low O₂ and low pH"}, {"id": "e", "text": "A client with unregulated arterial flow on Doppler"}]'::jsonb, '["a", "b", "d"]', '(a) Correct: the ischemic type is painful and rigid. (b) Correct: a painful, tender penis with a rigid shaft but soft glans are signs of priapism and fit the painful ischemic type. (d) Correct: low O₂ and low pH = ischemic. (c) Wrong: a painless erection after trauma fits the non-ischemic type. (e) Wrong: unregulated arterial blood flow is the non-ischemic mechanism.', true),
  ('priapism', 40, 'At 0200, a nurse advice line receives four calls from adult clients. Each describes an erection that has not gone away. Which caller''s report meets the definition of priapism and requires the provider STAT, making it the call to return FIRST?', '[{"id": "a", "text": "A painful erection that began at 2230 without sexual stimulation"}, {"id": "b", "text": "A painful erection that began at 2140 without sexual stimulation"}, {"id": "c", "text": "A painful erection that began at 2200 and resolved at 0130"}, {"id": "d", "text": "A painful erection that began at 2330 after taking sildenafil"}]'::jsonb, '["b"]', 'From 2140 to 0200 is 4 hours 20 minutes; priapism is a prolonged, painful erection lasting more than 4 hours without sexual stimulation, and a painful erection over 4 hours means calling the provider STAT. The erection that began at 2230 has lasted 3.5 hours, the one from 2200 resolved after 3.5 hours, and the sildenafil caller''s has lasted 2.5 hours.', false),
  ('priapism', 41, 'A nurse is reviewing the plan of care for a 36-year-old client admitted with priapism. The client has a painful, rigid erection and a hypoxic, acidotic cavernosal blood gas. Which order requires follow-up with the provider?', '[{"id": "a", "text": "Prepare a sterile needle for aspiration of the corpora cavernosa"}, {"id": "b", "text": "Intracavernosal injection of phenylephrine"}, {"id": "c", "text": "Ice packs and observation with follow-up as the only treatment"}, {"id": "d", "text": "Notify surgery for a shunt if unresponsive to aspiration"}]'::jsonb, '["c"]', 'Ice packs and observation are measures for non-ischemic priapism; a painful, rigid erection with a hypoxic, acidotic blood gas is the ischemic type, which is an emergency treated with aspiration plus phenylephrine, and a shunt if unresponsive.', false),
  ('priapism', 42, 'A 45-year-old client is admitted with ischemic priapism that has lasted 8 hours. Which statements explain why this is a urological emergency? Select all that apply.', '[{"id": "a", "text": "Blood is trapped in the corpora cavernosa with no outflow"}, {"id": "b", "text": "Tissue hypoxia is a medical emergency"}, {"id": "c", "text": "Unregulated arterial flow will damage the glans"}, {"id": "d", "text": "Ischemia leads to permanent erectile dysfunction if untreated"}, {"id": "e", "text": "Time = tissue, so delayed treatment has lasting effects"}]'::jsonb, '["a", "b", "d", "e"]', '(a) Correct: in ischemic priapism blood is trapped in the corpora cavernosa with no outflow. (b) Correct: the resulting tissue hypoxia is a medical emergency. (d) Correct: ischemia leads to permanent erectile dysfunction if untreated. (e) Correct: time = tissue; delayed treatment means permanent erectile dysfunction. (c) Wrong: unregulated arterial blood flow is the non-ischemic mechanism, which is not immediately life-threatening.', true),
  ('priapism', 43, 'A 28-year-old client with non-ischemic priapism after a pelvic injury is being discharged with ice packs and pressure to the perineum. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I will keep my follow-up appointment for observation.\""}, {"id": "b", "text": "\"This type is not immediately life-threatening.\""}, {"id": "c", "text": "\"This type often resolves without emergency treatment.\""}, {"id": "d", "text": "\"I will need a surgical shunt if it lasts 1 more day.\""}]'::jsonb, '["d"]', 'Non-ischemic priapism is managed with ice packs, perineal pressure, and observation and follow-up; it is not immediately life-threatening and often resolves. A surgical shunt is for ischemic priapism that is unresponsive to aspiration and phenylephrine.', false),
  ('priapism', 44, 'A home health nurse visits a 33-year-old client with sickle cell disease who mentions a painful erection that began 4.5 hours ago. He is embarrassed and asks the nurse not to tell anyone. Which action is the nurse''s PRIORITY?', '[{"id": "a", "text": "Respect his request for privacy and suggest ice packs and pressure to the perineum"}, {"id": "b", "text": "Call the provider STAT, explaining delayed treatment can cause permanent damage"}, {"id": "c", "text": "Schedule a clinic visit for later in the week for observation and follow-up"}, {"id": "d", "text": "Teach him that sickle cell disease is the most common cause in children"}]'::jsonb, '["b"]', 'Sickle cell plus priapism is a priority emergency, a painful erection over 4 hours requires the provider STAT, and time = tissue. Ice packs and delayed follow-up are measures for the non-ischemic type and would delay emergency treatment.', false),
  ('priapism', 45, 'A nurse is teaching a group of clients who take medications for depression, erectile dysfunction, or psychosis. Which medications should the nurse identify as possible causes of priapism? Select all that apply.', '[{"id": "a", "text": "Trazodone"}, {"id": "b", "text": "Phenylephrine"}, {"id": "c", "text": "Sildenafil (Viagra)"}, {"id": "d", "text": "Risperidone"}, {"id": "e", "text": "A vasoconstrictor"}]'::jsonb, '["a", "c", "d"]', '(a) Correct: trazodone (an antidepressant) is a possible cause. (c) Correct: sildenafil (Viagra), an erectile dysfunction drug, is a possible cause. (d) Correct: antipsychotics such as risperidone are a possible cause. (b) Wrong: phenylephrine is the intracavernosal treatment for ischemic priapism. (e) Wrong: phenylephrine is a vasoconstrictor, used to treat priapism rather than cause it.', true),
  ('priapism', 46, 'Four clients with erections lasting 5 hours are waiting in the emergency department. After the client with sickle cell disease, which client should the nurse see NEXT?', '[{"id": "a", "text": "A 30-year-old with a usually painless erection after a groin injury"}, {"id": "b", "text": "A 25-year-old with unregulated arterial blood flow on Doppler"}, {"id": "c", "text": "A 45-year-old with a painful, rigid erection after taking trazodone"}, {"id": "d", "text": "A 35-year-old whose priapism is improving with ice packs"}]'::jsonb, '["c"]', 'A painful, rigid erection is the ischemic type with trapped blood and tissue hypoxia, and trazodone is a possible cause; a painful erection over 4 hours requires the provider STAT. The painless erection, unregulated arterial flow, and improvement with ice packs fit the non-ischemic type, which is not immediately life-threatening.', false),
  ('priapism', 47, 'A 13-year-old client with sickle cell disease and a 6-hour painful erection is being prepared for aspiration. His parent asks why the provider is drawing blood from the penis before treatment. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"The cavernosal blood gas determines whether ischemia is present.\""}, {"id": "b", "text": "\"The blood is tested to see whether he has sickle cell disease.\""}, {"id": "c", "text": "\"The sample shows whether the erection came from sexual arousal.\""}, {"id": "d", "text": "\"The blood is sent to measure how fast the arteries are flowing.\""}]'::jsonb, '["a"]', 'A cavernosal blood gas determines ischemia (low O₂ and low pH = ischemic). Blood flow is assessed by the penile Doppler ultrasound, not the blood gas.', false),
  ('priapism', 48, 'A nurse is caring for a 40-year-old client whose ischemic priapism has not responded to aspiration. Which nursing actions are appropriate at this time? Select all that apply.', '[{"id": "a", "text": "Anticipate intracavernosal phenylephrine"}, {"id": "b", "text": "Apply ice packs to the perineum and observe"}, {"id": "c", "text": "Prepare for a surgical shunt if still unresponsive"}, {"id": "d", "text": "Reassure him it often resolves on its own"}, {"id": "e", "text": "Explain that delayed treatment risks permanent erectile dysfunction"}]'::jsonb, '["a", "c", "e"]', '(a) Correct: treatment of ischemic priapism is aspiration plus phenylephrine injection. (c) Correct: a surgical shunt is used if unresponsive to aspiration and phenylephrine. (e) Correct: time = tissue; delayed treatment causes permanent erectile dysfunction. (b) Wrong: ice packs and perineal pressure are for the non-ischemic type. (d) Wrong: resolving without emergency treatment describes the non-ischemic type.', true),
  ('priapism', 49, 'A 27-year-old client is seen in clinic 1 day after a straddle injury to the groin. He asks whether this kind of injury could ever cause a prolonged erection. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "\"Yes; trauma can cause unregulated arterial blood flow and a high-flow erection.\""}, {"id": "b", "text": "\"No; priapism results only from medications such as trazodone or sildenafil.\""}, {"id": "c", "text": "\"Yes; trauma traps blood in the corpora cavernosa, which is the high-flow type.\""}, {"id": "d", "text": "\"No; an injury causes priapism only in children with sickle cell disease.\""}]'::jsonb, '["a"]', 'Trauma to the genitals or pelvis is a cause of priapism, and the non-ischemic (high-flow) type results from unregulated arterial blood flow, usually from trauma. Trapped blood in the corpora cavernosa is the ischemic (low-flow) type, not the high-flow type.', false),
  ('priapism', 50, 'A 21-year-old client with an erection for 5 hours reports that it started after a groin injury while playing soccer. Which assessment findings should the nurse report to the provider IMMEDIATELY? Select all that apply.', '[{"id": "a", "text": "The erection is painful and rigid"}, {"id": "b", "text": "The client has a history of sickle cell disease"}, {"id": "c", "text": "The client''s medications include trazodone"}, {"id": "d", "text": "The cavernosal blood gas is hypoxic and acidotic"}, {"id": "e", "text": "The Doppler shows unregulated arterial flow"}]'::jsonb, '["a", "b", "c", "d"]', '(a) Correct: a painful, rigid erection is the ischemic type, a medical emergency. (b) Correct: sickle cell plus priapism is a priority emergency. (c) Correct: trazodone is a possible cause and is part of the report. (d) Correct: a hypoxic, acidotic blood gas means ischemia. (e) Wrong: unregulated arterial flow is the non-ischemic mechanism and is not immediately life-threatening.', true),
  ('infertility', 1, 'A 34-year-old client reports that she and her partner have had regular, unprotected intercourse for 9 months without conceiving. She asks the nurse whether this means she is infertile. Which response by the nurse is BEST?', '[{"id": "a", "text": "Yes; 9 months of regular, unprotected intercourse meets the criteria."}, {"id": "b", "text": "Not yet; at your age it takes 18 months or more of regular, unprotected intercourse."}, {"id": "c", "text": "Not yet; at your age it takes 12 months of regular, unprotected intercourse."}, {"id": "d", "text": "Yes; it takes 6 months of regular, unprotected intercourse at any age."}]'::jsonb, '["c"]', 'For a client younger than 35, infertility is the inability to conceive after 12 months of regular, unprotected intercourse, so 9 months does not yet meet the criteria. The 6-month timeframe applies to clients 35 and older.', false),
  ('infertility', 2, 'A nurse is reviewing intake histories of female clients at a fertility clinic. Which clients meet the criteria for infertility? Select all that apply.', '[{"id": "a", "text": "A 35-year-old with 6 months of regular, unprotected intercourse and no conception"}, {"id": "b", "text": "A 38-year-old with 4 months of regular, unprotected intercourse and no conception"}, {"id": "c", "text": "A 33-year-old with 10 months of regular, unprotected intercourse and no conception"}, {"id": "d", "text": "A 29-year-old with 13 months of regular, unprotected intercourse and no conception"}, {"id": "e", "text": "A 36-year-old with 6 months of regular, unprotected intercourse and no conception"}]'::jsonb, '["a", "d", "e"]', 'Correct: clients 35 and older (age ≥35) meet the criteria after 6 months, so the 36-year-old and the 35-year-old at 6 months qualify; a client younger than 35 meets them after 12 months, so the 29-year-old at 13 months qualifies. Wrong: the 33-year-old has not reached 12 months, and the 38-year-old has not reached 6 months.', true),
  ('infertility', 3, 'A 37-year-old client and her partner have had regular, unprotected intercourse for 7 months without conceiving. She asks whether they should keep trying before seeking help. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Begin a full assessment of both partners now."}, {"id": "b", "text": "Begin a full assessment of the female partner because of her age."}, {"id": "c", "text": "Start clomiphene citrate before any testing is completed."}, {"id": "d", "text": "Advise the couple to keep trying until 12 months have passed."}]'::jsonb, '["a"]', 'At age ≥35, infertility is defined after 6 months, so this couple already meets the criteria, and the workup always starts with a full assessment of both partners. Waiting until 12 months applies only to clients younger than 35, and treatment should not begin before assessment.', false),
  ('infertility', 4, 'A 31-year-old client with a history of pelvic inflammatory disease (PID) from untreated chlamydia has not conceived after 14 months. Her ovulation testing and her partner''s semen analysis are normal. Which diagnostic test is MOST important to evaluate the likely cause?', '[{"id": "a", "text": "Pelvic ultrasound"}, {"id": "b", "text": "Hysterosalpingogram (HSG)"}, {"id": "c", "text": "Endometrial biopsy"}, {"id": "d", "text": "Hormone levels (FSH, LH, TSH)"}]'::jsonb, '["b"]', 'PID from chlamydia/gonorrhea is a common cause of blocked tubes, and the HSG is the dye test that checks fallopian tube patency. An endometrial biopsy assesses the uterine lining, not the tubes.', false),
  ('infertility', 5, 'A male client whose partner is being evaluated with him for infertility has the following findings. Which findings should the nurse recognize as male factors that may contribute to the couple''s infertility? Select all that apply.', '[{"id": "a", "text": "Low sperm count on semen analysis"}, {"id": "b", "text": "Testosterone level within normal limits"}, {"id": "c", "text": "Enlarged scrotal veins on exam"}, {"id": "d", "text": "Reports of erectile dysfunction"}, {"id": "e", "text": "Normal sperm motility and morphology"}]'::jsonb, '["a", "c", "d"]', 'Correct: low sperm count (oligospermia), ejaculation disorders or erectile dysfunction, and varicocele (enlarged scrotal veins that heat the testes) are male factors. Wrong: poor motility or abnormal morphology is a factor, so normal motility and morphology is not; low testosterone is a factor, so a normal level is not.', true),
  ('infertility', 6, 'A client is scheduled for a hysterosalpingogram after 15 months of trying to conceive. She asks what the test will show about her body. Which response by the nurse is BEST?', '[{"id": "a", "text": "It is a tissue sample to assess your uterine lining."}, {"id": "b", "text": "It is a dye test to check fallopian tube patency."}, {"id": "c", "text": "It is a dye test to assess your ovarian follicles."}, {"id": "d", "text": "It is a blood test to confirm that you are ovulating."}]'::jsonb, '["b"]', 'The hysterosalpingogram (HSG) is a dye test to check fallopian tube patency. Assessing the uterine lining is the purpose of an endometrial biopsy, and ovarian follicles are assessed with a pelvic ultrasound.', false),
  ('infertility', 7, 'A 29-year-old client with irregular menstrual cycles has been unable to conceive for 13 months. The provider wants to determine whether she is releasing eggs at all. Which diagnostic test is MOST appropriate for the nurse to anticipate?', '[{"id": "a", "text": "Semen analysis of the partner''s sperm"}, {"id": "b", "text": "Endometrial biopsy to assess the uterine lining"}, {"id": "c", "text": "Ovulation testing (LH surge, progesterone)"}, {"id": "d", "text": "Hysterosalpingogram (HSG) dye test"}]'::jsonb, '["c"]', 'Ovulation testing for an LH surge and progesterone is used to confirm ovulation is occurring. The HSG checks fallopian tube patency, and an endometrial biopsy assesses the uterine lining.', false),
  ('infertility', 8, 'A nurse is explaining diagnostic tests to a client and her partner who are beginning an infertility workup. Which statements by the nurse are accurate? Select all that apply.', '[{"id": "a", "text": "A pelvic ultrasound assesses the uterus and ovarian follicles."}, {"id": "b", "text": "A semen analysis evaluates sperm count, motility, and morphology."}, {"id": "c", "text": "Ovulation testing is used to assess the uterine lining."}, {"id": "d", "text": "An endometrial biopsy is used to confirm ovulation is occurring."}, {"id": "e", "text": "A hysterosalpingogram is a dye test to check fallopian tube patency."}]'::jsonb, '["a", "b", "e"]', 'Correct: the HSG is a dye test to check fallopian tube patency; semen analysis evaluates sperm count, motility, and morphology; pelvic ultrasound assesses the uterus and ovarian follicles. Wrong: confirming ovulation is the purpose of ovulation testing (LH surge, progesterone), and assessing the uterine lining is the purpose of endometrial biopsy, so these two statements reverse the tests.', true),
  ('infertility', 9, 'During a male client''s physical exam for couple infertility, the provider notes enlarged scrotal veins. The client asks how this could affect the couple''s ability to conceive. Which response by the nurse is BEST?', '[{"id": "a", "text": "This is oligospermia, which means the sperm count is low."}, {"id": "b", "text": "This is azoospermia, which means that sperm are absent."}, {"id": "c", "text": "This is an ejaculation disorder, which is a male factor."}, {"id": "d", "text": "This is a varicocele, which heats the testes."}]'::jsonb, '["d"]', 'A varicocele is enlarged scrotal veins that heat the testes and is listed as a male factor. Oligospermia (low sperm count) and azoospermia (absent sperm) are semen findings, not a vein finding on exam.', false),
  ('infertility', 10, 'A 27-year-old client with polycystic ovary syndrome (PCOS) and insulin resistance is prescribed metformin to help her conceive. She asks how this drug will help. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "It is the most commonly used first-line drug to stimulate ovulation."}, {"id": "b", "text": "It directly stimulates follicle development like FSH/LH injections."}, {"id": "c", "text": "It treats endometriosis that is blocking the fallopian tubes."}, {"id": "d", "text": "It improves insulin resistance, which can restore ovulation."}]'::jsonb, '["d"]', 'Metformin is for PCOS-related infertility; it improves insulin resistance, which restores ovulation. The most commonly used first-line drug to stimulate ovulation is clomiphene citrate (Clomid), and gonadotropins directly stimulate follicle development.', false),
  ('infertility', 11, 'A client has had an intrauterine device (IUD) for 1 year. Which reports by the client should the nurse instruct her to report IMMEDIATELY? Select all that apply.', '[{"id": "a", "text": "Her period is late this month"}, {"id": "b", "text": "She has a fever and foul discharge"}, {"id": "c", "text": "Her IUD string is missing"}, {"id": "d", "text": "She has new abdominal pain"}, {"id": "e", "text": "She can feel the IUD string in place"}]'::jsonb, '["a", "b", "c", "d"]', 'Correct: the PAINS danger signs are Period late (possible pregnancy), Abdominal pain, Infection (fever, foul discharge), Not feeling well, and String missing, and all are reported immediately. Wrong: feeling the string in place is the opposite of the String missing warning sign.', true),
  ('infertility', 12, 'A 30-year-old client has absent ovulation confirmed by ovulation testing. Her HSG shows open fallopian tubes, her partner''s semen analysis is normal, and she does not have PCOS. Which medication should the nurse anticipate the provider will order FIRST?', '[{"id": "a", "text": "Metformin"}, {"id": "b", "text": "Clomiphene citrate (Clomid)"}, {"id": "c", "text": "Depo-Provera (medroxyprogesterone)"}, {"id": "d", "text": "Gonadotropins (FSH/LH injections)"}]'::jsonb, '["b"]', 'Clomiphene citrate (Clomid) stimulates ovulation and is the most commonly used first-line drug. Metformin is for PCOS-related infertility, which this client does not have, and gonadotropins are not described as first-line.', false),
  ('infertility', 13, 'A nurse is reinforcing teaching with a client who is starting infertility treatment. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "Clomid is a drug that is used to stimulate ovulation."}, {"id": "b", "text": "Clomid will open up my blocked fallopian tubes."}, {"id": "c", "text": "With IUI, sperm is placed directly into my uterus."}, {"id": "d", "text": "With IVF, my eggs are fertilized in a lab setting."}]'::jsonb, '["b"]', 'Clomiphene citrate (Clomid) stimulates ovulation; it does not open blocked tubes, for which surgery to remove adhesions is a treatment. The statements about IUI (sperm placed directly into the uterus) and IVF (eggs fertilized in lab) are correct.', false),
  ('infertility', 14, 'A nurse is teaching a client and her partner about the 2 types of assisted reproductive technology the provider has offered. Which statements by the couple indicate understanding? Select all that apply.', '[{"id": "a", "text": "With IUI, sperm is placed directly into the uterus around ovulation."}, {"id": "b", "text": "With IVF, eggs are fertilized in a lab and the embryo is transferred to the uterus."}, {"id": "c", "text": "With IVF, sperm is placed directly into the uterus during menstruation."}, {"id": "d", "text": "With IUI, eggs are retrieved and fertilized in a lab before transfer."}, {"id": "e", "text": "With IUI, the embryo is transferred to the uterus after lab fertilization."}]'::jsonb, '["a", "b"]', 'Correct: in IUI, sperm is placed directly into the uterus around ovulation; in IVF, eggs are retrieved, fertilized in lab, and the embryo is transferred to the uterus. Wrong: retrieving eggs, lab fertilization, and embryo transfer describe IVF, not IUI; placing sperm in the uterus describes IUI, and it is done around ovulation, not during menstruation.', true),
  ('infertility', 15, 'A client is scheduled for intrauterine insemination (IUI). She asks when during her cycle the procedure will be done and what will happen. Which response by the nurse is BEST?', '[{"id": "a", "text": "An embryo will be transferred to your uterus during menstruation."}, {"id": "b", "text": "Sperm will be placed directly into your uterus around ovulation."}, {"id": "c", "text": "Sperm will be placed directly into your uterus during menstruation."}, {"id": "d", "text": "Your eggs will be retrieved and fertilized in a lab around ovulation."}]'::jsonb, '["b"]', 'In IUI, sperm is placed directly into the uterus around ovulation. Egg retrieval, lab fertilization, and embryo transfer describe IVF.', false),
  ('infertility', 16, 'A client and her partner are reviewing the medications that may be used in her infertility treatment. Which statements by the client indicate understanding? Select all that apply.', '[{"id": "a", "text": "Clomid is used to stimulate ovulation."}, {"id": "b", "text": "Gonadotropins work by improving insulin resistance."}, {"id": "c", "text": "Metformin is used for PCOS-related infertility."}, {"id": "d", "text": "Gonadotropins directly stimulate follicle development."}, {"id": "e", "text": "Metformin is the most common first-line drug for all."}]'::jsonb, '["a", "c", "d"]', 'Correct: clomiphene citrate (Clomid) stimulates ovulation; metformin is for PCOS-related infertility; gonadotropins (FSH/LH injections) directly stimulate follicle development. Wrong: clomiphene citrate, not metformin, is the most commonly used first-line drug, and improving insulin resistance is how metformin works, not gonadotropins.', true),
  ('infertility', 17, 'A client who did not ovulate with clomiphene citrate is starting gonadotropin (FSH/LH) injections. She asks how these injections work differently. Which response by the nurse is BEST?', '[{"id": "a", "text": "They directly stimulate follicle development."}, {"id": "b", "text": "They improve insulin resistance to restore ovulation."}, {"id": "c", "text": "They treat endometriosis that is outside the uterus."}, {"id": "d", "text": "They are the most commonly used first-line drug for ovulation."}]'::jsonb, '["a"]', 'Gonadotropins (FSH/LH injections) directly stimulate follicle development. Improving insulin resistance describes metformin, and the most commonly used first-line drug is clomiphene citrate.', false),
  ('infertility', 18, 'A client taking a hormonal oral contraceptive is reviewing the ACHES warning signs before stopping the pill to try to conceive. Which statements by the client indicate understanding? Select all that apply.', '[{"id": "a", "text": "Severe leg pain could be a sign of a DVT."}, {"id": "b", "text": "A headache could be a sign of a stroke."}, {"id": "c", "text": "Chest pain could be a sign of a DVT in my leg."}, {"id": "d", "text": "Chest pain could be a sign of a pulmonary embolism."}, {"id": "e", "text": "Eye problems could be a sign of gallbladder disease."}]'::jsonb, '["a", "b", "d"]', 'Correct: in ACHES, Chest pain signals PE (pulmonary embolism), Severe leg pain signals DVT (deep vein thrombosis), and Headache signals stroke. Wrong: DVT is linked to severe leg pain, not chest pain; eye problems (vision changes) signal stroke or HTN, while gallbladder is linked to abdominal pain.', true),
  ('infertility', 19, 'A female client attends an infertility visit alone. She reports that her partner refuses testing because he says she is the one who cannot get pregnant. Which response by the nurse is BEST?', '[{"id": "a", "text": "A full assessment of both partners always comes first."}, {"id": "b", "text": "Your age is the most likely cause, so his testing can wait for now."}, {"id": "c", "text": "Male factors are rare, so we can begin with your evaluation alone."}, {"id": "d", "text": "Testing him is needed only if your own tests come back normal."}]'::jsonb, '["a"]', 'The infertility workup should always start with a full assessment of both partners, and there are several male factors (sperm count, motility, varicocele, ejaculation disorders, low testosterone). Delaying his testing until her results return conflicts with assessing both partners from the start.', false),
  ('infertility', 20, 'A client is tearful after her third unsuccessful IVF cycle. She says, ''I feel like my body keeps failing us.'' Which response by the nurse is BEST?', '[{"id": "a", "text": "Multiple treatment cycles are an emotional rollercoaster; how are you feeling?"}, {"id": "b", "text": "Since IVF has failed three times, you should consider adoption now."}, {"id": "c", "text": "Stay positive; there is a very good chance that the next cycle will work for you."}, {"id": "d", "text": "Let''s focus on scheduling the date for your next embryo transfer."}]'::jsonb, '["a"]', 'The nurse provides emotional support and supports the client through multiple treatment cycles, which is an emotional rollercoaster. Pushing adoption at this moment is not support, and adoption should be discussed without judgment rather than as the result of failure.', false),
  ('infertility', 21, 'A client and her partner are starting an infertility evaluation. Which actions by the nurse are appropriate at this INITIAL visit? Select all that apply.', '[{"id": "a", "text": "Assess both partners without blame or assumptions."}, {"id": "b", "text": "Teach basal body temperature charting and ovulation predictor kits."}, {"id": "c", "text": "Teach optimal intercourse timing around ovulation (Days 10–14)."}, {"id": "d", "text": "Advise intercourse during Days 1–5 of a 28-day cycle."}, {"id": "e", "text": "Begin with the female partner, since age is the main factor."}]'::jsonb, '["a", "b", "c"]', 'Correct: the nurse assesses both partners without blame or assumptions, teaches basal body temperature charting and ovulation predictor kits, and teaches that optimal intercourse timing is around ovulation (Days 10–14 of a 28-day cycle). Wrong: starting with only the female partner contradicts assessing both partners, and Days 1–5 are not around ovulation.', true),
  ('infertility', 22, 'After several unsuccessful treatment cycles, a client and her partner ask the nurse whether they should think about adoption. Which response by the nurse is BEST?', '[{"id": "a", "text": "You shouldn''t give up yet; adoption is really a last resort."}, {"id": "b", "text": "Let''s stay focused on treatment, since adoption isn''t a medical topic."}, {"id": "c", "text": "Adoption should be considered only after IVF has been tried."}, {"id": "d", "text": "Let''s discuss adoption and other family-building options."}]'::jsonb, '["d"]', 'The nurse discusses adoption or other family-building options without judgment. Calling adoption a last resort or delaying the topic until IVF is tried places judgment on the couple''s choice.', false),
  ('infertility', 23, 'A client with regular 28-day cycles is trying to conceive. Her last menstrual period began on March 1. She asks when intercourse is MOST likely to lead to pregnancy this cycle. Which response by the nurse is BEST?', '[{"id": "a", "text": "Days 1–5 of her cycle, March 1 to March 5, during menses"}, {"id": "b", "text": "Days 21–28 of her cycle, March 21 to March 28"}, {"id": "c", "text": "Days 10–14 of her cycle, March 10 to March 14"}, {"id": "d", "text": "Days 15–19 of her cycle, March 15 to March 19"}]'::jsonb, '["c"]', 'Optimal intercourse timing is around ovulation, Days 10–14 of a 28-day cycle; with day 1 on March 1, that is March 10 to March 14. Days 15–19 fall after that window.', false),
  ('infertility', 24, 'A 38-year-old client is being evaluated for infertility. Which findings in her history should the nurse recognize as female factors? Select all that apply.', '[{"id": "a", "text": "Her age of 38 years"}, {"id": "b", "text": "Prolactin imbalance on hormone levels"}, {"id": "c", "text": "Irregular or absent ovulation"}, {"id": "d", "text": "Uterine fibroids on ultrasound"}, {"id": "e", "text": "An LH surge confirmed each cycle"}]'::jsonb, '["a", "b", "c", "d"]', 'Correct: ovulatory dysfunction (irregular/absent ovulation), hormonal imbalance (thyroid, prolactin, PCOS), uterine fibroids or structural anomalies, and age (fertility declines significantly after 35) are female factors. Wrong: an LH surge each cycle is the ovulation-testing finding that confirms ovulation is occurring, so it is not a factor.', true),
  ('infertility', 25, 'A client taking a hormonal oral contraceptive while delaying pregnancy calls to report sudden chest pain that began 20 minutes ago. Which complication should the nurse suspect is MOST likely?', '[{"id": "a", "text": "Ectopic pregnancy"}, {"id": "b", "text": "Stroke"}, {"id": "c", "text": "Deep vein thrombosis (DVT)"}, {"id": "d", "text": "Pulmonary embolism (PE)"}]'::jsonb, '["d"]', 'In ACHES, Chest pain warns of PE (pulmonary embolism) and is reported immediately. DVT is linked to severe leg pain, stroke to headache, and ectopic pregnancy to abdominal pain.', false),
  ('infertility', 26, 'A client who takes a hormonal oral contraceptive reports that her vision has been blurry since this morning. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Advise her to rest her eyes and recheck her vision at her yearly visit."}, {"id": "b", "text": "Tell her to stop the pill and switch to an IUD at her routine visit."}, {"id": "c", "text": "Report it immediately; vision changes can signal stroke or HTN."}, {"id": "d", "text": "Reassure her that vision changes are expected with hormonal contraceptives."}]'::jsonb, '["c"]', 'Eye problems (vision changes) are an ACHES warning sign of stroke or HTN and must be reported immediately. Waiting for a yearly or routine visit delays a danger sign.', false),
  ('infertility', 27, 'A client who uses a hormonal oral contraceptive calls the clinic reporting new, severe abdominal pain. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "An ACHES sign of liver, ectopic pregnancy, or gallbladder problems"}, {"id": "b", "text": "An ACHES sign of a pulmonary embolism (PE) or a deep vein thrombosis"}, {"id": "c", "text": "An expected side effect that does not need to be reported"}, {"id": "d", "text": "An ACHES sign of a stroke or high blood pressure (HTN)"}]'::jsonb, '["a"]', 'In ACHES, Abdominal pain may signal liver, ectopic pregnancy, or gallbladder problems and is reported immediately. PE is linked to chest pain and DVT to severe leg pain.', false),
  ('infertility', 28, 'A client has been receiving Depo-Provera for 2.5 years and wants to continue it. She asks about her bone health. Which actions by the nurse are appropriate? Select all that apply.', '[{"id": "a", "text": "Space the injections to every 6 months to protect bone."}, {"id": "b", "text": "Continue the injections with no further discussion."}, {"id": "c", "text": "Hold a risk/benefit discussion about long-term use (>2 years)."}, {"id": "d", "text": "Stop calcium, since this drug protects bone density."}, {"id": "e", "text": "Monitor her calcium and Vitamin D intake."}]'::jsonb, '["c", "e"]', 'Correct: Depo-Provera causes bone density loss, so calcium and Vitamin D intake are monitored, and it is not recommended for long-term use (>2 years) without a risk/benefit discussion. Wrong: it is given every 3 months, not every 6 months; it causes bone density loss rather than protecting bone; and use beyond 2 years requires discussion.', true),
  ('infertility', 29, 'The nurse at a women''s health clinic receives four phone messages. Which client should the nurse call back FIRST?', '[{"id": "a", "text": "A client with a positive ovulation predictor kit result"}, {"id": "b", "text": "A client on Depo-Provera asking about calcium intake"}, {"id": "c", "text": "A client with an IUD whose string is missing"}, {"id": "d", "text": "A client with an IUD whose string is in place"}]'::jsonb, '["c"]', 'In PAINS, String missing is an IUD danger sign that must be reported immediately. Feeling the string in place is expected, and calcium questions and a positive ovulation predictor kit are routine.', false),
  ('infertility', 30, 'A 27-year-old client has received Depo-Provera injections for 18 months. She plans to stop and hopes to be pregnant within 6 months. Which teaching is MOST important for the nurse to provide?', '[{"id": "a", "text": "Fertility may not return for 3 months after stopping."}, {"id": "b", "text": "Fertility may not return for 6 months after stopping."}, {"id": "c", "text": "Fertility may not return for 12–18 months after stopping."}, {"id": "d", "text": "Fertility returns as soon as the next injection is missed."}]'::jsonb, '["c"]', 'After Depo-Provera, fertility may not return for 12–18 months after stopping, so pregnancy within 6 months may not occur. Three months is the injection interval, not the time for fertility to return.', false),
  ('infertility', 31, 'A nurse is reviewing Depo-Provera (medroxyprogesterone) teaching with a client. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "This shot can cause bone density loss over time."}, {"id": "b", "text": "I will increase my calcium and Vitamin D intake."}, {"id": "c", "text": "I will discuss the risks if I use it beyond 2 years."}, {"id": "d", "text": "I will come in for my injection every 6 months."}]'::jsonb, '["d"]', 'Depo-Provera is given every 3 months IM, so an every-6-months schedule needs correction. Bone density loss, monitoring calcium and Vitamin D, and a risk/benefit discussion beyond 2 years are all correct.', false),
  ('infertility', 32, 'A client who is undergoing fertility treatment is upset after several unsuccessful cycles. Which nursing actions are appropriate? Select all that apply.', '[{"id": "a", "text": "Discuss adoption or other options without judgment."}, {"id": "b", "text": "Reassure her that this distress is uncommon and brief."}, {"id": "c", "text": "Provide emotional support for her psychological distress."}, {"id": "d", "text": "Help the couple identify which partner is at fault."}, {"id": "e", "text": "Avoid any mention of adoption to protect her hope."}]'::jsonb, '["a", "c"]', 'Correct: infertility causes significant psychological distress, so the nurse provides emotional support, and the nurse discusses adoption or other family-building options without judgment. Wrong: infertility causes significant distress, not uncommon or brief distress; partners are assessed without blame; and adoption and other options are discussed rather than avoided.', true),
  ('infertility', 33, 'A 38-year-old client trying to conceive asks whether her age plays any role, since she exercises and has regular cycles. Which response by the nurse is BEST?', '[{"id": "a", "text": "Age begins to matter after 45, so it is not a factor for you yet."}, {"id": "b", "text": "Age is a concern when PCOS or fibroids are also present with it."}, {"id": "c", "text": "Age affects male partners through low testosterone, not females."}, {"id": "d", "text": "Fertility declines significantly after 35, a female factor."}]'::jsonb, '["d"]', 'Age is a female factor, and fertility declines significantly after 35, so it applies to this 38-year-old regardless of regular cycles. Age is a female factor on its own, not only when PCOS or fibroids are present.', false),
  ('infertility', 34, 'A client with endometriosis and 16 months of infertility asks how her condition could keep her from becoming pregnant. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "It heats the ovaries, which stops the release of the eggs."}, {"id": "b", "text": "Tissue outside the uterus is a common cause of blocked tubes."}, {"id": "c", "text": "It is a hormonal imbalance that is treated with metformin."}, {"id": "d", "text": "It is caused by PID from chlamydia, which then blocks the tubes."}]'::jsonb, '["b"]', 'Endometriosis is uterine tissue outside the uterus, and endometriosis and PID are common causes of blocked tubes. PID from chlamydia/gonorrhea is a separate cause, and metformin is for PCOS-related infertility.', false),
  ('infertility', 35, 'A client''s HSG shows that both fallopian tubes are blocked. Which items in her history should the nurse recognize as common causes of this finding? Select all that apply.', '[{"id": "a", "text": "Past PID from gonorrhea"}, {"id": "b", "text": "Partner''s enlarged scrotal veins"}, {"id": "c", "text": "Partner''s low sperm count"}, {"id": "d", "text": "Diagnosed endometriosis"}, {"id": "e", "text": "Past PID from chlamydia"}]'::jsonb, '["a", "d", "e"]', 'Correct: endometriosis and PID (from chlamydia/gonorrhea) are common causes of blocked tubes. Wrong: low sperm count (oligospermia) and varicocele (enlarged scrotal veins) are male factors and do not block the female partner''s tubes.', true),
  ('infertility', 36, 'A client with irregular ovulation has a known thyroid disorder that has been difficult to control. Which diagnostic test should the nurse anticipate to BEST evaluate this possible cause?', '[{"id": "a", "text": "Endometrial biopsy of the uterine lining"}, {"id": "b", "text": "Hormone levels, such as TSH and prolactin"}, {"id": "c", "text": "Semen analysis of the partner''s sperm"}, {"id": "d", "text": "Hysterosalpingogram to check the fallopian tubes"}]'::jsonb, '["b"]', 'Hormonal imbalance (thyroid, prolactin, PCOS) is a female factor, and hormone levels include FSH, LH, estrogen, prolactin, TSH, and AMH. The HSG checks fallopian tube patency rather than hormones.', false),
  ('infertility', 37, 'A client is suspected of having uterine fibroids or another structural anomaly of the uterus. Which diagnostic test should the nurse anticipate to BEST assess this concern?', '[{"id": "a", "text": "Semen analysis"}, {"id": "b", "text": "Endometrial biopsy"}, {"id": "c", "text": "Ovulation testing"}, {"id": "d", "text": "Pelvic ultrasound"}]'::jsonb, '["d"]', 'A pelvic ultrasound assesses the uterus and ovarian follicles, so it fits a suspected fibroid or structural anomaly. An endometrial biopsy assesses only the uterine lining.', false),
  ('infertility', 38, 'A client is reviewing ways to identify ovulation while she and her partner try to conceive. Which methods should the nurse include? Select all that apply.', '[{"id": "a", "text": "Hysterosalpingogram (HSG)"}, {"id": "b", "text": "Semen analysis"}, {"id": "c", "text": "Basal body temperature charting"}, {"id": "d", "text": "Ovulation predictor kits"}, {"id": "e", "text": "Ovulation testing (LH surge, progesterone)"}]'::jsonb, '["c", "d", "e"]', 'Correct: the nurse teaches basal body temperature charting and ovulation predictor kits, and ovulation testing (LH surge, progesterone) confirms ovulation is occurring. Wrong: the HSG is a dye test of fallopian tube patency, and semen analysis evaluates sperm count, motility, and morphology.', true),
  ('infertility', 39, 'A client''s workup shows confirmed ovulation, open fallopian tubes on HSG, and a normal semen analysis for her partner. The provider now wants to evaluate the uterine lining. Which test should the nurse prepare the client for NEXT?', '[{"id": "a", "text": "Endometrial biopsy"}, {"id": "b", "text": "Hysterosalpingogram"}, {"id": "c", "text": "Pelvic ultrasound"}, {"id": "d", "text": "Ovulation testing"}]'::jsonb, '["a"]', 'An endometrial biopsy is used to assess the uterine lining. A pelvic ultrasound assesses the uterus and ovarian follicles, and the HSG and ovulation testing have already been completed.', false),
  ('infertility', 40, 'A client has uterine fibroids and endometriosis that are likely contributing to her infertility. She asks which treatment directly addresses these problems. Which response by the nurse is BEST?', '[{"id": "a", "text": "Metformin to improve her insulin resistance"}, {"id": "b", "text": "IUI to place sperm directly into the uterus"}, {"id": "c", "text": "Surgery to remove fibroids or treat endometriosis"}, {"id": "d", "text": "Clomiphene citrate to stimulate her ovulation each cycle"}]'::jsonb, '["c"]', 'Surgery is used to remove adhesions, fibroids, or treat endometriosis. Clomiphene citrate stimulates ovulation and metformin improves insulin resistance in PCOS, which do not address fibroids or endometriosis.', false),
  ('infertility', 41, 'A male client''s semen analysis report reads: sperm present but count low, most sperm not moving well, and sperm shape normal. Which male factors should the nurse recognize in this report? Select all that apply.', '[{"id": "a", "text": "Varicocele"}, {"id": "b", "text": "Low sperm count (oligospermia)"}, {"id": "c", "text": "Poor sperm motility"}, {"id": "d", "text": "Abnormal morphology"}, {"id": "e", "text": "Absent sperm (azoospermia)"}]'::jsonb, '["b", "c"]', 'Correct: a low count is oligospermia, and sperm not moving well is poor sperm motility. Wrong: azoospermia means absent sperm, but sperm are present; morphology (shape) is normal; and a varicocele is enlarged scrotal veins found on exam, not on semen analysis.', true),
  ('infertility', 42, 'A male client reports erectile dysfunction during the couple''s infertility intake but says it has nothing to do with their difficulty conceiving. Which response by the nurse is BEST?', '[{"id": "a", "text": "Erectile dysfunction is a female factor tied to hormone levels."}, {"id": "b", "text": "Erectile dysfunction matters only if your sperm count is low."}, {"id": "c", "text": "Erectile dysfunction is a male factor in infertility."}, {"id": "d", "text": "Erectile dysfunction is assessed after her tests are finished."}]'::jsonb, '["c"]', 'Ejaculation disorders or erectile dysfunction are listed male factors, and both partners are assessed from the start. Limiting its importance to low sperm count is not accurate, because erectile dysfunction is a male factor on its own.', false),
  ('infertility', 43, 'A male client''s semen analysis report states that no sperm are present in the sample. Which interpretation of this result by the nurse is MOST accurate?', '[{"id": "a", "text": "Oligospermia"}, {"id": "b", "text": "Azoospermia"}, {"id": "c", "text": "Varicocele"}, {"id": "d", "text": "Poor sperm motility"}]'::jsonb, '["b"]', 'Absent sperm is azoospermia. Oligospermia is a low sperm count, which is the most tempting distractor, but this sample has no sperm at all.', false),
  ('infertility', 44, 'A nurse is triaging calls from clients using contraception. Which client reports require IMMEDIATE follow-up? Select all that apply.', '[{"id": "a", "text": "IUD user who can feel her string in place"}, {"id": "b", "text": "Client with a positive ovulation predictor kit"}, {"id": "c", "text": "Hormonal contraceptive user with a new headache"}, {"id": "d", "text": "Depo-Provera user asking about calcium intake"}, {"id": "e", "text": "Hormonal contraceptive user with eye problems"}]'::jsonb, '["c", "e"]', 'Correct: in ACHES, Headache (stroke) and Eye problems (vision changes — stroke, HTN) are hormonal contraceptive warning signs to report immediately. Wrong: calcium intake is routine Depo-Provera teaching, feeling the IUD string is the opposite of the String missing sign, and a positive ovulation predictor kit is expected when trying to conceive.', true),
  ('infertility', 45, 'The nurse receives four calls from clients using hormonal oral contraceptives. Which client should the nurse call back FIRST?', '[{"id": "a", "text": "A client with severe leg pain in one calf"}, {"id": "b", "text": "A client asking how long fertility takes to return"}, {"id": "c", "text": "A client asking when to use an ovulation predictor kit"}, {"id": "d", "text": "A client asking how to chart her basal temperature"}]'::jsonb, '["a"]', 'Severe leg pain is an ACHES warning sign of DVT (deep vein thrombosis) and must be reported immediately. The other calls are teaching questions about basal body temperature charting, ovulation predictor kits, and fertility timing.', false),
  ('infertility', 46, 'A client received her last Depo-Provera injection on January 10 and wants to continue the method. When should the nurse schedule her NEXT IM injection?', '[{"id": "a", "text": "In 1 month, on February 10"}, {"id": "b", "text": "In 3 months, on April 10"}, {"id": "c", "text": "In 6 months, on July 10"}, {"id": "d", "text": "In 12 months, on January 10"}]'::jsonb, '["b"]', 'Depo-Provera is given every 3 months IM, so the injection after January 10 is due April 10. July 10 would be a 6-month interval.', false),
  ('infertility', 47, 'A 26-year-old client with polycystic ovary syndrome (PCOS) and insulin resistance has irregular ovulation and has not conceived in 14 months. Which medication should the nurse anticipate is MOST specific to the cause of her infertility?', '[{"id": "a", "text": "Gonadotropins (FSH/LH injections)"}, {"id": "b", "text": "Clomiphene citrate (Clomid)"}, {"id": "c", "text": "Depo-Provera (medroxyprogesterone)"}, {"id": "d", "text": "Metformin"}]'::jsonb, '["d"]', 'Metformin is used for PCOS-related infertility because it improves insulin resistance, which restores ovulation. Clomiphene citrate stimulates ovulation and is first-line in general, but it does not target the insulin resistance behind PCOS-related infertility.', false),
  ('infertility', 48, 'A male client''s hormone testing during an infertility workup shows a low testosterone level, while his semen analysis is still pending. How should the nurse BEST classify this finding?', '[{"id": "a", "text": "A normal finding that needs no further follow-up"}, {"id": "b", "text": "Varicocele (enlarged scrotal veins), a male factor"}, {"id": "c", "text": "Hormonal deficiencies (low testosterone), a male factor"}, {"id": "d", "text": "Hormonal imbalance (thyroid, prolactin), a female factor"}]'::jsonb, '["c"]', 'Hormonal deficiencies (low testosterone) are listed as a male factor. Hormonal imbalance (thyroid, prolactin, PCOS) is the female-factor category, and a varicocele is enlarged scrotal veins.', false),
  ('infertility', 49, 'A client receiving gonadotropin injections is having frequent monitoring visits. The provider wants to see how the ovarian follicles are developing. Which test is MOST appropriate for the nurse to anticipate at these visits?', '[{"id": "a", "text": "Pelvic ultrasound"}, {"id": "b", "text": "Semen analysis"}, {"id": "c", "text": "Endometrial biopsy"}, {"id": "d", "text": "Hysterosalpingogram"}]'::jsonb, '["a"]', 'A pelvic ultrasound assesses the uterus and ovarian follicles, which fits monitoring follicle development during gonadotropin therapy. The HSG checks tube patency, and an endometrial biopsy assesses the uterine lining.', false),
  ('infertility', 50, 'A nurse is observing a new nurse counsel a client and her partner who have been trying to conceive for 15 months. Which statement by the new nurse requires follow-up by the precepting nurse?', '[{"id": "a", "text": "Your irregular ovulation is likely the cause of this infertility."}, {"id": "b", "text": "Infertility can cause significant psychological distress for couples."}, {"id": "c", "text": "Adoption is one of several family-building options we can discuss."}, {"id": "d", "text": "Optimal timing is around ovulation, Days 10–14 of a 28-day cycle."}]'::jsonb, '["a"]', 'Partners are assessed without blame or assumptions, so naming one partner''s ovulation as the likely cause before a full workup needs correction. The statements about psychological distress, intercourse timing on Days 10–14, and discussing adoption without judgment are correct.', false),
  ('turp', 1, 'A 68-year-old client is 6 hours post-TURP with continuous bladder irrigation running through a 3-way Foley. The drainage is light pink without clots, and vital signs are unchanged from baseline. Which action by the nurse is BEST?', '[{"id": "a", "text": "Increase the CBI rate because this suggests possible hemorrhage"}, {"id": "b", "text": "Slow the irrigation rate because the urine has cleared"}, {"id": "c", "text": "Continue monitoring; light pink is the expected color"}, {"id": "d", "text": "Notify the provider STAT of a hemorrhagic emergency"}]'::jsonb, '["c"]', 'Light pink urine is the expected color during CBI after TURP, so the nurse continues monitoring. Increasing the CBI rate and notifying the provider are reserved for bright red urine or clots.', false),
  ('turp', 2, 'On day 2 after TURP, the nurse notes that the CBI drainage of a 70-year-old client has changed from light pink to clear, with no clots and steady output. Which action should the nurse take NEXT?', '[{"id": "a", "text": "Slow the irrigation rate"}, {"id": "b", "text": "Increase the CBI rate"}, {"id": "c", "text": "Stop and remove the catheter"}, {"id": "d", "text": "Flush the catheter per protocol"}]'::jsonb, '["a"]', 'When urine becomes clear, the nurse slows the irrigation rate. Increasing the CBI rate is the response to bright red urine or clots, and flushing per protocol is for decreased output or blockage.', false),
  ('turp', 3, 'A 66-year-old client is being discharged 3 days after TURP. Which statements by the client indicate understanding of the discharge teaching? Select all that apply.', '[{"id": "a", "text": "\"I will use docusate so I do not strain.\""}, {"id": "b", "text": "\"I will avoid heavy lifting for 4 to 6 weeks.\""}, {"id": "c", "text": "\"I will limit fluids to keep from leaking.\""}, {"id": "d", "text": "\"I will drink 2 to 3 liters of fluid daily.\""}, {"id": "e", "text": "\"I will report urine that turns bright red.\""}]'::jsonb, '["a", "b", "d", "e"]', 'Docusate prevents straining, which raises abdominal pressure and risks bleeding; heavy lifting is avoided for 4–6 weeks; 2–3 L of fluid daily flushes the urinary tract; and dark or bright red urine must be reported. Limiting fluids to prevent leaking contradicts the hydration teaching; temporary incontinence is common and helped by Kegels and bladder training.', true),
  ('turp', 4, 'A 71-year-old client is on day 1 after TURP. Which assessment data does the nurse recognize as expected findings at this time? Select all that apply.', '[{"id": "a", "text": "Dark red urine in the drainage bag"}, {"id": "b", "text": "Light pink urine during irrigation"}, {"id": "c", "text": "Bright red urine with several clots"}, {"id": "d", "text": "3-way Foley with CBI infusing"}, {"id": "e", "text": "Bradycardia with new confusion"}]'::jsonb, '["b", "d"]', 'Light pink urine is the expected color, and a 3-way Foley is inserted after TURP for continuous bladder irrigation. Dark red or bright red urine with clots suggests bleeding that must be reported, and bradycardia with confusion suggests TURP syndrome.', true),
  ('turp', 5, 'A 72-year-old client on CBI after TURP has new bright red drainage with several small clots. His heart rate is 84/min and blood pressure is unchanged from baseline. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Slow the irrigation rate to reduce bleeding"}, {"id": "b", "text": "Restrict fluids and check the serum sodium level now"}, {"id": "c", "text": "Give oxybutynin for bladder spasms"}, {"id": "d", "text": "Increase the CBI rate and notify the provider"}]'::jsonb, '["d"]', 'Bright red urine or clots signal possible hemorrhage, so the nurse increases the CBI rate and notifies the provider. Slowing the irrigation rate is done only when the urine becomes clear.', false),
  ('turp', 6, 'Eight hours after TURP, a 74-year-old client''s CBI drainage is bright red with large clots. His heart rate has risen from 78 to 122/min and his blood pressure has fallen from 134/82 to 88/52. Which action is the PRIORITY?', '[{"id": "a", "text": "Slow the CBI rate until the drainage clears"}, {"id": "b", "text": "Notify the provider STAT of a hemorrhagic emergency"}, {"id": "c", "text": "Check the serum sodium level for possible TURP syndrome"}, {"id": "d", "text": "Teach the client to avoid straining at stool"}]'::jsonb, '["b"]', 'Tachycardia plus hypotension plus clots is a hemorrhagic emergency requiring STAT provider notification. Serum sodium monitoring applies to TURP syndrome, which presents with bradycardia and confusion rather than tachycardia.', false),
  ('turp', 7, 'Several hours after TURP, a 71-year-old client becomes confused and nauseated. His heart rate has dropped from 76 to 50/min, and the CBI drainage is light pink. Which laboratory result is MOST important for the nurse to check?', '[{"id": "a", "text": "Hematocrit and hemoglobin"}, {"id": "b", "text": "Serum sodium"}, {"id": "c", "text": "Urinalysis and culture"}, {"id": "d", "text": "BUN and creatinine"}]'::jsonb, '["b"]', 'Confusion, bradycardia and nausea suggest TURP syndrome, which is hyponatremia from irrigant absorption, so serum sodium is monitored. Hematocrit/hemoglobin detect post-op bleeding, which is not suggested by light pink drainage and bradycardia.', false),
  ('turp', 8, 'A 69-year-old client is 12 hours post-TURP. Which findings should the nurse report to the provider IMMEDIATELY? Select all that apply.', '[{"id": "a", "text": "Light pink urine draining steadily"}, {"id": "b", "text": "Bright red urine with clots"}, {"id": "c", "text": "New tachycardia with hypotension"}, {"id": "d", "text": "Leaking urine after catheter removal"}, {"id": "e", "text": "Clots with a falling blood pressure"}]'::jsonb, '["b", "c", "e"]', 'Bright red urine with clots signals possible hemorrhage, and tachycardia plus hypotension plus clots is a hemorrhagic emergency to report STAT. Light pink urine is expected, and temporary incontinence after catheter removal is common post-op.', true),
  ('turp', 9, 'A 73-year-old client with suspected TURP syndrome is confused and bradycardic, and his serum sodium is below normal. Which order is the nurse MOST likely to implement?', '[{"id": "a", "text": "Encourage 2–3 L of fluids daily"}, {"id": "b", "text": "Increase the CBI rate to flush clots"}, {"id": "c", "text": "Prepare the client for a blood transfusion"}, {"id": "d", "text": "Restrict fluids and report immediately"}]'::jsonb, '["d"]', 'TURP syndrome is hyponatremia from irrigant absorption; management includes monitoring serum Na⁺, restricting fluids and reporting immediately. Drinking 2–3 L daily is discharge teaching to flush the urinary tract and would worsen this situation.', false),
  ('turp', 10, 'On day 1 after TURP, a 69-year-old client watches the saline flowing through his 3-way Foley and asks, "Why does that fluid have to keep running? Can''t you turn it off?" The drainage is light pink. Which response by the nurse is BEST?', '[{"id": "a", "text": "It prevents clots and maintains catheter patency."}, {"id": "b", "text": "It replaces fluids, so you do not need to drink today."}, {"id": "c", "text": "It will be stopped as soon as the urine turns light pink."}, {"id": "d", "text": "It treats infection, so stopping it now would risk sepsis."}]'::jsonb, '["a"]', 'The purpose of CBI is to prevent clots and maintain catheter patency by flushing blood from the bladder. Light pink is the expected color during CBI, not a signal to stop it, and the irrigation does not replace oral fluids.', false),
  ('turp', 11, 'A 70-year-old client is on day 1 after TURP. Which signs would lead the nurse to suspect TURP syndrome? Select all that apply.', '[{"id": "a", "text": "Confusion"}, {"id": "b", "text": "Bradycardia"}, {"id": "c", "text": "Tachycardia"}, {"id": "d", "text": "Nausea"}, {"id": "e", "text": "Seizures"}]'::jsonb, '["a", "b", "d", "e"]', 'TURP syndrome presents with confusion, bradycardia, nausea and seizures from hyponatremia caused by irrigant absorption. Tachycardia, especially with hypotension and clots, points to hemorrhage instead.', true),
  ('turp', 12, 'During an 8-hour shift, 3,000 mL of sterile saline irrigant infused through the 3-way Foley of a client on CBI after TURP. The total volume emptied from the drainage bag was 3,450 mL. Which value is the MOST accurate true urine output to record for the shift?', '[{"id": "a", "text": "3,450 mL"}, {"id": "b", "text": "3,000 mL"}, {"id": "c", "text": "450 mL"}, {"id": "d", "text": "6,450 mL"}]'::jsonb, '["c"]', 'Because sterile saline continuously runs into the bladder and drains out with the urine, true urine output equals total drainage minus irrigant: 3,450 mL − 3,000 mL = 450 mL. Recording 3,450 mL counts the irrigant as urine.', false),
  ('turp', 13, 'Over 4 hours, 2,400 mL of irrigant infused into a client on CBI after TURP, but only 2,150 mL has drained. The client reports bladder fullness and cramping. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Check for kinks or blockage; flush per protocol"}, {"id": "b", "text": "Record a true urine output of 2,150 mL"}, {"id": "c", "text": "Increase the irrigation rate to clear clots"}, {"id": "d", "text": "Give a belladonna-opium suppository for the spasms"}]'::jsonb, '["a"]', 'Drainage is 250 mL less than the irrigant infused, so output is decreased and fluid is being retained; with spasms, the nurse checks for kinks or blockage and flushes per protocol. Treating spasms with medication first would leave a blocked catheter unaddressed.', false),
  ('turp', 14, 'A 65-year-old client on day 2 after TURP has a temperature elevation. Which additional findings support infection rather than another post-op complication? Select all that apply.', '[{"id": "a", "text": "Cloudy, foul-smelling urine"}, {"id": "b", "text": "Urge to void with catheter in place"}, {"id": "c", "text": "Suprapubic tenderness"}, {"id": "d", "text": "Bradycardia with new confusion"}, {"id": "e", "text": "Bright red urine with clots"}]'::jsonb, '["a", "c"]', 'Fever with cloudy/foul urine and suprapubic tenderness indicates infection (UTI/sepsis). An urge to void with the catheter in place is a bladder spasm, bradycardia with confusion suggests TURP syndrome, and bright red urine with clots suggests hemorrhage.', true),
  ('turp', 15, 'Four hours after his catheter was removed following TURP, a 69-year-old client has not voided and reports lower abdominal fullness. Which action should the nurse take NEXT?', '[{"id": "a", "text": "Reassure him that temporary incontinence is common"}, {"id": "b", "text": "Restrict fluids to reduce bladder filling"}, {"id": "c", "text": "Teach Kegel exercises to start the stream"}, {"id": "d", "text": "Prepare for straight catheterization if needed"}]'::jsonb, '["d"]', 'Inability to void after catheter removal indicates post-catheter urinary retention, managed by assessing the first void and straight catheterization if needed. Reassurance about temporary incontinence applies to leaking, not to an inability to void.', false),
  ('turp', 16, 'A 66-year-old client on day 3 after TURP has a fever, cloudy foul-smelling urine, and suprapubic tenderness. Which action does the nurse anticipate performing FIRST?', '[{"id": "a", "text": "Starting antibiotics"}, {"id": "b", "text": "Increasing the CBI rate"}, {"id": "c", "text": "Obtaining cultures"}, {"id": "d", "text": "Restricting fluids"}]'::jsonb, '["c"]', 'Fever, cloudy/foul urine and suprapubic tenderness suggest infection, managed with cultures, then antibiotics, and vital sign monitoring. Increasing the CBI rate is the response to bright red urine or clots.', false),
  ('turp', 17, 'A 72-year-old client develops bright red CBI drainage, clots, tachycardia, and hypotension after TURP. Which actions does the nurse anticipate? Select all that apply.', '[{"id": "a", "text": "Report immediately to the provider"}, {"id": "b", "text": "Slow the irrigation rate"}, {"id": "c", "text": "Increase the CBI rate"}, {"id": "d", "text": "Restrict oral fluids"}, {"id": "e", "text": "Prepare for transfusion"}]'::jsonb, '["a", "c", "e"]', 'Hemorrhage after TURP is managed by reporting immediately, increasing the CBI rate and preparing for transfusion. Slowing the irrigation rate is for clear urine, and restricting fluids is a TURP syndrome action.', true),
  ('turp', 18, 'A client on CBI after TURP has bright red drainage with clots, and the nurse is monitoring for blood loss. Which laboratory values are MOST useful for detecting post-op bleeding?', '[{"id": "a", "text": "Serum sodium"}, {"id": "b", "text": "Hematocrit and hemoglobin"}, {"id": "c", "text": "BUN and creatinine"}, {"id": "d", "text": "Urinalysis and culture"}]'::jsonb, '["b"]', 'Hematocrit/hemoglobin detect post-op bleeding. Serum sodium monitors for TURP syndrome, and BUN/creatinine assess renal function.', false),
  ('turp', 19, 'A 70-year-old client had long-standing urinary obstruction from BPH before his TURP. His daughter asks why BUN and creatinine are being drawn after surgery. Which response by the nurse is BEST?', '[{"id": "a", "text": "To detect post-op bleeding into the bladder"}, {"id": "b", "text": "To monitor for hyponatremia from irrigant absorption"}, {"id": "c", "text": "To rule out a urinary tract infection"}, {"id": "d", "text": "To assess renal function after urinary obstruction"}]'::jsonb, '["d"]', 'BUN/creatinine assess renal function after urinary obstruction. Hematocrit/hemoglobin detect bleeding, serum sodium monitors for TURP syndrome, and urinalysis/culture rules out infection.', false),
  ('turp', 20, 'A 67-year-old client on CBI reports cramping and an urge to void with the catheter in place. The tubing is free of kinks, the catheter is patent, and the drainage is light pink. Which medications does the nurse anticipate? Select all that apply.', '[{"id": "a", "text": "Docusate"}, {"id": "b", "text": "Oxybutynin"}, {"id": "c", "text": "Antibiotics"}, {"id": "d", "text": "Belladonna-opium suppository"}, {"id": "e", "text": "Blood transfusion"}]'::jsonb, '["b", "d"]', 'An urge to void with the catheter in place plus cramping are bladder spasms; once the catheter is confirmed patent, antispasmodics such as oxybutynin or a belladonna-opium suppository are used. Docusate prevents straining, antibiotics treat infection, and transfusion is for hemorrhage.', true),
  ('turp', 21, 'A 62-year-old client returns for a 2-week check after TURP and says, "My grandson is moving this weekend, and I plan to help carry his furniture." Which response by the nurse is BEST?', '[{"id": "a", "text": "Lifting is safe now that the catheter is out."}, {"id": "b", "text": "Avoid heavy lifting for 4–6 weeks after surgery."}, {"id": "c", "text": "Lifting is fine as long as you drink 2–3 L of fluid daily."}, {"id": "d", "text": "Lifting is safe if you take docusate first."}]'::jsonb, '["b"]', 'Heavy lifting is restricted for 4–6 weeks after TURP, and at 2 weeks the client is still within that window. Docusate and fluids are separate teaching points and do not make heavy lifting safe.', false),
  ('turp', 22, 'A 64-year-old client 3 weeks after TURP tells the nurse privately, "When I ejaculate, little or nothing comes out. Did the surgery go wrong?" Which response by the nurse is BEST?', '[{"id": "a", "text": "Semen enters the bladder; it is harmless but may affect fertility."}, {"id": "b", "text": "This is a sign of hemorrhage, so you need to be seen in the clinic today."}, {"id": "c", "text": "This means your catheter injured the urethra during surgery."}, {"id": "d", "text": "This shows an infection that will need cultures and antibiotics."}]'::jsonb, '["a"]', 'Retrograde ejaculation, in which semen enters the bladder instead of exiting, is harmless but may affect fertility, and the client should be counseled. It is not a sign of hemorrhage or infection.', false),
  ('turp', 23, 'A 71-year-old client asks why fluid is running into his bladder through a 3-way catheter after TURP. Which statements by the nurse are accurate? Select all that apply.', '[{"id": "a", "text": "\"Sterile saline flows into your bladder continuously.\""}, {"id": "b", "text": "\"It flushes blood and prevents clot formation.\""}, {"id": "c", "text": "\"It removes the extra prostate tissue.\""}, {"id": "d", "text": "\"It prevents catheter blockage.\""}, {"id": "e", "text": "\"It replaces fluids so you need not drink.\""}]'::jsonb, '["a", "b", "d"]', 'In CBI, sterile saline continuously runs into the bladder via the 3-way Foley to flush blood and prevent clot formation and catheter blockage. Prostate tissue is removed during surgery with a resectoscope, and the client is still taught to drink 2–3 L of fluids daily unless restricted.', true),
  ('turp', 24, 'Two days after his catheter was removed following TURP, a 68-year-old client is upset because he leaks small amounts of urine. He asks, "Will I be like this forever?" Which response by the nurse is BEST?', '[{"id": "a", "text": "Leaking means the surgery failed, so I will notify the provider right now."}, {"id": "b", "text": "Leaking is a sign of TURP syndrome, so your sodium level must be checked."}, {"id": "c", "text": "Temporary incontinence is common; Kegel exercises and bladder training help."}, {"id": "d", "text": "Leaking means a straight catheter is needed until the bladder has fully healed."}]'::jsonb, '["c"]', 'Temporary incontinence is common post-op; the nurse reassures the client and teaches Kegels and bladder training. Straight catheterization is for inability to void after catheter removal, not leaking.', false),
  ('turp', 25, 'A 63-year-old client being discharged after TURP has been constipated and says, "If I need to, I will just push hard to have a bowel movement." Which response by the nurse is BEST?', '[{"id": "a", "text": "Pushing hard is fine once the CBI has been stopped and you are home."}, {"id": "b", "text": "Use a stool softener such as docusate; straining risks bleeding."}, {"id": "c", "text": "Pushing hard is fine if your urine has stayed light pink."}, {"id": "d", "text": "Limit fluids so that bowel movements become easier to pass."}]'::jsonb, '["b"]', 'Stool softeners such as docusate are used because straining raises abdominal pressure and risks bleeding. Light pink urine does not make straining safe, and fluids of 2–3 L daily are encouraged, not limited.', false),
  ('turp', 26, 'A nurse caring for a client on CBI after TURP reviews the irrigation protocol. Which actions are appropriate? Select all that apply.', '[{"id": "a", "text": "Slow irrigation rate when urine becomes clear"}, {"id": "b", "text": "Increase CBI rate when urine becomes clear"}, {"id": "c", "text": "Check for kinks when output decreases"}, {"id": "d", "text": "Flush per protocol for catheter blockage"}, {"id": "e", "text": "Stop the CBI when urine is light pink"}]'::jsonb, '["a", "c", "d"]', 'Clear urine calls for slowing the irrigation rate, and decreased output calls for checking for kinks or blockage and flushing per protocol. Increasing the rate is the response to bright red urine or clots, not clear urine, and light pink urine is the expected color, so CBI is not stopped for it.', true),
  ('turp', 27, 'A 70-year-old client is preparing for discharge after TURP and plans to drink very little to avoid leaking. Which response by the nurse BEST reflects the hydration teaching?', '[{"id": "a", "text": "Limit fluids to 1 L daily until bladder control has fully returned."}, {"id": "b", "text": "Drink fluids only when urine turns dark red to dilute any clots."}, {"id": "c", "text": "Drink 2–3 L of fluids daily, unless restricted, to flush the urinary tract."}, {"id": "d", "text": "Limit fluids because of the risk of hyponatremia from absorbing the irrigation fluid."}]'::jsonb, '["c"]', 'After TURP the client should drink 2–3 L of fluids daily unless restricted to flush the urinary tract, and temporary incontinence is managed with Kegels and bladder training. Fluid restriction is an inpatient action for TURP syndrome, not routine discharge teaching.', false),
  ('turp', 28, 'The nurse receives report on four clients after TURP. Which client should the nurse see FIRST?', '[{"id": "a", "text": "Bright red urine with clots, heart rate 118/min, blood pressure 90/54"}, {"id": "b", "text": "Light pink urine and a request for help with the urinal"}, {"id": "c", "text": "Leaking urine 1 day after the catheter was removed"}, {"id": "d", "text": "Cramping relieved 30 minutes after an oxybutynin dose"}]'::jsonb, '["a"]', 'Clots with tachycardia and hypotension represent a hemorrhagic emergency requiring STAT provider notification. Light pink urine is expected, leaking is common temporary incontinence, and relieved spasms are improving.', false),
  ('turp', 29, 'The nurse is assigned four clients after TURP. Which client should the nurse assess FIRST?', '[{"id": "a", "text": "Light pink drainage with the CBI running at the ordered rate"}, {"id": "b", "text": "Leaking small amounts after catheter removal"}, {"id": "c", "text": "Asking when sexual activity can safely resume"}, {"id": "d", "text": "New confusion and nausea with a heart rate of 50/min"}]'::jsonb, '["d"]', 'New confusion, nausea and bradycardia suggest TURP syndrome, hyponatremia from irrigant absorption that must be reported immediately. Light pink drainage is expected and leaking is common after catheter removal.', false),
  ('turp', 30, 'A 66-year-old client develops confusion, bradycardia, and nausea after TURP, and his serum sodium is low. Which actions should the nurse anticipate? Select all that apply.', '[{"id": "a", "text": "Monitor serum sodium"}, {"id": "b", "text": "Encourage 2–3 L of fluids"}, {"id": "c", "text": "Restrict fluids"}, {"id": "d", "text": "Report immediately"}, {"id": "e", "text": "Give oxybutynin"}]'::jsonb, '["a", "c", "d"]', 'TURP syndrome (hyponatremia from irrigant absorption) is managed by monitoring serum Na⁺, restricting fluids and reporting immediately. Encouraging 2–3 L of fluids is discharge teaching and would worsen hyponatremia, and oxybutynin treats bladder spasms.', true),
  ('turp', 31, 'A 67-year-old client is reviewing his discharge teaching after TURP with the nurse. Which statements by the client indicate a need for further teaching? Select all that apply.', '[{"id": "a", "text": "\"Light pink urine is expected.\""}, {"id": "b", "text": "\"I can resume sexual activity after 1 week.\""}, {"id": "c", "text": "\"Retrograde ejaculation may affect fertility.\""}, {"id": "d", "text": "\"Leaking urine means my surgery failed.\""}, {"id": "e", "text": "\"I should report bright red urine.\""}]'::jsonb, '["b", "d"]', 'Sexual activity is avoided for 4–6 weeks, not 1 week, and temporary incontinence is common post-op rather than a sign of failure, so both statements need correction. Light pink urine is expected, retrograde ejaculation is harmless but may affect fertility, and dark or bright red urine is reported.', true),
  ('turp', 32, 'A 69-year-old client asks how his prostate was removed because he cannot find an incision on his abdomen after TURP. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "Tissue was removed through the urethra with a resectoscope; no external incision."}, {"id": "b", "text": "The incision is hidden inside the rectum, so it cannot be seen from the outside."}, {"id": "c", "text": "A small incision was made in the perineum and was closed with sutures that dissolve."}, {"id": "d", "text": "The prostate was shrunk with medication, so no tissue was actually removed."}]'::jsonb, '["a"]', 'TURP removes excess prostate tissue through the urethra using a resectoscope, with no external incision. Shrinking the prostate describes medication therapy, not TURP.', false),
  ('turp', 33, 'Before surgery, a 72-year-old client who has taken BPH medications for 2 years without relief asks why TURP was chosen for him. Which response by the nurse is BEST?', '[{"id": "a", "text": "It is the first-line treatment before any BPH medication is tried."}, {"id": "b", "text": "It is used only when the prostate is found to be cancerous."}, {"id": "c", "text": "It is the most common surgery for BPH refractory to medication."}, {"id": "d", "text": "It is chosen because it needs an incision for full tissue removal."}]'::jsonb, '["c"]', 'TURP is the most common surgery for BPH refractory to medication, which matches this client. TURP has no external incision because tissue is removed through the urethra.', false),
  ('turp', 34, 'A new nurse is caring for several clients on CBI after TURP. Which action by the new nurse requires immediate intervention?', '[{"id": "a", "text": "Slowing the CBI rate when the drainage becomes clear"}, {"id": "b", "text": "Slowing the CBI rate for bright red urine with clots"}, {"id": "c", "text": "Checking for kinks when output drops and spasms begin"}, {"id": "d", "text": "Monitoring serum sodium in a client who is confused"}]'::jsonb, '["b"]', 'Bright red urine or clots require increasing the CBI rate and notifying the provider, so slowing it is incorrect. Slowing the rate for clear urine, checking for kinks with decreased output, and monitoring sodium for TURP syndrome are all correct.', false),
  ('turp', 35, 'A 67-year-old client asks which activities he must avoid for 4–6 weeks after TURP. Which activities should the nurse include? Select all that apply.', '[{"id": "a", "text": "Heavy lifting"}, {"id": "b", "text": "Drinking 2–3 L of fluids"}, {"id": "c", "text": "Sexual activity"}, {"id": "d", "text": "Kegel exercises"}, {"id": "e", "text": "Straining at stool"}]'::jsonb, '["a", "c", "e"]', 'Heavy lifting and sexual activity are restricted for 4–6 weeks, and straining is avoided because it raises abdominal pressure and risks bleeding. Drinking 2–3 L of fluids daily and Kegel exercises are encouraged after TURP.', true),
  ('turp', 36, 'A 65-year-old client 10 days after TURP asks when he and his partner can resume sexual activity. Which time frame should the nurse BEST teach?', '[{"id": "a", "text": "After 1 week"}, {"id": "b", "text": "After 2 weeks"}, {"id": "c", "text": "After 6 months"}, {"id": "d", "text": "After 4–6 weeks"}]'::jsonb, '["d"]', 'Sexual activity, like heavy lifting, is avoided for 4–6 weeks after TURP. At 10 days the client is still within the restricted period.', false),
  ('turp', 37, 'Two clients on a urology unit are being assessed after TURP. One has a fever, cloudy foul urine, and suprapubic tenderness; the other has cramping and an urge to void with his catheter in place. Which interpretation is MOST accurate?', '[{"id": "a", "text": "The first suggests bladder spasms; the second suggests infection."}, {"id": "b", "text": "Both findings suggest hemorrhage that requires an increased CBI rate now."}, {"id": "c", "text": "Both findings suggest TURP syndrome from irrigant absorption."}, {"id": "d", "text": "The first suggests infection; the second suggests bladder spasms."}]'::jsonb, '["d"]', 'Fever, cloudy/foul urine and suprapubic tenderness indicate infection, while an urge to void with the catheter in place plus cramping indicates bladder spasms. Hemorrhage shows bright red urine and clots, and TURP syndrome shows confusion and bradycardia.', false),
  ('turp', 38, 'The nurse reviews laboratory orders for a client after TURP. Which pairings of laboratory test and purpose are correct? Select all that apply.', '[{"id": "a", "text": "Hematocrit/hemoglobin — detect bleeding"}, {"id": "b", "text": "BUN/creatinine — detect post-op bleeding"}, {"id": "c", "text": "Serum sodium — monitor for TURP syndrome"}, {"id": "d", "text": "Urinalysis/culture — rule out infection"}, {"id": "e", "text": "BUN/creatinine — assess renal function"}]'::jsonb, '["a", "c", "d", "e"]', 'Hematocrit/hemoglobin detect post-op bleeding, serum sodium monitors for TURP syndrome (hyponatremia), urinalysis/culture rules out infection, and BUN/creatinine assess renal function after urinary obstruction. BUN/creatinine are not the tests for detecting bleeding.', true),
  ('turp', 39, 'A 74-year-old client on CBI after TURP has bright red drainage with clots, a heart rate rising to 116/min, and hemoglobin falling on serial checks. After notifying the provider and increasing the CBI rate, what should the nurse anticipate NEXT?', '[{"id": "a", "text": "Preparing for transfusion"}, {"id": "b", "text": "Restricting fluids"}, {"id": "c", "text": "Slowing the irrigation"}, {"id": "d", "text": "Giving oxybutynin"}]'::jsonb, '["a"]', 'Hemorrhage after TURP is managed by reporting immediately, increasing CBI and preparing for transfusion. Fluid restriction is a TURP syndrome action, and slowing irrigation is for clear urine.', false),
  ('turp', 40, 'The nurse is about to remove the 3-way Foley from a 66-year-old client whose CBI has been discontinued after TURP. Which assessment is MOST important after the catheter is removed?', '[{"id": "a", "text": "Checking the serum sodium"}, {"id": "b", "text": "Monitoring the first void"}, {"id": "c", "text": "Teaching about retrograde ejaculation"}, {"id": "d", "text": "Checking the tubing for kinks"}]'::jsonb, '["b"]', 'After the catheter is removed as ordered, the nurse monitors the first void to detect post-catheter urinary retention. Checking tubing for kinks applies while the catheter is in place.', false),
  ('turp', 41, 'A 63-year-old client is counseled about retrograde ejaculation before discharge after TURP. Which statements by the nurse are accurate? Select all that apply.', '[{"id": "a", "text": "\"It is a sign of bleeding.\""}, {"id": "b", "text": "\"Semen enters the bladder.\""}, {"id": "c", "text": "\"It means you have an infection.\""}, {"id": "d", "text": "\"It is harmless but may affect fertility.\""}, {"id": "e", "text": "\"It will need surgery to correct.\""}]'::jsonb, '["b", "d"]', 'In retrograde ejaculation, semen enters the bladder instead of exiting; it is harmless but may affect fertility, so the client is counseled. It is not a sign of bleeding or infection and is described as harmless, not as something requiring surgery.', true),
  ('turp', 42, 'The daughter of a 72-year-old client asks why her father became confused and had a seizure after his TURP. Which explanation by the nurse is MOST accurate?', '[{"id": "a", "text": "Hemorrhage from the prostate bed, causing low blood pressure"}, {"id": "b", "text": "Infection of the urinary tract that has spread to the blood"}, {"id": "c", "text": "Hyponatremia from irrigant absorption, called TURP syndrome"}, {"id": "d", "text": "Bladder spasms from the catheter, causing severe cramping"}]'::jsonb, '["c"]', 'TURP syndrome is hyponatremia from irrigant absorption and causes confusion and seizures. Hemorrhage presents with bright red urine, clots, tachycardia and hypotension instead.', false),
  ('turp', 43, 'In the first 24 hours after TURP, a 69-year-old client has a 3-way Foley with CBI. Which nursing focus is the PRIORITY during this period?', '[{"id": "a", "text": "Teaching Kegels for urinary control"}, {"id": "b", "text": "CBI care and urine color monitoring"}, {"id": "c", "text": "Counseling about retrograde ejaculation"}, {"id": "d", "text": "Reviewing lifting limits for 4–6 weeks"}]'::jsonb, '["b"]', 'CBI is the nursing priority after TURP; pink urine is normal and bright red urine or clots signal an emergency. Kegels, retrograde ejaculation counseling and activity restrictions are later discharge teaching.', false),
  ('turp', 44, 'A 68-year-old client has just had his catheter removed after TURP. Which actions by the nurse are appropriate? Select all that apply.', '[{"id": "a", "text": "Assess the first void"}, {"id": "b", "text": "Restrict fluids to reduce leaking"}, {"id": "c", "text": "Straight catheterize if unable to void"}, {"id": "d", "text": "Teach Kegels for urinary control"}, {"id": "e", "text": "Restart CBI if leaking occurs"}]'::jsonb, '["a", "c", "d"]', 'After catheter removal the nurse assesses the first void, straight catheterizes if the client cannot void, and teaches Kegels to help regain urinary control. Fluids of 2–3 L daily are encouraged rather than restricted, and leaking is common temporary incontinence, not a reason to restart CBI.', true),
  ('turp', 45, 'A client discharged 4 days after TURP calls the clinic and reports that his urine has turned dark red since this morning. Which instruction by the nurse is BEST?', '[{"id": "a", "text": "Dark red urine is expected and needs no follow-up."}, {"id": "b", "text": "Dark red urine is from retrograde ejaculation and is harmless."}, {"id": "c", "text": "Dark red urine will clear if you strain to empty fully."}, {"id": "d", "text": "Report dark red urine; it is not the expected color."}]'::jsonb, '["d"]', 'Light pink is the expected urine color after TURP, whereas dark or bright red urine must be reported. Straining is avoided because it raises abdominal pressure and risks bleeding.', false),
  ('turp', 46, 'A client on CBI had 3,000 mL of irrigant in the first bag fully infused and a second 3,000-mL bag hung with 1,200 mL still remaining at the end of the shift. Total drainage for the shift was 5,350 mL. Which true urine output is MOST accurate for the nurse to record?', '[{"id": "a", "text": "550 mL"}, {"id": "b", "text": "2,350 mL"}, {"id": "c", "text": "−650 mL"}, {"id": "d", "text": "6,550 mL"}]'::jsonb, '["a"]', 'Irrigant infused = 3,000 + (3,000 − 1,200) = 4,800 mL, so true urine output = 5,350 − 4,800 = 550 mL. Subtracting the full 6,000 mL ignores the 1,200 mL still in the bag and wrongly gives −650 mL.', false),
  ('turp', 47, 'The nurse reviews 4-hour CBI totals for four clients after TURP. Client 1: irrigant 1,000 mL, drainage 1,180 mL. Client 2: irrigant 1,200 mL, drainage 1,350 mL. Client 3: irrigant 1,500 mL, drainage 1,320 mL. Client 4: irrigant 1,000 mL, drainage 1,100 mL. Which client requires IMMEDIATE follow-up?', '[{"id": "a", "text": "Client 1"}, {"id": "b", "text": "Client 2"}, {"id": "c", "text": "Client 3"}, {"id": "d", "text": "Client 4"}]'::jsonb, '["c"]', 'Client 3 drained 180 mL less than the irrigant infused, so output is decreased and the catheter must be checked for kinks or blockage; the other clients have true urine outputs of 180, 150 and 100 mL. Decreased output is a finding the nurse must report, whereas Clients 1, 2 and 4 drained more than the irrigant infused.', false),
  ('turp', 48, 'On day 1 after TURP, a 67-year-old client''s CBI drainage is dark red without visible clots, and his vital signs are stable. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Report the dark red urine to the provider"}, {"id": "b", "text": "Document it as the expected urine color"}, {"id": "c", "text": "Slow the irrigation rate until the drainage clears"}, {"id": "d", "text": "Stop the CBI and remove the catheter"}]'::jsonb, '["a"]', 'The expected color is light pink, not dark red or bright red, and dark red urine is reported. Slowing the irrigation rate is only for clear urine.', false),
  ('turp', 49, 'A 64-year-old client asks the nurse how the Kegel exercises he was taught will help him after his catheter is removed following TURP. Which statement by the client indicates understanding?', '[{"id": "a", "text": "\"They help prevent clots from blocking my catheter.\""}, {"id": "b", "text": "\"They help my body absorb less of the irrigant used during surgery.\""}, {"id": "c", "text": "\"They prevent retrograde ejaculation from occurring.\""}, {"id": "d", "text": "\"They help me regain urinary control after catheter removal.\""}]'::jsonb, '["d"]', 'Kegel exercises help regain urinary control after catheter removal and are taught for temporary incontinence. Preventing clots and maintaining catheter patency is the purpose of CBI.', false),
  ('turp', 50, 'Two hours after TURP, a 70-year-old client''s CBI is running and the drainage is light pink. The client reports intense cramping and an urge to void. Which explanation of this finding is MOST accurate?', '[{"id": "a", "text": "TURP syndrome from irrigant absorption, so restrict the client''s fluids"}, {"id": "b", "text": "Bladder spasms from the catheter, so check the catheter and treat"}, {"id": "c", "text": "Hemorrhage from the prostate, so prepare for transfusion"}, {"id": "d", "text": "Infection of the urinary tract, so obtain cultures first"}]'::jsonb, '["b"]', 'Urge to void with the catheter in place and cramping are bladder spasms; the nurse checks the catheter and treats with antispasmodics. TURP syndrome presents with confusion and bradycardia, and hemorrhage with bright red urine and clots.', false),
  ('contraception', 1, 'A 36-year-old client who smokes 10 cigarettes daily and has no other health history asks to start a combined estrogen-progestin pill. Which response by the nurse is BEST?', '[{"id": "a", "text": "Estrogen-containing contraceptives are contraindicated in smokers older than 35 years; other methods need review."}, {"id": "b", "text": "The combined pill is a safe choice for you as long as you take each pill at the same time daily."}, {"id": "c", "text": "The combined pill is a good choice for you because it also lowers your risk of sexually transmitted infections as well."}, {"id": "d", "text": "You may start the combined pill today and report any nausea or breast tenderness to the provider right away."}]'::jsonb, '["a"]', 'At 36 years old and smoking, this client falls under ''smokers older than 35 years,'' an estrogen contraindication, so the request must be redirected. Taking the pill at the same time daily is correct teaching but does not make an estrogen method safe for her, and only condoms prevent STIs.', false),
  ('contraception', 2, 'A 30-year-old client requests a combined estrogen-progestin pill, and the nurse reviews her health history. Which findings require follow-up with the health care provider before the pill is started? Select all that apply.', '[{"id": "a", "text": "Migraine headaches with aura"}, {"id": "b", "text": "Breakthrough bleeding on a prior pill"}, {"id": "c", "text": "Pulmonary embolism three years ago"}, {"id": "d", "text": "Breast tenderness on a prior pill"}, {"id": "e", "text": "History of liver disease"}]'::jsonb, '["a", "c", "e"]', 'Correct: migraine with aura, a history of PE (blood clots), and liver disease are each listed estrogen contraindications. Wrong: breakthrough bleeding and breast tenderness are common side effects of hormonal contraceptives, not contraindications.', true),
  ('contraception', 3, 'A 27-year-old client who started a combined oral contraceptive 6 weeks ago calls the clinic reporting severe pain and swelling in her left calf since this morning. Which action by the nurse is the PRIORITY?', '[{"id": "a", "text": "Explain that mild leg aches are a common side effect during the first several months of combined pill use."}, {"id": "b", "text": "Tell her severe leg pain must be reported immediately as a possible DVT (deep vein thrombosis)."}, {"id": "c", "text": "Remind her to take each pill at the same time daily so that hormone levels stay steady."}, {"id": "d", "text": "Advise her to use a backup method until her next menstrual period begins this month."}]'::jsonb, '["b"]', 'Severe leg pain is the ''S'' in ACHES, a warning sign of DVT that is reported immediately. The common side effects of hormonal contraception are nausea, breast tenderness, mood changes, and breakthrough bleeding, not leg pain.', false),
  ('contraception', 4, 'A 24-year-old client using a hormonal contraceptive patch calls the nurse line with several concerns. Which findings require IMMEDIATE follow-up? Select all that apply.', '[{"id": "a", "text": "Mild breast tenderness"}, {"id": "b", "text": "Sudden chest pain"}, {"id": "c", "text": "Severe leg pain"}, {"id": "d", "text": "Severe abdominal pain"}, {"id": "e", "text": "New vision changes"}]'::jsonb, '["b", "c", "d", "e"]', 'Correct: chest pain (possible PE), severe leg pain (DVT), abdominal pain (liver, ectopic pregnancy, gallbladder), and eye problems such as vision changes (stroke, HTN) are ACHES warning signs to report immediately. Wrong: mild breast tenderness is listed as a common side effect, not a warning sign.', true),
  ('contraception', 5, 'A 22-year-old client who began a combined pill 3 weeks ago reports mild nausea and some spotting between periods. She denies chest, leg, or abdominal pain, headache, and eye problems. Which response by the nurse is BEST?', '[{"id": "a", "text": "Stop the pill now and use condoms until you can be examined by the provider this week."}, {"id": "b", "text": "Spotting between periods is a hormonal warning sign that must be reported to the provider later today."}, {"id": "c", "text": "Nausea and breakthrough bleeding are common side effects; keep taking the pill at the same time daily."}, {"id": "d", "text": "Take an extra pill today, because spotting means that your hormone levels have dropped too low."}]'::jsonb, '["c"]', 'With no ACHES findings, nausea and breakthrough bleeding match the listed common side effects, and taking the pill at the same time daily maintains hormone levels. Spotting is not one of the ACHES warning signs, so it does not require urgent reporting.', false),
  ('contraception', 6, 'A client who takes a combined oral contraceptive every evening at 9 PM realizes at 7 AM the next morning that she forgot last night''s pill. It is the only pill she has missed in this pack. Which instruction by the nurse is BEST?', '[{"id": "a", "text": "Skip the missed pill and take tonight''s pill at the usual time."}, {"id": "b", "text": "Stop this pack and begin a new pack after your next period."}, {"id": "c", "text": "Double the dose each evening for the next 7 days to catch up on hormones."}, {"id": "d", "text": "Take the missed pill ASAP and keep taking pills at the same time daily."}]'::jsonb, '["d"]', 'For a missed pill the teaching is to take it ASAP, then continue at the same time daily to maintain hormone levels. Skipping it, stopping the pack, or doubling doses for a week does not follow this teaching.', false),
  ('contraception', 7, 'A 19-year-old client reports unprotected intercourse 4 days ago and asks the nurse for emergency contraception. Which option should the nurse expect to be MOST effective at this point?', '[{"id": "a", "text": "Plan B (levonorgestrel) taken today"}, {"id": "b", "text": "Copper IUD inserted within 5 days"}, {"id": "c", "text": "Nexplanon implant inserted today"}, {"id": "d", "text": "Depot-Provera injection given today"}]'::jsonb, '["b"]', 'Four days is 96 hours, beyond the 72-hour window for Plan B, while the copper IUD is the most effective emergency method within 5 days. The implant and injection are not listed as emergency methods.', false),
  ('contraception', 8, 'A 20-year-old client had unprotected intercourse 30 hours ago and chooses an oral emergency method. Which statement by the client indicates understanding of the teaching?', '[{"id": "a", "text": "I have up to 5 days to take Plan B, so I can wait until the weekend."}, {"id": "b", "text": "Plan B will also protect me from sexually transmitted infections."}, {"id": "c", "text": "I need to take Plan B (levonorgestrel) within 72h of having sex."}, {"id": "d", "text": "Plan B is the most effective emergency method that I could choose."}]'::jsonb, '["c"]', 'Plan B (levonorgestrel) is taken within 72h; the 5-day window and ''most effective'' description belong to the copper IUD. Only condoms prevent STIs.', false),
  ('contraception', 9, 'A nurse is teaching a group of college students about emergency contraception after a client asks about options. Which statements by students indicate understanding? Select all that apply.', '[{"id": "a", "text": "Plan B is taken within 72h as an emergency method."}, {"id": "b", "text": "A copper IUD is the most effective emergency method within 5 days."}, {"id": "c", "text": "Plan B will also protect me from sexually transmitted infections."}, {"id": "d", "text": "A diaphragm put in the morning after sex works as an emergency method."}, {"id": "e", "text": "Plan B can still be taken up to 5 days after sex."}]'::jsonb, '["a", "b"]', 'Correct: Plan B (levonorgestrel) is taken within 72h, and the copper IUD is the most effective emergency method within 5 days. Wrong: only condoms prevent STIs; the 5-day window belongs to the copper IUD, not Plan B; and the diaphragm is a barrier method used with spermicide at the time of sex, not an emergency method.', true),
  ('contraception', 10, 'A nurse at a women''s health clinic receives four messages. Which client should the nurse contact FIRST?', '[{"id": "a", "text": "A client on Depot-Provera asking how to add calcium and vitamin D"}, {"id": "b", "text": "A client with a Nexplanon implant asking when the implant should be removed and replaced"}, {"id": "c", "text": "A client asking whether her diaphragm protects her against STIs"}, {"id": "d", "text": "A client 3 weeks after IUD insertion with fever and foul discharge"}]'::jsonb, '["d"]', 'Fever and foul discharge after IUD insertion are the ''I'' (infection) in PAINS, an IUD danger sign; infection is a listed IUD risk. The other clients have teaching questions that are not urgent.', false),
  ('contraception', 11, 'During her monthly self-check, a client with a copper IUD inserted 5 months ago cannot feel the IUD strings. She has no pain or fever. Which action by the nurse is BEST?', '[{"id": "a", "text": "Tell her to report it, since a missing string may indicate expulsion or migration."}, {"id": "b", "text": "Reassure her that the strings often soften and cannot be felt after a few months of use."}, {"id": "c", "text": "Advise her to wait and recheck the strings at her yearly gynecologic examination."}, {"id": "d", "text": "Instruct her to take Plan B tonight as a precaution and then recheck next month."}]'::jsonb, '["a"]', 'A missing string must be reported because it may indicate expulsion or migration of the IUD; ''S — String missing'' is a PAINS danger sign even without pain or fever. Waiting until a yearly examination ignores this red flag.', false),
  ('contraception', 12, 'A client who had a Mirena hormonal IUD inserted 2 months ago calls the clinic. Which reports require follow-up as IUD danger signs? Select all that apply.', '[{"id": "a", "text": "My period is 2 weeks late."}, {"id": "b", "text": "I can''t find my strings this month."}, {"id": "c", "text": "I''ve had a fever and foul discharge."}, {"id": "d", "text": "I have not been feeling well this week."}, {"id": "e", "text": "I can feel the strings like last month."}]'::jsonb, '["a", "b", "c", "d"]', 'Correct: a late period (possible pregnancy), a string missing (possible expulsion or migration), infection signs such as fever and foul discharge, and not feeling well are PAINS danger signs. Wrong: being able to feel the strings at the monthly check confirms the IUD is in position.', true),
  ('contraception', 13, 'A nurse is teaching a client immediately after Paragard copper IUD insertion. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "Some slight cramping and spotting today is normal after the insertion."}, {"id": "b", "text": "This IUD will not protect me from STIs, so I will still use condoms every time."}, {"id": "c", "text": "Abdominal pain with a fever next week is expected while I adjust to the IUD."}, {"id": "d", "text": "If my period is late, I will call because it could mean a pregnancy."}]'::jsonb, '["c"]', 'Abdominal pain and infection signs such as fever are PAINS danger signs, not expected findings; only slight cramping and spotting immediately after insertion are normal. The other statements are correct.', false),
  ('contraception', 14, 'A 25-year-old client is starting Depot-Provera injections. Which teaching point is MOST important for the nurse to include?', '[{"id": "a", "text": "Take the medication at the same time each day so that the hormone levels stay steady."}, {"id": "b", "text": "Check for the device strings monthly to confirm that the method is still in position."}, {"id": "c", "text": "Have the device removed and replaced after 3 years of continuous use in the upper arm."}, {"id": "d", "text": "Return for an injection every 3 months; calcium and Vit D help protect bone density."}]'::jsonb, '["d"]', 'Depot-Provera is an injection every 3 months that may cause bone density loss, so calcium and Vit D are monitored. Same-time-daily dosing applies to pills, string checks to IUDs, and 3-year replacement to Nexplanon.', false),
  ('contraception', 15, 'A client had a Nexplanon implant inserted 34 months ago and says she wants to keep using the same method. Which response by the nurse is BEST?', '[{"id": "a", "text": "The implant lasts up to 3 years, so plan its replacement within about 2 months."}, {"id": "b", "text": "The implant lasts 5 years, so no change is needed for about 2 more years."}, {"id": "c", "text": "Schedule your next injection now, since this method is renewed every 3 months."}, {"id": "d", "text": "Check the strings monthly; the implant is replaced only if the strings go missing."}]'::jsonb, '["a"]', 'Nexplanon lasts up to 3 years (36 months), so at 34 months replacement is due in about 2 months. Every-3-month renewal describes Depot-Provera, and string checks apply to IUDs.', false),
  ('contraception', 16, 'A client who uses a diaphragm with spermicide had intercourse at 10 PM. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "I''ll leave the diaphragm in place until at least 4 AM tomorrow."}, {"id": "b", "text": "I''ll take the diaphragm out at midnight so it doesn''t irritate me."}, {"id": "c", "text": "I use spermicide with my diaphragm every time I put it in before sex."}, {"id": "d", "text": "My diaphragm doesn''t prevent STIs, so we also use condoms."}]'::jsonb, '["b"]', 'The diaphragm must be left in 6h after sex; removing it at midnight is only 2 hours, whereas 4 AM is 6 hours. Using it with spermicide and adding condoms for STI protection are correct.', false),
  ('contraception', 17, 'A 23-year-old client with a Mirena IUD tells the nurse that she has a new sexual partner and asks whether she needs anything else. Which response by the nurse is BEST?', '[{"id": "a", "text": "Your IUD is highly effective, so no added protection is necessary for you."}, {"id": "b", "text": "Ask your provider for a diaphragm, which also prevents STIs well."}, {"id": "c", "text": "Add a combined pill, because two hormonal methods block infection."}, {"id": "d", "text": "Only condoms prevent STIs, so use condoms in addition to your IUD."}]'::jsonb, '["d"]', 'Only condoms prevent STIs, so even a highly effective LARC method must be paired with condoms for STI protection. A diaphragm is a barrier method but is not described as preventing STIs.', false),
  ('contraception', 18, 'A 26-year-old client says she wants a reversible method that is as effective as possible because she may want children in about 3 years. Which methods would the nurse expect to discuss as meeting her goals? Select all that apply.', '[{"id": "a", "text": "Tubal ligation"}, {"id": "b", "text": "Mirena hormonal IUD"}, {"id": "c", "text": "Combined oral pill"}, {"id": "d", "text": "Paragard copper IUD"}, {"id": "e", "text": "Nexplanon implant"}]'::jsonb, '["b", "d", "e"]', 'Correct: Mirena, Paragard, and the Nexplanon implant are LARC methods, the most effective reversible methods. Wrong: tubal ligation is surgical and irreversible, and the combined pill is a short-acting hormonal method that depends on daily use.', true),
  ('contraception', 19, 'A 28-year-old client scheduled for tubal ligation tells the nurse, "If we decide we want another baby, I can just have it reversed." Which action by the nurse is the PRIORITY?', '[{"id": "a", "text": "Ensure informed consent by notifying the provider that she believes it is reversible."}, {"id": "b", "text": "Continue the preoperative teaching about how the surgical procedure is performed tomorrow."}, {"id": "c", "text": "Document the statement and reinforce that this method is a surgical procedure."}, {"id": "d", "text": "Suggest that her partner consider having a vasectomy instead of her surgery."}]'::jsonb, '["a"]', 'Tubal ligation is surgical and irreversible, and informed consent is required for permanent methods; her statement shows consent is not informed, so the provider must be notified before proceeding. Vasectomy is also permanent, so suggesting it does not correct the misunderstanding.', false),
  ('contraception', 20, 'A 32-year-old client asks the nurse, "Which birth control is right for me?" Which action should the nurse take FIRST?', '[{"id": "a", "text": "Recommend an IUD, since LARC methods are the most effective."}, {"id": "b", "text": "Assess her preference, lifestyle, and medical history."}, {"id": "c", "text": "Teach her to take a pill at the same time every day."}, {"id": "d", "text": "Review the ACHES warning signs of hormonal methods."}]'::jsonb, '["b"]', 'The nurse must assess patient preference, lifestyle, and medical history before recommending contraception; this also screens for estrogen contraindications. Recommending a method or teaching about one comes after assessment.', false),
  ('contraception', 21, 'A 29-year-old client using a combined pill has had a blood pressure above her baseline at her last two visits. She has no other symptoms. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Reassure her that blood pressure changes are a common side effect of the combined pill."}, {"id": "b", "text": "Teach her to take the pill in the morning to lower her blood pressure readings."}, {"id": "c", "text": "Report the findings to the provider, since hormonal methods carry a risk of HTN."}, {"id": "d", "text": "Advise her to stop the pill and take Plan B if she has intercourse this month."}]'::jsonb, '["c"]', 'Hormonal short-acting methods carry a risk of DVT and HTN, so a rising blood pressure is reported. The listed common side effects are nausea, breast tenderness, mood changes, and breakthrough bleeding, not blood pressure changes.', false),
  ('contraception', 22, 'A 34-year-old client taking a combined oral contraceptive calls reporting a sudden, severe headache with blurred vision that started an hour ago. The nurse recognizes these findings as MOST concerning for which complication?', '[{"id": "a", "text": "Stroke"}, {"id": "b", "text": "Pulmonary embolism"}, {"id": "c", "text": "Ectopic pregnancy"}, {"id": "d", "text": "Deep vein thrombosis"}]'::jsonb, '["a"]', 'In ACHES, headache and eye problems (vision changes) point to stroke. Pulmonary embolism presents as chest pain and DVT as severe leg pain; ectopic pregnancy is linked to abdominal pain.', false),
  ('contraception', 23, 'A 30-year-old client taking a combined pill calls to report severe abdominal pain that began yesterday. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "It is a common side effect of the pill that needs no follow-up unless it lasts several weeks."}, {"id": "b", "text": "It is an ACHES warning sign that may indicate liver, gallbladder, or ectopic problems."}, {"id": "c", "text": "It suggests that a pill was missed and that a backup method is now needed this week."}, {"id": "d", "text": "It is expected only during the first week of each new pill pack and then resolves."}]'::jsonb, '["b"]', 'Abdominal pain is the ''A'' in ACHES (liver, ectopic pregnancy, gallbladder) and is reported immediately. It is not among the listed common side effects.', false),
  ('contraception', 24, 'A 31-year-old client with a history of DVT asks which birth control options she can use. Which methods would be appropriate for the nurse to discuss? Select all that apply.', '[{"id": "a", "text": "Combined estrogen-progestin pill"}, {"id": "b", "text": "Paragard copper IUD"}, {"id": "c", "text": "Diaphragm with spermicide"}, {"id": "d", "text": "Estrogen-containing patch"}, {"id": "e", "text": "Male or female condoms"}]'::jsonb, '["b", "c", "e"]', 'Correct: the Paragard copper IUD and barrier methods (condoms, diaphragm with spermicide) contain no estrogen. Wrong: the combined pill and an estrogen-containing patch are estrogen-containing contraceptives, which are contraindicated with a history of DVT or PE.', true),
  ('contraception', 25, 'The nurse at a family planning clinic reviews four phone messages. Which client should the nurse call back FIRST?', '[{"id": "a", "text": "A client on Depot-Provera who asks when her next injection is due"}, {"id": "b", "text": "A client with a Nexplanon implant asking about the insertion site"}, {"id": "c", "text": "A client on a combined pill who reports new, sudden chest pain"}, {"id": "d", "text": "A client taking a combined pill with breast tenderness and mood changes"}]'::jsonb, '["c"]', 'Chest pain is the ''C'' in ACHES and may indicate PE (pulmonary embolism), which is reported immediately. Breast tenderness and mood changes are common side effects, and the other calls are routine questions.', false),
  ('contraception', 26, 'A 27-year-old client who often forgets daily medications wants a method she does not take every day and is deciding between Depot-Provera and Nexplanon. Which statements by the nurse are accurate? Select all that apply.', '[{"id": "a", "text": "Depot-Provera may cause bone density loss."}, {"id": "b", "text": "Nexplanon must be replaced every year."}, {"id": "c", "text": "Depot-Provera is taken as a daily pill."}, {"id": "d", "text": "Nexplanon is inserted subdermally in the upper arm."}, {"id": "e", "text": "Depot-Provera is an injection given every 3 months."}]'::jsonb, '["a", "d", "e"]', 'Correct: Depot-Provera is an injection every 3 months that may cause bone density loss, and Nexplanon is inserted subdermally in the upper arm. Wrong: Nexplanon lasts up to 3 years, not 1 year, and Depot-Provera is an injection, not a daily pill.', true),
  ('contraception', 27, 'A 51-year-old client reports hot flashes and says that her last menstrual period was 9 months ago. She asks whether she has reached menopause. Which response by the nurse is BEST?', '[{"id": "a", "text": "Yes; 6 months without a period confirms menopause has occurred."}, {"id": "b", "text": "Yes; hot flashes by themselves confirm that menopause has begun."}, {"id": "c", "text": "Not yet; menopause is diagnosed when estrogen levels start to rise again."}, {"id": "d", "text": "Not yet; menopause is cessation of menses for 12 consecutive months."}]'::jsonb, '["d"]', 'Menopause is cessation of menses for 12 consecutive months; 9 months does not meet that definition even with hot flashes. Menopause is caused by a decline, not a rise, in estrogen.', false),
  ('contraception', 28, 'A 50-year-old client whose last menstrual period was 14 months ago reports several concerns at her annual visit. Which findings would the nurse recognize as expected with her condition? Select all that apply.', '[{"id": "a", "text": "Hot flashes at night"}, {"id": "b", "text": "Vaginal dryness"}, {"id": "c", "text": "Rising estrogen levels"}, {"id": "d", "text": "Sleep disturbances"}, {"id": "e", "text": "Mood swings"}]'::jsonb, '["a", "b", "d", "e"]', 'Correct: 14 months without menses meets the 12-month definition of menopause, and hot flashes, vaginal dryness, sleep disturbances, and mood swings are listed symptoms. Wrong: menopause is caused by a decline in estrogen, not rising estrogen levels.', true),
  ('contraception', 29, 'A 53-year-old client with a history of breast cancer reports frequent hot flashes and sleep disturbances and asks to start hormone replacement therapy. Which response by the nurse is BEST?', '[{"id": "a", "text": "HRT is safe for you because it can be given as estrogen alone, without any added progesterone component."}, {"id": "b", "text": "HRT is contraindicated with a history of breast cancer; let''s discuss options with your provider."}, {"id": "c", "text": "HRT will be started at a low dose, because your hot flashes are frequent and disruptive."}, {"id": "d", "text": "HRT is appropriate because your symptoms are caused by a decline in your estrogen level."}]'::jsonb, '["b"]', 'HRT is contraindicated with a history of breast cancer, and breast cancer is also a listed risk of HRT. Although menopause symptoms are caused by declining estrogen, that does not override the contraindication.', false),
  ('contraception', 30, 'A nurse reviews the record of a 52-year-old client being considered for HRT (estrogen ± progesterone) for menopausal symptoms. Which findings require follow-up with the provider before HRT is started? Select all that apply.', '[{"id": "a", "text": "Vaginal dryness with intercourse"}, {"id": "b", "text": "History of clotting disorders"}, {"id": "c", "text": "Mood swings and hot flashes"}, {"id": "d", "text": "History of liver disease"}, {"id": "e", "text": "Sleep disturbances at night"}]'::jsonb, '["b", "d"]', 'Correct: clotting disorders and liver disease are listed contraindications to HRT. Wrong: vaginal dryness, mood swings, hot flashes, and sleep disturbances are menopause symptoms that HRT is used to treat, not contraindications.', true),
  ('contraception', 31, 'A 55-year-old postmenopausal client asks how she can lower her osteoporosis risk without medication. Which recommendations should the nurse include? Select all that apply.', '[{"id": "a", "text": "Limiting activity to protect her bones"}, {"id": "b", "text": "Weight-bearing exercise such as walking"}, {"id": "c", "text": "Calcium + Vitamin D supplementation"}, {"id": "d", "text": "Starting HRT to replace estrogen"}, {"id": "e", "text": "Avoiding smoking and alcohol"}]'::jsonb, '["b", "c", "e"]', 'Correct: weight-bearing exercise, calcium + Vitamin D supplementation, and avoiding smoking and alcohol are the listed non-pharmacological measures. Wrong: limiting activity is the opposite of weight-bearing exercise, and HRT is a hormone medication, not a non-pharmacological measure.', true),
  ('contraception', 32, 'A client at 12 weeks'' gestation has vaginal bleeding, hyperemesis gravidarum, a uterus larger than expected for gestational age, and a markedly elevated hCG. Which ultrasound result is an expected finding for this client''s condition?', '[{"id": "a", "text": "A viable fetus with normal heart activity"}, {"id": "b", "text": "An empty uterus with a tubal mass"}, {"id": "c", "text": "A \"snowstorm\" pattern with no viable fetus"}, {"id": "d", "text": "Two separate fetuses, each with normal heart activity"}]'::jsonb, '["c"]', 'These findings describe a molar pregnancy, in which ultrasound shows a ''snowstorm'' pattern and there is no viable fetus. A viable fetus or twins would not explain this cluster of findings.', false),
  ('contraception', 33, 'A client has weekly hCG levels drawn after D&C for a molar pregnancy. Results (mIU/mL): week 1, 48,000; week 2, 9,500; week 3, 1,200; week 4, 2,100. Which action by the nurse is the PRIORITY?', '[{"id": "a", "text": "Reassure her that the overall trend shows hCG moving toward zero."}, {"id": "b", "text": "Change hCG testing to monthly because levels have dropped so far."}, {"id": "c", "text": "Tell her she may try to conceive once her hCG level reaches zero."}, {"id": "d", "text": "Report the rise in hCG to the provider as a possible malignancy."}]'::jsonb, '["d"]', 'hCG rose from 1,200 to 2,100 in week 4; any rise after D&C indicates possible malignant transformation (choriocarcinoma) and must be reported. The overall downward trend does not outweigh a new rise, and monitoring stays weekly until zero.', false),
  ('contraception', 34, 'A client is being discharged after D&C for a molar pregnancy. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "We plan to start trying for another baby next month."}, {"id": "b", "text": "I''ll come in every week for hCG tests until it is zero."}, {"id": "c", "text": "I''ll use contraception while my hCG is being monitored."}, {"id": "d", "text": "If my hCG level rises, it could mean a malignancy."}]'::jsonb, '["a"]', 'Pregnancy should be avoided for 6–12 months after a molar pregnancy, with contraception during hCG monitoring, so trying next month needs correction. Weekly hCG until zero and recognizing a rise as possible malignancy are correct.', false),
  ('contraception', 35, 'A client at 11 weeks'' gestation comes to the clinic. Which findings would lead the nurse to suspect gestational trophoblastic disease? Select all that apply.', '[{"id": "a", "text": "hCG lower than expected"}, {"id": "b", "text": "Vaginal bleeding"}, {"id": "c", "text": "Markedly elevated hCG"}, {"id": "d", "text": "Hyperemesis gravidarum"}, {"id": "e", "text": "Uterus larger than expected"}]'::jsonb, '["b", "c", "d", "e"]', 'Correct: vaginal bleeding, markedly elevated hCG, hyperemesis gravidarum, and a uterus larger than expected for gestational age are the listed signs of molar pregnancy. Wrong: hCG is markedly elevated in molar pregnancy, not lower than expected.', true),
  ('contraception', 36, 'After D&C for a molar pregnancy, a client''s weekly hCG level has stayed at the same elevated value for 3 weeks instead of falling toward zero. Which medication is the provider MOST likely to order?', '[{"id": "a", "text": "Penicillin G"}, {"id": "b", "text": "Metronidazole"}, {"id": "c", "text": "Methotrexate"}, {"id": "d", "text": "Levonorgestrel"}]'::jsonb, '["c"]', 'Persistent hCG after D&C suggests possible malignancy, and methotrexate may be used for persistent disease. Levonorgestrel is Plan B and does not treat persistent trophoblastic disease.', false),
  ('contraception', 37, 'A client with trichomoniasis is prescribed metronidazole (Flagyl). Her male partner has no symptoms. Which instruction by the nurse is BEST?', '[{"id": "a", "text": "Your partner needs treatment only if he begins to develop symptoms."}, {"id": "b", "text": "Small amounts of alcohol are safe once you have taken the first dose of Flagyl."}, {"id": "c", "text": "Your partner will be treated with penicillin G rather than Flagyl."}, {"id": "d", "text": "Both partners need metronidazole, and no alcohol is used with Flagyl."}]'::jsonb, '["d"]', 'Trichomoniasis is treated with metronidazole for both partners, and alcohol with Flagyl causes severe vomiting. Waiting for the partner to develop symptoms leaves him untreated.', false),
  ('contraception', 38, 'A nurse reviews teaching with four clients being treated for STIs. Which statements by clients indicate understanding? Select all that apply.', '[{"id": "a", "text": "My partner and I both need metronidazole for trichomoniasis."}, {"id": "b", "text": "Azithromycin for my chlamydia is taken for 7 days."}, {"id": "c", "text": "Acyclovir will cure my herpes if I take every dose."}, {"id": "d", "text": "Doxycycline for my chlamydia is taken for 7 days."}, {"id": "e", "text": "My ART medicines will cure the HIV over time."}]'::jsonb, '["a", "d"]', 'Correct: trichomoniasis is treated with metronidazole for both partners, and doxycycline for chlamydia is given for 7 days. Wrong: azithromycin for chlamydia is a single dose, not 7 days; acyclovir treats herpes but there is no cure; and HIV has no cure with ART.', true),
  ('contraception', 39, 'A client reports a genital chancre a few weeks ago that went away on its own and now has a rash on the palms and soles. Which medication is the nurse MOST likely to prepare?', '[{"id": "a", "text": "Penicillin G"}, {"id": "b", "text": "Acyclovir"}, {"id": "c", "text": "Metronidazole"}, {"id": "d", "text": "Valacyclovir"}]'::jsonb, '["a"]', 'A chancre followed by a palm/sole rash fits the stages of syphilis, for which penicillin G is the drug of choice. Acyclovir and valacyclovir are for herpes, and metronidazole is for trichomoniasis.', false),
  ('contraception', 40, 'A client with recurrent genital herpes (HSV) is prescribed valacyclovir. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "We will avoid sex during my outbreaks to protect my partner."}, {"id": "b", "text": "Once I finish this medicine, my herpes will be gone for good."}, {"id": "c", "text": "I''ll tell my provider if I become pregnant due to neonatal risk."}, {"id": "d", "text": "Acyclovir or valacyclovir can be used to treat my outbreaks."}]'::jsonb, '["b"]', 'Herpes is treated with acyclovir or valacyclovir, but there is no cure. Avoiding sex during outbreaks and recognizing the neonatal risk are correct.', false),
  ('contraception', 41, 'A 24-year-old client is diagnosed with genital warts caused by HPV and asks about her future health. Which teaching is MOST important for the nurse to reinforce?', '[{"id": "a", "text": "HPV is cured once the warts are removed with cryotherapy treatments."}, {"id": "b", "text": "The Gardasil vaccine is used now to treat the warts you currently have."}, {"id": "c", "text": "Metronidazole for both partners will clear the genital warts within a week."}, {"id": "d", "text": "HPV carries a cervical cancer risk, so keep up with Pap smear screening."}]'::jsonb, '["d"]', 'HPV carries a cervical cancer risk, so Pap smear screening is essential. Gardasil is for prevention and cryotherapy treats warts; neither removes the cancer risk.', false),
  ('contraception', 42, 'A 21-year-old client is treated for chlamydia with a single dose of azithromycin. Which statement by the client indicates understanding of the teaching?', '[{"id": "a", "text": "Treat both partners: my partner needs chlamydia treatment too."}, {"id": "b", "text": "Since it was one dose, my partner doesn''t need it."}, {"id": "c", "text": "This infection is rare, so I won''t likely get it again."}, {"id": "d", "text": "Doxycycline would also have been a single dose."}]'::jsonb, '["a"]', 'Chlamydia requires treatment of both partners, and it is the most common bacterial STI. Doxycycline is given for 7 days, while azithromycin is the single-dose option.', false),
  ('contraception', 43, 'A 66-year-old client has urinary hesitancy, hematuria, a hard, nodular prostate on DRE, and a markedly elevated PSA. Which test should the nurse anticipate NEXT to confirm the suspected diagnosis?', '[{"id": "a", "text": "Uroflowmetry study"}, {"id": "b", "text": "Biopsy of the prostate"}, {"id": "c", "text": "Repeat DRE in 1 year"}, {"id": "d", "text": "Pap smear screening"}]'::jsonb, '["b"]', 'Hematuria, a hard, nodular prostate, and a markedly elevated PSA suggest prostate cancer, for which a biopsy is required for confirmation. Uroflowmetry supports a clinical diagnosis of BPH.', false),
  ('contraception', 44, 'A nurse compares assessment data for two older male clients who both report urinary hesitancy and nocturia. Which findings suggest prostate cancer rather than BPH? Select all that apply.', '[{"id": "a", "text": "Hematuria with the urinary symptoms"}, {"id": "b", "text": "Smooth, enlarged prostate on DRE"}, {"id": "c", "text": "Markedly elevated PSA level"}, {"id": "d", "text": "Mildly elevated PSA level"}, {"id": "e", "text": "Hard, nodular prostate on DRE"}]'::jsonb, '["a", "c", "e"]', 'Correct: prostate cancer has similar urinary symptoms plus hematuria, a hard, nodular prostate, and a markedly elevated PSA. Wrong: a smooth, enlarged prostate and a mildly elevated PSA are BPH findings.', true),
  ('contraception', 45, 'A 70-year-old client has nocturia, a weak stream, a smooth, enlarged prostate on DRE, and a mildly elevated PSA. Which treatment plan is the nurse MOST likely to see ordered?', '[{"id": "a", "text": "Radiation therapy combined with hormone therapy"}, {"id": "b", "text": "Prostate biopsy, followed by surgery and radiation"}, {"id": "c", "text": "Alpha-blockers or finasteride, with TURP if needed"}, {"id": "d", "text": "Penicillin G for a suspected urinary infection"}]'::jsonb, '["c"]', 'A smooth, enlarged prostate with a mildly elevated PSA and urinary symptoms fits BPH, treated with alpha-blockers, finasteride, or TURP. Surgery, radiation, and hormone therapy are prostate cancer treatments.', false),
  ('contraception', 46, 'A nurse provides discharge teaching to a client immediately after Paragard copper IUD insertion. Which instructions should the nurse include? Select all that apply.', '[{"id": "a", "text": "Report abdominal pain or a missing string."}, {"id": "b", "text": "Slight cramping and spotting are normal today."}, {"id": "c", "text": "Check the strings monthly to confirm position."}, {"id": "d", "text": "Replace the IUD every 3 months at the clinic."}, {"id": "e", "text": "Report a late period, fever, or foul discharge."}]'::jsonb, '["a", "b", "c", "e"]', 'Correct: slight cramping and spotting are normal immediately after insertion, strings are checked monthly to confirm position, and a late period or infection signs (fever, foul discharge) are PAINS danger signs, as are abdominal pain and a missing string. Wrong: the IUD is not replaced every 3 months; every-3-month renewal describes the Depot-Provera injection.', true),
  ('contraception', 47, 'A nurse evaluates teaching for a 25-year-old client who started a combined oral contraceptive last week. Which statements by the client indicate understanding? Select all that apply.', '[{"id": "a", "text": "Breast tenderness means I must stop the pill."}, {"id": "b", "text": "Mood changes mean the pill must be stopped."}, {"id": "c", "text": "The pill will protect me from STIs as well."}, {"id": "d", "text": "I should report severe leg pain right away."}, {"id": "e", "text": "I''ll report eye problems such as vision changes."}]'::jsonb, '["d", "e"]', 'Correct: severe leg pain (DVT) and eye problems such as vision changes (stroke, HTN) are ACHES signs to report immediately. Wrong: breast tenderness and mood changes are common side effects, not reasons to stop the pill, and only condoms prevent STIs.', true),
  ('contraception', 48, 'A 34-year-old client is preparing for a vasectomy after he and his partner decide they want no more children. Which statements by the client indicate understanding? Select all that apply.', '[{"id": "a", "text": "It is a surgical, permanent method of birth control."}, {"id": "b", "text": "This can easily be reversed if we change our minds."}, {"id": "c", "text": "It is considered irreversible and permanent."}, {"id": "d", "text": "Informed consent is required before this permanent method."}, {"id": "e", "text": "It works as emergency contraception within 5 days."}]'::jsonb, '["a", "c", "d"]', 'Correct: vasectomy is a surgical, irreversible permanent method that requires informed consent. Wrong: it is not reversible, and the emergency method effective within 5 days is the copper IUD.', true),
  ('contraception', 49, 'Two days after IUD insertion, a client calls reporting severe, worsening abdominal pain that is much stronger than the slight cramping she had right after the procedure. Which action by the nurse is BEST?', '[{"id": "a", "text": "Have her evaluated promptly, because abdominal pain is an IUD danger sign."}, {"id": "b", "text": "Reassure her that cramping is normal in the first week after an insertion."}, {"id": "c", "text": "Tell her to check her strings at her next monthly self-check and call then."}, {"id": "d", "text": "Advise her to take Plan B tonight in case the IUD did not work correctly."}]'::jsonb, '["a"]', 'Only slight cramping immediately after insertion is normal; abdominal pain is the ''A'' in PAINS, and perforation is a listed IUD risk. Waiting for the monthly string check delays evaluation of a danger sign.', false),
  ('contraception', 50, 'A 26-year-old client with migraine with aura asks to start a combined estrogen-progestin pill because a friend uses one. Which action by the nurse is BEST?', '[{"id": "a", "text": "Start the combined pill and report any headache right away to the provider."}, {"id": "b", "text": "Discuss a non-estrogen method, such as the Paragard copper IUD, with the provider."}, {"id": "c", "text": "Use the combined pill only during months when no migraines are occurring."}, {"id": "d", "text": "Use the estrogen patch instead, since it avoids the risks linked to the combined pill."}]'::jsonb, '["b"]', 'Estrogen-containing contraceptives are contraindicated with migraine with aura, so a non-estrogen option such as the copper IUD should be discussed. A patch with estrogen carries the same contraindication.', false),
  ('anatomy', 1, 'A client in active labor has a cervical exam showing 8 cm of dilation. She reports strong pressure and asks the nurse whether the baby can be delivered now. Which response by the nurse is BEST?', '[{"id": "a", "text": "Yes; the cervix dilates to 8 cm for delivery."}, {"id": "b", "text": "Not yet; the cervix dilates to 10 cm for delivery."}, {"id": "c", "text": "Not yet; the uterus dilates to 10 cm for delivery."}, {"id": "d", "text": "Not yet; the vaginal opening dilates to 10 cm for delivery."}]'::jsonb, '["b"]', 'The cervix dilates to 10 cm for delivery, so at 8 cm the client is not yet ready. The uterus is the muscular organ where the fetus grows; it is the cervix (lower uterus) that dilates, and 8 cm is below 10 cm.', false),
  ('anatomy', 2, 'A 38-year-old client is preparing for discharge after a vasectomy. Which statements by the client indicate correct understanding of the procedure? Select all that apply.', '[{"id": "a", "text": "The epididymis was cut, so sperm are no longer stored and matured."}, {"id": "b", "text": "The vas deferens was cut, so sperm are not transported to the urethra."}, {"id": "c", "text": "My prostate gland was removed, so no fluid will be added to semen."}, {"id": "d", "text": "My urethra will still carry urine through the penis."}, {"id": "e", "text": "My testes will still produce sperm and testosterone."}]'::jsonb, '["b", "d", "e"]', 'Correct: a vasectomy cuts the vas deferens, which transports sperm to the urethra; the testes (which produce sperm and testosterone) are not cut; the urethra still carries urine through the penis. Wrong: the epididymis (stores and matures sperm) is not the structure cut in a vasectomy, and the prostate gland is not removed in a vasectomy, so it still adds fluid.', true),
  ('anatomy', 3, 'A 70-year-old client reports a weak urine stream and difficulty starting urination. He has been told his prostate gland is enlarged and asks how a reproductive gland can affect urination. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "The prostate gland adds fluid to semen, and when it enlarges (BPH) it blocks urine flow."}, {"id": "b", "text": "The seminal vesicles add fluid to semen, and when they enlarge they block urine flow."}, {"id": "c", "text": "The prostate gland stores and matures sperm, and when it enlarges it blocks the vas deferens."}, {"id": "d", "text": "The prostate gland produces testosterone, and when it enlarges it slows sperm production."}]'::jsonb, '["a"]', 'The prostate gland adds fluid and can enlarge (BPH); prostate enlargement blocks urine flow. Seminal vesicles also add fluid, but enlargement that blocks urine flow is linked to the prostate, not the seminal vesicles.', false),
  ('anatomy', 4, 'A client''s testes are producing sperm normally, but imaging shows a blockage where sperm leave the epididymis on both sides. Based on the sperm pathway, which structure will sperm be unable to enter NEXT?', '[{"id": "a", "text": "Seminal vesicles"}, {"id": "b", "text": "Prostate gland"}, {"id": "c", "text": "Vas deferens"}, {"id": "d", "text": "Urethra"}]'::jsonb, '["c"]', 'The sperm pathway is testes → epididymis → vas deferens → urethra → out, so a blockage leaving the epididymis stops sperm from entering the vas deferens next. The urethra comes after the vas deferens, and the seminal vesicles and prostate add fluid rather than forming the next step of the pathway.', false),
  ('anatomy', 5, 'A 32-year-old client had both ovaries removed. She asks which functions those organs performed. Which functions should the nurse include in the response? Select all that apply.', '[{"id": "a", "text": "Produce progesterone"}, {"id": "b", "text": "Store eggs (ova)"}, {"id": "c", "text": "Produce testosterone"}, {"id": "d", "text": "Release FSH and LH"}, {"id": "e", "text": "Produce estrogen"}]'::jsonb, '["a", "b", "e"]', 'Correct: the ovaries store eggs (ova) and produce estrogen and progesterone. Wrong: FSH and LH come from the anterior pituitary, not the ovaries; testosterone comes from the testes.', true),
  ('anatomy', 6, 'A 34-year-old client had both fallopian tubes removed several years ago. Her ovaries and uterus are healthy, and she asks why she cannot become pregnant naturally. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "The tubes store eggs and produce the estrogen and progesterone needed to conceive."}, {"id": "b", "text": "The tubes form the inner uterine lining that sheds during menstruation."}, {"id": "c", "text": "They transport the egg from ovary to uterus and are the site of fertilization."}, {"id": "d", "text": "The tubes are where the fertilized egg implants and where the fetus grows."}]'::jsonb, '["c"]', 'Fallopian tubes transport the egg from the ovary to the uterus and are the site of fertilization, so without them the egg and sperm cannot meet. Implantation and fetal growth occur in the uterus, and the ovaries store eggs and produce hormones.', false),
  ('anatomy', 7, 'A client with irregular cycles is told she is not ovulating because the hormone surge that triggers ovulation is missing. She asks which hormone this is and where it comes from. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "It is LH, which comes from the anterior pituitary."}, {"id": "b", "text": "It is estrogen, which comes from the anterior pituitary."}, {"id": "c", "text": "It is LH, which comes from the ovaries."}, {"id": "d", "text": "It is progesterone, which comes from the corpus luteum."}]'::jsonb, '["a"]', 'LH (luteinizing hormone) comes from the anterior pituitary and triggers ovulation in the female. The ovaries produce estrogen and progesterone, not LH, and progesterone maintains the uterine lining rather than triggering ovulation.', false),
  ('anatomy', 8, 'A 40-year-old client with an enlarged prostate asks the nurse to explain the structures involved in his symptoms. Which statements by the nurse are accurate? Select all that apply.', '[{"id": "a", "text": "The prostate gland stores and matures sperm."}, {"id": "b", "text": "The urethra carries urine and semen through the penis."}, {"id": "c", "text": "Prostate enlargement (BPH) stops sperm production."}, {"id": "d", "text": "The prostate gland adds fluid to semen."}, {"id": "e", "text": "Prostate enlargement (BPH) blocks urine flow."}]'::jsonb, '["b", "d", "e"]', 'Correct: the prostate gland adds fluid; prostate enlargement (BPH) blocks urine flow; the urethra carries urine and semen through the penis. Wrong: storing and maturing sperm is the job of the epididymis, and sperm production occurs in the testes (stimulated by FSH), not in the prostate.', true),
  ('anatomy', 9, 'A client who is 6 weeks pregnant asks why her provider is monitoring a hormone that is made by the corpus luteum and later by the placenta. Which function of this hormone is MOST important for the nurse to explain?', '[{"id": "a", "text": "It triggers ovulation in the middle of each cycle."}, {"id": "b", "text": "It maintains the uterine lining for pregnancy."}, {"id": "c", "text": "It builds up the uterine lining during each cycle."}, {"id": "d", "text": "It stimulates egg production within the ovaries."}]'::jsonb, '["b"]', 'The hormone from the corpus luteum / placenta is progesterone, which maintains the uterine lining for pregnancy. Building the uterine lining is estrogen''s action, and triggering ovulation is LH.', false),
  ('anatomy', 10, 'A male client and his partner have been trying to conceive. He reports soaking in a hot tub most evenings and wearing heavily insulated clothing at work. Which explanation BEST supports the nurse''s teaching about these habits?', '[{"id": "a", "text": "The scrotum keeps the testes warmer than body temp for sperm production."}, {"id": "b", "text": "The prostate gland must stay cooler than body temp to add fluid to semen."}, {"id": "c", "text": "The epididymis must stay cooler than body temp to produce testosterone."}, {"id": "d", "text": "The scrotum keeps the testes cooler than body temp for sperm production."}]'::jsonb, '["d"]', 'The scrotum holds the testes and keeps them cooler than body temperature for sperm production, so repeated heat works against that function. This cooling role belongs to the scrotum and testes, not the epididymis or prostate.', false),
  ('anatomy', 11, 'A nurse is caring for a client with a pituitary tumor that is affecting hormone release from the anterior pituitary. Which hormone levels should the nurse expect to be DIRECTLY affected? Select all that apply.', '[{"id": "a", "text": "Estrogen"}, {"id": "b", "text": "Progesterone"}, {"id": "c", "text": "FSH (Follicle-Stimulating Hormone)"}, {"id": "d", "text": "LH (Luteinizing Hormone)"}, {"id": "e", "text": "Testosterone"}]'::jsonb, '["c", "d"]', 'Correct: FSH and LH both come from the anterior pituitary. Wrong: estrogen comes from the ovaries, progesterone from the corpus luteum / placenta, and testosterone from the testes, so these are not released directly by the pituitary.', true),
  ('anatomy', 12, 'A nurse is preparing to insert an indwelling urinary catheter for a female client after surgery. The client asks whether the catheter goes into the same opening as her menstrual flow. Which response by the nurse is BEST?', '[{"id": "a", "text": "No; it goes into the cervix, which opens into the vagina."}, {"id": "b", "text": "Yes; the urethral opening carries both urine and menstrual flow."}, {"id": "c", "text": "No; it goes into the urethral opening, which is not reproductive."}, {"id": "d", "text": "Yes; the vaginal opening is where both urine and menstrual flow exit."}]'::jsonb, '["c"]', 'Urine exits through the urethral opening, which is not reproductive; menstrual flow leaves through the vaginal opening. The cervix opens into the vagina and is part of the uterus, not the urinary tract.', false),
  ('anatomy', 13, 'A client asks whether an injury to the urethra inside his penis could affect anything besides urination. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "Yes; the urethra is the site where sperm are stored and matured."}, {"id": "b", "text": "No; the urethra carries urine, while semen leaves through the vas deferens."}, {"id": "c", "text": "Yes; the urethra carries both urine and semen through the penis."}, {"id": "d", "text": "No; semen exits through the epididymis, which is separate from the urethra."}]'::jsonb, '["c"]', 'The urethra carries urine and semen through the penis, so an injury there can affect both. The vas deferens transports sperm to the urethra rather than out of the body, and the epididymis stores and matures sperm.', false),
  ('anatomy', 14, 'A 45-year-old client had her uterus removed, but both ovaries were left in place. Which statements by the client indicate correct understanding? Select all that apply.', '[{"id": "a", "text": "My ovaries will still store eggs and produce estrogen and progesterone."}, {"id": "b", "text": "My ovaries were removed, so they will stop producing estrogen."}, {"id": "c", "text": "My menstrual flow will now leave through the urethral opening."}, {"id": "d", "text": "My endometrium was removed, so no uterine lining sheds in menstruation."}, {"id": "e", "text": "I cannot carry a pregnancy, because the uterus is where the fetus grows."}]'::jsonb, '["a", "d", "e"]', 'Correct: the ovaries were kept, and they store eggs and produce estrogen and progesterone; the endometrium is the inner uterine lining that sheds during menstruation, so it is removed with the uterus; the uterus is the muscular organ where the fetus grows. Wrong: the ovaries were not removed; the urethral opening is where urine exits and is not reproductive.', true),
  ('anatomy', 15, 'A 16-year-old client reports monthly bleeding lasting 5 days and asks the nurse which part of her body the menstrual flow actually comes from. Which response by the nurse is BEST?', '[{"id": "a", "text": "The muscular wall of the vagina sheds during menstruation."}, {"id": "b", "text": "The ovaries release stored eggs that leave as menstrual flow."}, {"id": "c", "text": "The cervix, the lower uterus, sheds its lining during menstruation."}, {"id": "d", "text": "The endometrium, the inner uterine lining, sheds."}]'::jsonb, '["d"]', 'The endometrium is the inner uterine lining and sheds during menstruation; the vagina is only the canal the flow passes through. The cervix is the lower uterus that opens into the vagina, and the ovaries store eggs.', false),
  ('anatomy', 16, 'A client with a positive pregnancy test asks the nurse where her egg was fertilized and where the pregnancy is now attached. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "Fertilization in the ovary; implantation in the lower uterus at the cervix."}, {"id": "b", "text": "Fertilization in the fallopian tube; implantation in the uterus."}, {"id": "c", "text": "Fertilization in the fallopian tube; implantation in the ovary."}, {"id": "d", "text": "Fertilization in the uterus; implantation in the fallopian tube."}]'::jsonb, '["b"]', 'Fertilization occurs in the fallopian tube, and implantation occurs in the uterus. The most tempting distractor reverses the two sites.', false),
  ('anatomy', 17, 'A male client asks how sperm leave the body. Which structures should the nurse identify as part of the sperm pathway from production to exit? Select all that apply.', '[{"id": "a", "text": "Vas deferens"}, {"id": "b", "text": "Seminal vesicles"}, {"id": "c", "text": "Testes"}, {"id": "d", "text": "Epididymis"}, {"id": "e", "text": "Urethra"}]'::jsonb, '["a", "c", "d", "e"]', 'Correct: the sperm pathway is testes → epididymis → vas deferens → urethra → out. Wrong: the seminal vesicles add fluid to make semen but are not listed as a step in the sperm pathway.', true),
  ('anatomy', 18, 'During a perineal assessment after a fall onto a bicycle bar, the nurse notes a bruise over the client''s fatty tissue that cushions during intercourse. Which structure is MOST accurately documented as injured?', '[{"id": "a", "text": "Labia majora"}, {"id": "b", "text": "Labia minora"}, {"id": "c", "text": "Mons pubis"}, {"id": "d", "text": "Clitoris"}]'::jsonb, '["c"]', 'The mons pubis is the fatty tissue over the pubic bone that cushions during intercourse. The labia majora and minora protect inner structures, and the clitoris is sensitive erectile tissue.', false),
  ('anatomy', 19, 'During sexual health teaching, a client asks which external structure is the sensitive erectile tissue for sexual stimulation and whether urine also exits from it. Which response by the nurse is BEST?', '[{"id": "a", "text": "That is the mons pubis; urine exits from the vaginal opening."}, {"id": "b", "text": "That is the clitoris; urine exits from the vaginal opening."}, {"id": "c", "text": "That is the labia minora; urine exits from the urethral opening."}, {"id": "d", "text": "That is the clitoris; urine exits the urethral opening."}]'::jsonb, '["d"]', 'The clitoris is sensitive erectile tissue for sexual stimulation, and urine exits from the urethral opening, which is not reproductive. The vaginal opening is for menstrual flow, intercourse, and childbirth, not urine.', false),
  ('anatomy', 20, 'A client who is 39 weeks pregnant asks the nurse about the structure that will dilate in labor. Which statements by the nurse are accurate? Select all that apply.', '[{"id": "a", "text": "The cervix is the inner lining that sheds during menstruation."}, {"id": "b", "text": "The fetus grows in the uterus above the cervix."}, {"id": "c", "text": "The cervix dilates to 10 cm during labor."}, {"id": "d", "text": "The cervix opens into the vagina."}, {"id": "e", "text": "The cervix is the lower part of the uterus."}]'::jsonb, '["b", "c", "d", "e"]', 'Correct: the cervix is the lower uterus, opens into the vagina, and dilates to 10 cm during labor; the uterus is the muscular organ where the fetus grows. Wrong: the inner uterine lining that sheds during menstruation is the endometrium, not the cervix.', true),
  ('anatomy', 21, 'A male client has a low testosterone level. Testing shows his testes are structurally normal, but the hormone that triggers testosterone release is very low. Which gland is the MOST likely source of the problem?', '[{"id": "a", "text": "Anterior pituitary"}, {"id": "b", "text": "Corpus luteum of the ovary"}, {"id": "c", "text": "Prostate gland"}, {"id": "d", "text": "Seminal vesicles"}]'::jsonb, '["a"]', 'In the male, LH triggers testosterone release, and LH comes from the anterior pituitary. The prostate gland and seminal vesicles add fluid to semen, and the corpus luteum is a source of progesterone.', false),
  ('anatomy', 22, 'A male client''s semen analysis shows very few sperm, and his FSH level is markedly low. Which explanation MOST accurately links these two findings?', '[{"id": "a", "text": "FSH from the anterior pituitary triggers testosterone release."}, {"id": "b", "text": "FSH from the prostate gland adds fluid to form semen."}, {"id": "c", "text": "FSH from the anterior pituitary stimulates sperm production."}, {"id": "d", "text": "FSH from the testes builds sperm and develops male traits."}]'::jsonb, '["c"]', 'FSH comes from the anterior pituitary and stimulates egg or sperm production, so low FSH fits low sperm production. Triggering testosterone release is the action of LH, not FSH.', false),
  ('anatomy', 23, 'A client asks which structures add the fluid that makes up semen. Which structures should the nurse include? Select all that apply.', '[{"id": "a", "text": "Testes"}, {"id": "b", "text": "Vas deferens"}, {"id": "c", "text": "Prostate gland"}, {"id": "d", "text": "Seminal vesicles"}, {"id": "e", "text": "Epididymis"}]'::jsonb, '["c", "d"]', 'Correct: seminal vesicles add fluid to form semen, and the prostate gland adds fluid. Wrong: the epididymis stores and matures sperm, the vas deferens transports sperm to the urethra, and the testes produce sperm and testosterone.', true),
  ('anatomy', 24, 'The nurse receives four calls at a urology and women''s health clinic. Which client should the nurse call back FIRST?', '[{"id": "a", "text": "A client asking whether her menstrual flow comes from the inner uterine lining"}, {"id": "b", "text": "A client after vasectomy asking whether his testes still produce testosterone"}, {"id": "c", "text": "A client 1 week after vasectomy whose semen still contains fluid"}, {"id": "d", "text": "A client with prostate enlargement (BPH) whose urine flow is now blocked"}]'::jsonb, '["d"]', 'Prostate enlargement (BPH) blocks urine flow, so a client with an enlarged prostate who cannot pass urine has an active problem. The other callers have expected findings or teaching questions that can wait: after a vasectomy the seminal vesicles and prostate still add fluid, the testes still produce testosterone, and the endometrium is the lining that sheds.', false),
  ('anatomy', 25, 'A nursing student is teaching a client about male reproductive anatomy. Which statement by the student requires correction by the nurse?', '[{"id": "a", "text": "The epididymis stores and matures sperm."}, {"id": "b", "text": "The epididymis produces sperm and testosterone."}, {"id": "c", "text": "The scrotum keeps the testes cooler than body temp."}, {"id": "d", "text": "The seminal vesicles add fluid to form semen."}]'::jsonb, '["b"]', 'The testes, not the epididymis, produce sperm and testosterone; the epididymis stores and matures sperm. The other statements are accurate.', false),
  ('anatomy', 26, 'A nurse is teaching about the external genitalia (vulva) after a pelvic examination. Which statements by the nurse are accurate? Select all that apply.', '[{"id": "a", "text": "The labia majora and minora protect inner structures."}, {"id": "b", "text": "The clitoris is sensitive erectile tissue for sexual stimulation."}, {"id": "c", "text": "The vaginal opening is where urine exits the body."}, {"id": "d", "text": "The mons pubis is fatty tissue that cushions during intercourse."}, {"id": "e", "text": "The urethral opening is used for menstrual flow and childbirth."}]'::jsonb, '["a", "b", "d"]', 'Correct: the mons pubis is fatty tissue over the pubic bone that cushions during intercourse; the labia majora / minora protect inner structures; the clitoris is sensitive erectile tissue for sexual stimulation. Wrong: menstrual flow and childbirth use the vaginal opening, and urine exits from the urethral opening, which is not reproductive.', true),
  ('anatomy', 27, 'A 14-year-old client has not developed female secondary sex traits, and her estrogen level is very low. Which structure that produces this hormone should the nurse expect the provider to evaluate as the MOST likely source?', '[{"id": "a", "text": "Ovaries"}, {"id": "b", "text": "Corpus luteum"}, {"id": "c", "text": "Endometrium"}, {"id": "d", "text": "Anterior pituitary"}]'::jsonb, '["a"]', 'Estrogen comes from the ovaries and develops female secondary sex traits. The anterior pituitary releases FSH and LH rather than estrogen, the corpus luteum is a source of progesterone, and the endometrium is the uterine lining that estrogen builds.', false),
  ('anatomy', 28, 'A client undergoing evaluation has a very thin uterine lining on ultrasound and a low estrogen level. Which explanation by the nurse BEST connects these findings?', '[{"id": "a", "text": "Estrogen from the anterior pituitary sheds the uterine lining."}, {"id": "b", "text": "Testosterone from the ovaries builds the uterine lining."}, {"id": "c", "text": "Estrogen from the ovaries builds the uterine lining."}, {"id": "d", "text": "LH from the anterior pituitary builds the uterine lining."}]'::jsonb, '["c"]', 'Estrogen comes from the ovaries and builds the uterine lining, so low estrogen fits a thin lining. LH comes from the anterior pituitary but triggers ovulation rather than building the lining.', false),
  ('anatomy', 29, 'A 16-year-old male has delayed development of male secondary sex traits, and testing shows a low testosterone level. Which effects of this hormone should the nurse explain may be reduced? Select all that apply.', '[{"id": "a", "text": "Develops male secondary sex traits"}, {"id": "b", "text": "Stores and matures sperm"}, {"id": "c", "text": "Adds fluid to semen"}, {"id": "d", "text": "Builds sperm"}, {"id": "e", "text": "Triggers ovulation"}]'::jsonb, '["a", "d"]', 'Correct: testosterone, from the testes, builds sperm and develops male secondary sex traits. Wrong: triggering ovulation is the action of LH in females, adding fluid to semen is done by the seminal vesicles and prostate, and storing and maturing sperm is the role of the epididymis.', true),
  ('anatomy', 30, 'A client is scheduled for a vasectomy and asks which structure will be cut and what that structure normally does. Which response by the nurse is BEST?', '[{"id": "a", "text": "The seminal vesicles, which add fluid to form semen."}, {"id": "b", "text": "The urethra, which carries urine and semen through the penis."}, {"id": "c", "text": "The epididymis, which stores and matures sperm."}, {"id": "d", "text": "The vas deferens, which transports sperm to the urethra."}]'::jsonb, '["d"]', 'Vasectomy cuts the vas deferens, which transports sperm to the urethra. The epididymis is the earlier step that stores and matures sperm and is not the structure cut.', false),
  ('anatomy', 31, 'A client who is trying to conceive is reviewing what she learned about conception. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "My ovaries store my eggs until they are released."}, {"id": "b", "text": "Fertilization of my egg happens in my uterus."}, {"id": "c", "text": "My fallopian tubes carry the egg toward my uterus."}, {"id": "d", "text": "The fertilized egg implants in my uterus."}]'::jsonb, '["b"]', 'Fertilization occurs in the fallopian tube, not in the uterus; the uterus is the site of implantation. The ovaries store eggs and the fallopian tubes transport the egg from ovary to uterus, so those statements are correct.', false),
  ('anatomy', 32, 'A nurse is reviewing conception with a couple who are planning a pregnancy. Which statements by the couple indicate understanding? Select all that apply.', '[{"id": "a", "text": "The fallopian tubes transport the egg from ovary to uterus."}, {"id": "b", "text": "Implantation occurs in the fallopian tube."}, {"id": "c", "text": "Implantation occurs in the uterus."}, {"id": "d", "text": "Fertilization occurs in the fallopian tube."}, {"id": "e", "text": "The ovaries store the eggs."}]'::jsonb, '["a", "c", "d", "e"]', 'Correct: the ovaries store eggs (ova); the fallopian tubes transport the egg from ovary to uterus and are the site of fertilization; implantation occurs in the uterus. Wrong: the fallopian tube is the site of fertilization, not implantation.', true),
  ('anatomy', 33, 'A client has an early pregnancy ultrasound. Which finding should the nurse recognize as the expected finding for implantation in a normal pregnancy?', '[{"id": "a", "text": "The pregnancy is implanted in the cervix."}, {"id": "b", "text": "The pregnancy is implanted in the uterus."}, {"id": "c", "text": "The pregnancy is implanted in the ovary."}, {"id": "d", "text": "The pregnancy is implanted in the fallopian tube."}]'::jsonb, '["b"]', 'Implantation occurs in the uterus, the muscular organ where the fetus grows. The fallopian tube is the site of fertilization, not implantation, which makes it the most tempting wrong choice.', false),
  ('anatomy', 34, 'A male client is surprised to learn that men also have luteinizing hormone. He asks what it does in his body. Which response by the nurse is BEST?', '[{"id": "a", "text": "In males, LH stores and matures the sperm."}, {"id": "b", "text": "In males, LH triggers ovulation and egg production."}, {"id": "c", "text": "In males, LH triggers testosterone release."}, {"id": "d", "text": "In males, LH adds fluid to form semen."}]'::jsonb, '["c"]', 'LH from the anterior pituitary triggers ovulation in the female and testosterone release in the male. Storing and maturing sperm is the epididymis, and adding fluid is the seminal vesicles and prostate.', false),
  ('anatomy', 35, 'A 15-year-old client asks the nurse which structures menstrual flow involves. Which structures should the nurse include? Select all that apply.', '[{"id": "a", "text": "Urethral opening"}, {"id": "b", "text": "Fallopian tubes"}, {"id": "c", "text": "Endometrium"}, {"id": "d", "text": "Vagina"}, {"id": "e", "text": "Vaginal opening"}]'::jsonb, '["c", "d", "e"]', 'Correct: the endometrium sheds during menstruation, the vagina is the muscular canal for menstrual flow, and the vaginal opening is where menstrual flow leaves. Wrong: urine exits the urethral opening, which is not reproductive, and the fallopian tubes transport the egg from ovary to uterus.', true),
  ('anatomy', 36, 'A client who had a vasectomy 2 months ago is worried that he will no longer have any fluid when he ejaculates. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "Seminal vesicles and the prostate still add fluid."}, {"id": "b", "text": "The epididymis now adds the fluid that forms the semen."}, {"id": "c", "text": "The testes now add the fluid that forms semen."}, {"id": "d", "text": "The vas deferens still adds fluid to form semen."}]'::jsonb, '["a"]', 'Seminal vesicles add fluid to form semen and the prostate gland adds fluid; a vasectomy only cuts the vas deferens. The vas deferens transports sperm to the urethra rather than adding fluid.', false),
  ('anatomy', 37, 'A client sustained a scrotal injury that damaged the epididymis on one side. Which function of the injured structure should the nurse explain may be impaired?', '[{"id": "a", "text": "Produces sperm and testosterone"}, {"id": "b", "text": "Stores and matures sperm"}, {"id": "c", "text": "Transports sperm to the urethra"}, {"id": "d", "text": "Adds fluid to form semen"}]'::jsonb, '["b"]', 'The epididymis stores and matures sperm. Producing sperm and testosterone is the testes, and transporting sperm to the urethra is the vas deferens.', false),
  ('anatomy', 38, 'During a pelvic examination, the provider visualizes the structure that forms the lower part of the uterus and opens into the vagina. The client asks what this structure does during childbirth. Which response by the nurse is BEST?', '[{"id": "a", "text": "It is the cervix, and it dilates to 8 cm during labor."}, {"id": "b", "text": "It is the endometrium, and it sheds during labor."}, {"id": "c", "text": "It is the vaginal opening, and it dilates to 10 cm during labor."}, {"id": "d", "text": "It is the cervix, and it dilates to 10 cm during labor."}]'::jsonb, '["d"]', 'The cervix is the lower uterus, opens into the vagina, and dilates to 10 cm during labor. The endometrium is the inner uterine lining that sheds during menstruation.', false),
  ('anatomy', 39, 'A 30-year-old client had both testes removed because of disease. Which functions should the nurse expect to be lost? Select all that apply.', '[{"id": "a", "text": "Add fluid to semen"}, {"id": "b", "text": "Produce testosterone"}, {"id": "c", "text": "Produce sperm"}, {"id": "d", "text": "Release LH"}, {"id": "e", "text": "Carry urine through the penis"}]'::jsonb, '["b", "c"]', 'Correct: the testes produce sperm and testosterone. Wrong: the seminal vesicles and prostate add fluid, the urethra carries urine through the penis, and LH comes from the anterior pituitary, so those functions remain.', true),
  ('anatomy', 40, 'The nurse reviews cervical exam findings for four laboring clients. Which client has reached the cervical dilation needed for delivery?', '[{"id": "a", "text": "Cervix at 10 cm"}, {"id": "b", "text": "Vaginal opening at 10 cm"}, {"id": "c", "text": "Cervix at 9 cm"}, {"id": "d", "text": "Cervix at 7 cm and progressing"}]'::jsonb, '["a"]', 'The cervix dilates to 10 cm for delivery, so only the client at 10 cm has reached that point. A cervix at 9 cm is close but has not yet reached 10 cm.', false),
  ('anatomy', 41, 'A client with an enlarged prostate is reviewing teaching about his condition. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "Prostate enlargement (BPH) stops sperm production in my testes."}, {"id": "b", "text": "Prostate enlargement (BPH) is what blocks my urine flow."}, {"id": "c", "text": "My prostate gland adds fluid that becomes part of my semen."}, {"id": "d", "text": "My urethra carries both urine and semen through my penis."}]'::jsonb, '["a"]', 'Prostate enlargement (BPH) blocks urine flow; it is not linked to sperm production, which is the role of the testes. The other statements are accurate: the prostate adds fluid, and the urethra carries urine and semen.', false),
  ('anatomy', 42, 'A pregnant client asks which structures produce the hormone that maintains the uterine lining for pregnancy. Which structures should the nurse include? Select all that apply.', '[{"id": "a", "text": "Placenta"}, {"id": "b", "text": "Corpus luteum"}, {"id": "c", "text": "Testes"}, {"id": "d", "text": "Anterior pituitary"}, {"id": "e", "text": "Endometrium"}]'::jsonb, '["a", "b"]', 'Correct: progesterone comes from the corpus luteum / placenta and maintains the uterine lining for pregnancy. Wrong: the anterior pituitary releases FSH and LH, the endometrium is the lining itself, and the testes produce testosterone.', true),
  ('anatomy', 43, 'A 25-year-old client had one ovary removed because of a cyst. The other ovary is healthy. She asks whether she will still have eggs and female hormones. Which response by the nurse is BEST?', '[{"id": "a", "text": "No; your fallopian tubes must now store eggs and produce estrogen."}, {"id": "b", "text": "Yes; your uterus will now produce estrogen and store your eggs."}, {"id": "c", "text": "No; your anterior pituitary must now produce estrogen and progesterone."}, {"id": "d", "text": "Yes; the remaining ovary can store eggs and produce estrogen and progesterone."}]'::jsonb, '["d"]', 'The ovaries store eggs (ova) and produce estrogen and progesterone, so the remaining healthy ovary still performs these functions. The anterior pituitary releases FSH and LH, not estrogen and progesterone.', false),
  ('anatomy', 44, 'A client''s laboratory results show a very low FSH level, while her LH level is normal. Which process should the nurse recognize as MOST directly affected by the low FSH?', '[{"id": "a", "text": "Triggering of ovulation"}, {"id": "b", "text": "Maintenance of the uterine lining for pregnancy"}, {"id": "c", "text": "Shedding of the endometrium"}, {"id": "d", "text": "Stimulation of egg production"}]'::jsonb, '["d"]', 'FSH stimulates egg or sperm production. Triggering ovulation is the action of LH, which is normal in this client, and maintaining the lining for pregnancy is progesterone.', false),
  ('anatomy', 45, 'A nurse is reviewing the female internal reproductive structures with a client before a pelvic procedure. Which statements by the client indicate understanding? Select all that apply.', '[{"id": "a", "text": "The cervix is the upper uterus that opens into the tubes."}, {"id": "b", "text": "The endometrium is the inner uterine lining that sheds."}, {"id": "c", "text": "The ovaries store eggs and produce estrogen and progesterone."}, {"id": "d", "text": "The uterus is the muscular organ where the fetus grows."}, {"id": "e", "text": "The vagina is a muscular canal for intercourse, birth, and menstrual flow."}]'::jsonb, '["b", "c", "d", "e"]', 'Correct: the vagina is a muscular canal for intercourse, birth, and menstrual flow; the uterus is the muscular organ where the fetus grows; the ovaries store eggs and produce estrogen and progesterone; the endometrium is the inner uterine lining that sheds during menstruation. Wrong: the cervix is the lower uterus and opens into the vagina.', true),
  ('anatomy', 46, 'A male client and his partner are trying to conceive. He makes several statements during a clinic visit. Which statement requires follow-up by the nurse?', '[{"id": "a", "text": "I keep a heating pad on my scrotum most nights."}, {"id": "b", "text": "I understand semen and urine both pass through my urethra."}, {"id": "c", "text": "I learned that my epididymis stores and matures sperm."}, {"id": "d", "text": "I know that my testes produce both sperm and testosterone."}]'::jsonb, '["a"]', 'The scrotum keeps the testes cooler than body temperature for sperm production, so nightly heat to the scrotum works against sperm production and needs follow-up. The other statements correctly describe the testes, epididymis, and urethra.', false),
  ('anatomy', 47, 'A client with injuries to the external genitalia after an accident asks what the labia majora and labia minora normally do. Which response by the nurse is BEST?', '[{"id": "a", "text": "They cushion during intercourse."}, {"id": "b", "text": "They are where urine exits the body."}, {"id": "c", "text": "They protect inner structures."}, {"id": "d", "text": "They provide sensitive erectile tissue."}]'::jsonb, '["c"]', 'The labia majora and minora protect inner structures. Cushioning during intercourse is the role of the mons pubis, and sensitive erectile tissue is the clitoris.', false),
  ('anatomy', 48, 'A client asks how sperm deposited in the vagina reach the uterus. Which structure should the nurse identify as the MOST direct connection between the two?', '[{"id": "a", "text": "The urethral opening, which is next to the vaginal opening"}, {"id": "b", "text": "The cervix, the lower uterus that opens into the vagina"}, {"id": "c", "text": "The endometrium, the inner lining that sheds"}, {"id": "d", "text": "The fallopian tube, which carries the egg to the uterus"}]'::jsonb, '["b"]', 'The cervix is the lower uterus and opens into the vagina, connecting the vagina to the uterus. The fallopian tube connects the ovary to the uterus, not the vagina to the uterus.', false),
  ('anatomy', 49, 'A male client who has had a penile injury asks whether the injury could affect both his reproductive and urinary functions. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "Yes; the penis delivers both sperm and urine."}, {"id": "b", "text": "No; the penis delivers urine, while sperm leave through the scrotum."}, {"id": "c", "text": "Yes; the penis produces sperm and stores urine."}, {"id": "d", "text": "No; the penis delivers sperm, while urine leaves through the prostate."}]'::jsonb, '["a"]', 'The penis delivers sperm and urine, so injury may affect both functions. The scrotum holds the testes and the prostate adds fluid; neither is an exit route.', false),
  ('anatomy', 50, 'A client in labor whose cervix is dilated to 10 cm asks which structure the baby will pass through to be born. Which response by the nurse is BEST?', '[{"id": "a", "text": "The endometrium, the lining that sheds after birth"}, {"id": "b", "text": "The vagina, the muscular canal for birth"}, {"id": "c", "text": "The fallopian tube, which transports the egg to the uterus"}, {"id": "d", "text": "The urethral opening, where urine exits the body"}]'::jsonb, '["b"]', 'The vagina is the muscular canal for intercourse, birth, and menstrual flow, and the vaginal opening is used for childbirth. The urethral opening is where urine exits and is not reproductive.', false),
  ('sti', 1, 'A 27-year-old client reports vulvar itching and burning with a foul-smelling, frothy, green vaginal discharge. On speculum examination the nurse notes a strawberry cervix. Which medication is the nurse MOST likely to prepare?', '[{"id": "a", "text": "Penicillin G injection"}, {"id": "b", "text": "Metronidazole (Flagyl)"}, {"id": "c", "text": "Acyclovir by mouth"}, {"id": "d", "text": "Permethrin cream to apply"}]'::jsonb, '["b"]', 'Frothy green discharge with itching, burning, and a strawberry cervix indicates trichomoniasis, treated with metronidazole (Flagyl). Permethrin cream treats pubic lice, which cause itching but not this discharge.', false),
  ('sti', 2, 'A client who started metronidazole (Flagyl) this morning tells the nurse, "My sister''s wedding is this weekend, so I''ll just have a couple of glasses of champagne." Which response by the nurse is the PRIORITY?', '[{"id": "a", "text": "A small amount of alcohol is safe if you take the dose with a full meal."}, {"id": "b", "text": "Skip your doses on the day of the wedding and resume them the next day."}, {"id": "c", "text": "Avoid alcohol while taking Flagyl; together they cause severe vomiting."}, {"id": "d", "text": "Stop the Flagyl now, because the symptoms are already starting to improve."}]'::jsonb, '["c"]', 'Metronidazole (Flagyl) plus alcohol causes severe vomiting, so no alcohol is the priority teaching. Skipping or stopping doses conflicts with completing the full course even if symptoms resolve.', false),
  ('sti', 3, 'A 23-year-old client has a thick yellow-green discharge and dysuria, and a culture confirms Neisseria gonorrhoeae. Which actions should the nurse anticipate? Select all that apply.', '[{"id": "a", "text": "Treat for chlamydia as well"}, {"id": "b", "text": "Partner notification and treatment"}, {"id": "c", "text": "Report to the health department"}, {"id": "d", "text": "Acyclovir to reduce outbreaks"}, {"id": "e", "text": "Permethrin cream and hot-water wash"}]'::jsonb, '["a", "b", "c"]', 'Correct: chlamydia and gonorrhea often co-occur, so both are treated; partner notification and treatment prevents reinfection; and gonorrhea is a reportable STI. Wrong: acyclovir is for herpes, and permethrin cream with hot-water washing is for pubic lice.', true),
  ('sti', 4, 'A 20-year-old client has no symptoms, but a routine screening test is positive for Chlamydia trachomatis. She says, "I feel completely fine, so I don''t think I need any medicine." Which response by the nurse is BEST?', '[{"id": "a", "text": "Without symptoms the infection is not contagious, so your treatment can wait until later."}, {"id": "b", "text": "Treatment is needed only if you develop burning urination or an abnormal discharge later."}, {"id": "c", "text": "The result is probably false, because chlamydia typically causes a thick discharge first."}, {"id": "d", "text": "Chlamydia is often asymptomatic, and without treatment it can lead to PID and infertility."}]'::jsonb, '["d"]', 'Chlamydia is often asymptomatic in women, yet it can cause PID leading to infertility, so it must be treated. Burning urination and abnormal discharge can occur but are not required before treatment.', false),
  ('sti', 5, 'A client has a new rash on the palms of the hands and the soles of the feet. She recalls a painless sore on her genitals about 2 months ago that healed without treatment. The nurse recognizes this as which condition?', '[{"id": "a", "text": "Secondary syphilis"}, {"id": "b", "text": "Primary syphilis (Stage 1)"}, {"id": "c", "text": "Neurosyphilis"}, {"id": "d", "text": "Herpes (HSV-2)"}]'::jsonb, '["a"]', 'A rash on the palms and soles is the highly distinctive sign of Stage 2 (secondary) syphilis; the earlier painless chancre was Stage 1. Neurosyphilis reflects Stage 3 brain damage, and herpes causes painful blisters.', false),
  ('sti', 6, 'A 22-year-old client reports painful blisters on the genitals with fever and body aches for 3 days. She has never had these symptoms before. Which infection is the nurse MOST likely to suspect?', '[{"id": "a", "text": "Primary syphilis"}, {"id": "b", "text": "HPV"}, {"id": "c", "text": "Gonorrhea"}, {"id": "d", "text": "Herpes (HSV-2)"}]'::jsonb, '["d"]', 'Painful blisters with flu-like symptoms at the first outbreak point to herpes (HSV-2). Primary syphilis causes a painless chancre and HPV causes painless genital warts.', false),
  ('sti', 7, 'A client has severe genital itching, and the nurse sees visible lice in the pubic hair. Which instructions should the nurse include? Select all that apply.', '[{"id": "a", "text": "Take metronidazole with your partner"}, {"id": "b", "text": "Apply the permethrin cream as directed"}, {"id": "c", "text": "Avoid sex only during outbreaks"}, {"id": "d", "text": "Take acyclovir daily to reduce itching"}, {"id": "e", "text": "Wash clothes/bedding in hot water"}]'::jsonb, '["b", "e"]', 'Correct: pubic lice are treated with permethrin cream, and clothes and bedding are washed in hot water. Wrong: metronidazole treats trichomoniasis, acyclovir treats herpes, and avoiding sex during outbreaks is herpes teaching.', true),
  ('sti', 8, 'At a well visit, a parent of a 12-year-old asks whether it is too early to give the HPV vaccine because the child is not sexually active. Which response by the nurse is BEST?', '[{"id": "a", "text": "The Gardasil vaccine is given at ages 11–12, so now is the right time."}, {"id": "b", "text": "The vaccine should wait until sexual activity begins, so you can delay it."}, {"id": "c", "text": "The vaccine is used to treat genital warts, so it is not needed until then."}, {"id": "d", "text": "The vaccine is given only after an abnormal Pap smear result is reported."}]'::jsonb, '["a"]', 'The Gardasil vaccine is given at ages 11–12, so a 12-year-old is in the recommended range. Warts are treated with cryotherapy, not the vaccine, which is used for prevention.', false),
  ('sti', 9, 'A client with chronic hepatitis B asks the nurse about long-term health risks. Which complications should the nurse include in the teaching? Select all that apply.', '[{"id": "a", "text": "Liver failure"}, {"id": "b", "text": "Neurosyphilis"}, {"id": "c", "text": "Cirrhosis"}, {"id": "d", "text": "Cervical cancer"}, {"id": "e", "text": "Liver cancer"}]'::jsonb, '["a", "c", "e"]', 'Correct: hepatitis B can lead to liver failure, cirrhosis, and liver cancer. Wrong: neurosyphilis is a complication of syphilis, and cervical cancer is a complication of HPV.', true),
  ('sti', 10, 'The sexual partner of a client newly diagnosed with hepatitis B asks the nurse how to protect himself from getting the infection. Which response by the nurse is BEST?', '[{"id": "a", "text": "Start antiviral therapy now so that the infection cannot become chronic."}, {"id": "b", "text": "The hepatitis B vaccine prevents this infection; ask about receiving it."}, {"id": "c", "text": "The Gardasil vaccine will protect you against both hepatitis B and HPV infection."}, {"id": "d", "text": "Taking acyclovir daily will prevent you from getting hepatitis B later."}]'::jsonb, '["b"]', 'For hepatitis B, the vaccine prevents infection, while antiviral therapy is used for chronic disease, not prevention. Gardasil prevents HPV, not hepatitis B.', false),
  ('sti', 11, 'A client with HIV who stopped taking ART 1 year ago has a CD4 count of 180 cells/mm³. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "The count is above the cutoff, so it is still early HIV."}, {"id": "b", "text": "The count shows that the client''s HIV has been cured."}, {"id": "c", "text": "The client''s HIV has progressed to AIDS (CD4 <200)."}, {"id": "d", "text": "The count confirms that ART is no longer needed at all."}]'::jsonb, '["c"]', 'A CD4 count below 200 defines AIDS, and 180 is below that cutoff. ART slows the disease but there is no cure, so the infection has not been cured.', false),
  ('sti', 12, 'A nurse reviews the records of several clients with HIV. Which findings indicate that a client''s HIV has progressed to AIDS? Select all that apply.', '[{"id": "a", "text": "CD4 count of 150 cells/mm³"}, {"id": "b", "text": "Flu-like symptoms at onset"}, {"id": "c", "text": "An opportunistic infection"}, {"id": "d", "text": "CD4 count of 450 cells/mm³"}, {"id": "e", "text": "A painless genital chancre"}]'::jsonb, '["a", "c"]', 'Correct: AIDS is defined by a CD4 count below 200 and is associated with opportunistic infections. Wrong: flu-like symptoms occur initially with HIV, a CD4 count of 450 is above the AIDS cutoff, and a painless chancre is primary syphilis.', true),
  ('sti', 13, 'A client newly diagnosed with HIV begins antiretroviral therapy. Which statement by the client indicates understanding of the treatment?', '[{"id": "a", "text": "ART slows the disease, but there is no cure for HIV."}, {"id": "b", "text": "Once my viral test is negative, I can stop the ART."}, {"id": "c", "text": "ART cures HIV if I take it daily for a full year."}, {"id": "d", "text": "ART is only needed if I develop an opportunistic infection."}]'::jsonb, '["a"]', 'ART (antiretroviral therapy) slows disease and there is no cure, so it is not stopped once the client feels well. Waiting for opportunistic infections allows progression to AIDS.', false),
  ('sti', 14, 'A nurse in a sexual health clinic reviews four diagnoses confirmed today. Which diagnosis must the nurse report to the health department?', '[{"id": "a", "text": "Trichomoniasis with a strawberry cervix"}, {"id": "b", "text": "Syphilis with a painless chancre"}, {"id": "c", "text": "Genital herpes with painful blisters"}, {"id": "d", "text": "Pubic lice with severe itching"}]'::jsonb, '["b"]', 'Syphilis is one of the reportable STIs, along with chlamydia, gonorrhea, and HIV. Trichomoniasis, herpes, and pubic lice are not on that list.', false),
  ('sti', 15, 'A nurse is completing documentation for clients seen in an STI clinic. Which confirmed infections require the nurse to report to the health department? Select all that apply.', '[{"id": "a", "text": "HPV with genital warts"}, {"id": "b", "text": "Chlamydia"}, {"id": "c", "text": "Trichomoniasis"}, {"id": "d", "text": "Gonorrhea"}, {"id": "e", "text": "HIV"}]'::jsonb, '["b", "d", "e"]', 'Correct: chlamydia, gonorrhea, and HIV are reportable STIs (as is syphilis). Wrong: HPV and trichomoniasis are not among the reportable STIs listed.', true),
  ('sti', 16, 'At her first prenatal visit, a pregnant client with no symptoms asks why she is being tested for STIs: "I''ve been with the same partner for years." Which response by the nurse is BEST?', '[{"id": "a", "text": "Testing is done only for pregnant women who have symptoms."}, {"id": "b", "text": "Screening is needed only if your partner has had any symptoms recently."}, {"id": "c", "text": "All pregnant women are screened for STIs to protect the newborn."}, {"id": "d", "text": "STI testing is optional unless you plan to breastfeed later."}]'::jsonb, '["c"]', 'All pregnant women are screened for STIs to protect the newborn, regardless of symptoms; several STIs, such as chlamydia, are often asymptomatic in women.', false),
  ('sti', 17, 'A client at 32 weeks'' gestation has a thick yellow-green discharge and dysuria and has not yet been treated. She asks how this could affect her baby. Which newborn complication is the nurse MOST likely to explain?', '[{"id": "a", "text": "Neonatal herpes"}, {"id": "b", "text": "Congenital birth defects"}, {"id": "c", "text": "Newborn jaundice"}, {"id": "d", "text": "Newborn blindness"}]'::jsonb, '["d"]', 'Thick yellow-green discharge with dysuria indicates gonorrhea, whose complications include newborn blindness. Congenital birth defects are a syphilis complication and neonatal herpes is an HSV complication.', false),
  ('sti', 18, 'A client at 38 weeks'' gestation reports new painful blisters on her genitals and flu-like symptoms. Which concern is the nurse''s PRIORITY?', '[{"id": "a", "text": "Newborn blindness from gonorrhea"}, {"id": "b", "text": "Congenital birth defects from syphilis"}, {"id": "c", "text": "Neonatal herpes, which is severe in newborns"}, {"id": "d", "text": "Later cervical cancer risk from HPV infection"}]'::jsonb, '["c"]', 'Painful genital blisters with flu-like symptoms indicate herpes (HSV-2), and neonatal herpes is severe in newborns. Newborn blindness and congenital defects are complications of gonorrhea and syphilis.', false),
  ('sti', 19, 'A 24-year-old client with untreated chlamydia asks what could happen if she does not complete treatment. Which complications should the nurse include? Select all that apply.', '[{"id": "a", "text": "Infertility"}, {"id": "b", "text": "Neurosyphilis"}, {"id": "c", "text": "Ectopic pregnancy"}, {"id": "d", "text": "PID (pelvic inflammatory disease)"}, {"id": "e", "text": "Liver cancer"}]'::jsonb, '["a", "c", "d"]', 'Correct: chlamydia can cause PID leading to infertility, ectopic pregnancy, and newborn eye infection. Wrong: neurosyphilis is a syphilis complication, and liver cancer is a hepatitis B complication.', true),
  ('sti', 20, 'A client treated last month for thick yellow-green discharge and dysuria now has a painful, swollen knee. Which complication should the nurse suspect is MOST likely?', '[{"id": "a", "text": "Stage 3 syphilis with organ damage"}, {"id": "b", "text": "Herpes outbreak spreading to joints"}, {"id": "c", "text": "Hepatitis B progressing to cirrhosis"}, {"id": "d", "text": "A joint infection related to gonorrhea"}]'::jsonb, '["d"]', 'Thick yellow-green discharge with dysuria indicates gonorrhea, which can cause joint infections. Stage 3 syphilis causes organ damage, not a gonorrhea-linked joint infection.', false),
  ('sti', 21, 'A client on day 3 of doxycycline for chlamydia says, "The burning is gone, so I''m going to stop the pills and save the rest." Which response by the nurse is BEST?', '[{"id": "a", "text": "Complete the full antibiotic course even if symptoms resolve."}, {"id": "b", "text": "You may stop the pills now, since the burning has gone away."}, {"id": "c", "text": "Stop now and restart the leftover pills later if the burning returns."}, {"id": "d", "text": "Switch to the leftover pills only when your partner has symptoms."}]'::jsonb, '["a"]', 'The full antibiotic course must be completed even if symptoms resolve; doxycycline for chlamydia is given for 7 days. Stopping on day 3 leaves treatment incomplete.', false),
  ('sti', 22, 'A client has been treated for chlamydia twice in 4 months. She reports that her partner has never been tested or treated. Which nursing action is the PRIORITY to prevent another infection?', '[{"id": "a", "text": "A longer course of antibiotics for the client alone this time"}, {"id": "b", "text": "Partner notification and treatment to prevent reinfection"}, {"id": "c", "text": "Abstinence only until the client''s symptoms resolve"}, {"id": "d", "text": "Retesting the client every month for the next year"}]'::jsonb, '["b"]', 'Partner notification and treatment prevents reinfection; treating only the client leaves the untreated partner as a source of repeat infection.', false),
  ('sti', 23, 'After treatment for an STI, a client and the nurse review safer sex practices. Which statements by the client indicate understanding? Select all that apply.', '[{"id": "a", "text": "Condoms reduce my risk of getting an STI."}, {"id": "b", "text": "Only abstinence is 100% effective against STIs."}, {"id": "c", "text": "Using condoms makes me 100% protected from STIs."}, {"id": "d", "text": "Once treated, I can''t get this same STI again."}, {"id": "e", "text": "I''ll complete the full antibiotic course."}]'::jsonb, '["a", "b", "e"]', 'Correct: condoms reduce risk, only abstinence is 100% effective, and the full antibiotic course is completed even if symptoms resolve. Wrong: condoms are not 100% protective, and reinfection is possible, which is why partner notification and treatment prevents reinfection.', true),
  ('sti', 24, 'A client''s test is positive for Neisseria gonorrhoeae, and the chlamydia result will not be available for 3 days. Which plan of care should the nurse anticipate?', '[{"id": "a", "text": "Treat gonorrhea now and wait for the chlamydia result to return."}, {"id": "b", "text": "Hold all treatment until both test results have come back."}, {"id": "c", "text": "Treat chlamydia only, because it is the more common infection."}, {"id": "d", "text": "Treat for both, because chlamydia and gonorrhea often co-occur."}]'::jsonb, '["d"]', 'Chlamydia and gonorrhea often co-occur, so the plan is to treat for both rather than wait. Delaying treatment leaves the confirmed gonorrhea untreated.', false),
  ('sti', 25, 'A 64-year-old client with a remote history of an untreated genital sore is admitted with confusion and personality changes. Which complication does the nurse recognize as MOST likely?', '[{"id": "a", "text": "Primary syphilis"}, {"id": "b", "text": "Neurosyphilis (Stage 3)"}, {"id": "c", "text": "Secondary syphilis"}, {"id": "d", "text": "Neonatal herpes"}]'::jsonb, '["b"]', 'Untreated syphilis progresses to Stage 3 with organ damage; brain damage is neurosyphilis. Primary syphilis is the painless chancre and secondary is the palm/sole rash.', false),
  ('sti', 26, 'A nurse triages clients in an STI clinic. Which findings suggest a bacterial STI that is curable with antibiotics? Select all that apply.', '[{"id": "a", "text": "Painless genital warts"}, {"id": "b", "text": "Burning urination and pelvic pain"}, {"id": "c", "text": "Painless ulcer (chancre)"}, {"id": "d", "text": "Thick yellow-green discharge + dysuria"}, {"id": "e", "text": "Painful blisters on the genitals"}]'::jsonb, '["b", "c", "d"]', 'Correct: a painless chancre (syphilis), thick yellow-green discharge with dysuria (gonorrhea), and burning urination with pelvic pain (chlamydia) are bacterial STIs curable with antibiotics. Wrong: painful blisters (herpes) and painless genital warts (HPV) are viral STIs with no cure.', true),
  ('sti', 27, 'A 25-year-old client has a single painless ulcer on the genitals that appeared about 2 weeks ago. There are no blisters and no discharge. Which condition is the nurse MOST likely to suspect?', '[{"id": "a", "text": "Herpes (HSV-2)"}, {"id": "b", "text": "Secondary syphilis"}, {"id": "c", "text": "Primary syphilis"}, {"id": "d", "text": "Trichomoniasis"}]'::jsonb, '["c"]', 'A painless ulcer (chancre) indicates primary syphilis, the first stage. Herpes causes painful blisters, and secondary syphilis causes a rash on the palms and soles.', false),
  ('sti', 28, 'A client reports severe genital itching for a week. The nurse notes visible lice in the pubic hair and no discharge. Which treatment is the nurse MOST likely to teach about?', '[{"id": "a", "text": "Permethrin cream"}, {"id": "b", "text": "Metronidazole (Flagyl)"}, {"id": "c", "text": "Acyclovir ointment"}, {"id": "d", "text": "Penicillin G injection"}]'::jsonb, '["a"]', 'Severe genital itching with visible lice in the pubic hair indicates pubic lice, treated with permethrin cream. Trichomoniasis also causes itching but with a frothy green discharge and is treated with metronidazole.', false),
  ('sti', 29, 'A client with recurrent genital herpes is taking valacyclovir. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "The medicine reduces outbreaks, but the herpes virus will not be cured."}, {"id": "b", "text": "We can have sex during an outbreak as long as I am taking the valacyclovir."}, {"id": "c", "text": "My outbreaks may recur, so I''ll watch for painful blisters coming back."}, {"id": "d", "text": "If I become pregnant, I''ll tell my provider because of neonatal herpes."}]'::jsonb, '["b"]', 'Sex is avoided during outbreaks even while taking acyclovir or valacyclovir, which reduce outbreaks but do not cure herpes. Recurring outbreaks and the neonatal risk are accurate.', false),
  ('sti', 30, 'A 26-year-old client has several painless genital warts and asks how they will be treated. Which treatment is the nurse MOST likely to explain?', '[{"id": "a", "text": "Acyclovir to cure the virus"}, {"id": "b", "text": "Penicillin G as drug of choice"}, {"id": "c", "text": "Warts treated with cryotherapy"}, {"id": "d", "text": "Metronidazole for both partners"}]'::jsonb, '["c"]', 'Painless genital warts indicate HPV, and the warts are treated with cryotherapy. Acyclovir is for herpes and does not cure any virus, and penicillin G is for syphilis.', false),
  ('sti', 31, 'A male client with HPV says, "I thought only women get cancer from this virus." Which response by the nurse is BEST?', '[{"id": "a", "text": "You are correct; HPV only affects the cervix, so you have no risk."}, {"id": "b", "text": "HPV causes only genital warts in men, which are treated with cryotherapy."}, {"id": "c", "text": "HPV in men leads mainly to liver cancer, so you''ll need monitoring."}, {"id": "d", "text": "HPV can lead to anal and throat cancers, not only cervical cancer."}]'::jsonb, '["d"]', 'HPV complications include cervical, anal, and throat cancers, so men are also at risk. Liver cancer is a complication of hepatitis B.', false),
  ('sti', 32, 'A client with chronic hepatitis B and ongoing fatigue asks what treatment is available now that the infection is long-term. Which treatment should the nurse expect the provider to order?', '[{"id": "a", "text": "Antiviral therapy for chronic disease"}, {"id": "b", "text": "Hepatitis B vaccine to cure the infection"}, {"id": "c", "text": "Penicillin G for liver infection"}, {"id": "d", "text": "Metronidazole for both partners"}]'::jsonb, '["a"]', 'Antiviral therapy is used for chronic hepatitis B; the vaccine prevents infection but does not treat existing disease.', false),
  ('sti', 33, 'A nurse reviews prenatal STI results for several pregnant clients. Which findings require follow-up to protect the newborn? Select all that apply.', '[{"id": "a", "text": "Positive test for Treponema pallidum"}, {"id": "b", "text": "Positive test for Neisseria gonorrhoeae"}, {"id": "c", "text": "Negative results for all STIs tested"}, {"id": "d", "text": "Positive test for Chlamydia trachomatis"}, {"id": "e", "text": "Painful genital blisters at 37 weeks"}]'::jsonb, '["a", "b", "d", "e"]', 'Correct: syphilis (Treponema pallidum) can cause congenital birth defects, gonorrhea can cause newborn blindness, chlamydia can cause newborn eye infection, and herpes blisters near birth risk neonatal herpes. Wrong: negative results need no follow-up.', true),
  ('sti', 34, 'The nurse in an STI clinic receives four new client messages. Which client should the nurse contact FIRST?', '[{"id": "a", "text": "A parent asking when an 11-year-old can receive Gardasil"}, {"id": "b", "text": "A client with pubic lice asking how to wash the bedding"}, {"id": "c", "text": "A client with genital warts asking when cryotherapy is scheduled"}, {"id": "d", "text": "A client with HIV and CD4 <200 who has a new fever and cough"}]'::jsonb, '["d"]', 'A CD4 count below 200 means AIDS, with risk of opportunistic infections and death, so new signs of infection take priority. The other messages are teaching questions.', false),
  ('sti', 35, 'A nurse compares two clients: one has a thick yellow-green discharge with dysuria, and the other has a foul-smelling, frothy, green discharge with itching. Which finding BEST distinguishes the second client''s infection?', '[{"id": "a", "text": "Strawberry cervix"}, {"id": "b", "text": "Dysuria"}, {"id": "c", "text": "Green color"}, {"id": "d", "text": "Burning"}]'::jsonb, '["a"]', 'A strawberry cervix with frothy green discharge is the clue for trichomoniasis, whereas thick yellow-green discharge with dysuria indicates gonorrhea. Green color, burning, and painful urination can occur with both.', false),
  ('sti', 36, 'A client and her partner are diagnosed with trichomoniasis and prescribed metronidazole (Flagyl). Which instructions should the nurse include? Select all that apply.', '[{"id": "a", "text": "Avoid sex only during outbreaks"}, {"id": "b", "text": "Stop the drug when itching stops"}, {"id": "c", "text": "Treat both partners with Flagyl"}, {"id": "d", "text": "No alcohol while taking Flagyl"}, {"id": "e", "text": "Use permethrin cream on the area"}]'::jsonb, '["c", "d"]', 'Correct: trichomoniasis is treated with metronidazole for both partners, and alcohol is avoided because Flagyl plus alcohol causes severe vomiting. Wrong: permethrin is for pubic lice, avoiding sex during outbreaks is herpes teaching, and the full course is completed even if symptoms resolve.', true),
  ('sti', 37, 'A 19-year-old client''s screening culture is positive for Chlamydia trachomatis. Which prescription is the nurse MOST likely to receive?', '[{"id": "a", "text": "Doxycycline as a single dose or Penicillin G"}, {"id": "b", "text": "Azithromycin (single dose) or Doxycycline × 7 days"}, {"id": "c", "text": "Acyclovir / Valacyclovir to reduce outbreaks"}, {"id": "d", "text": "Metronidazole (Flagyl) for both partners"}]'::jsonb, '["b"]', 'Chlamydia is treated with azithromycin as a single dose or doxycycline for 7 days; doxycycline is not a single-dose regimen. Metronidazole is for trichomoniasis.', false),
  ('sti', 38, 'A client at 10 weeks'' gestation tests positive for Treponema pallidum. She asks why treatment must start right away. Which response by the nurse is BEST?', '[{"id": "a", "text": "Acyclovir treats it; untreated, it can cause neonatal herpes in the baby."}, {"id": "b", "text": "Metronidazole treats it; untreated, it can cause newborn eye infections."}, {"id": "c", "text": "Penicillin G treats it; untreated, it can cause congenital birth defects."}, {"id": "d", "text": "No treatment exists in pregnancy; your baby will be tested after birth."}]'::jsonb, '["c"]', 'Treponema pallidum causes syphilis, for which penicillin G is the drug of choice, and its complications include congenital birth defects. Acyclovir treats herpes and metronidazole treats trichomoniasis.', false),
  ('sti', 39, 'A 21-year-old client has painful genital blisters with flu-like symptoms during a first outbreak. Which teaching points should the nurse include? Select all that apply.', '[{"id": "a", "text": "Acyclovir or valacyclovir reduces outbreaks."}, {"id": "b", "text": "Penicillin G will cure this infection."}, {"id": "c", "text": "There is no cure for this infection."}, {"id": "d", "text": "Avoid sex during outbreaks."}, {"id": "e", "text": "Outbreaks may recur after this one."}]'::jsonb, '["a", "c", "d", "e"]', 'Correct: herpes (HSV-2) is managed with acyclovir or valacyclovir to reduce outbreaks, there is no cure, sex is avoided during outbreaks, and recurring outbreaks are a complication. Wrong: penicillin G is the drug of choice for syphilis, not herpes.', true),
  ('sti', 40, 'A 30-year-old client has an abnormal Pap smear. Which additional findings would support HPV as the cause? Select all that apply.', '[{"id": "a", "text": "Painful genital blisters"}, {"id": "b", "text": "Painless genital warts"}, {"id": "c", "text": "Rash on palms and soles"}, {"id": "d", "text": "Strawberry cervix"}, {"id": "e", "text": "Abnormal Pap smear history"}]'::jsonb, '["b", "e"]', 'Correct: HPV causes painless genital warts and an abnormal Pap smear. Wrong: painful blisters indicate herpes, a palm/sole rash indicates secondary syphilis, and a strawberry cervix indicates trichomoniasis.', true),
  ('sti', 41, 'A client recently treated for gonorrhea asks what can happen if the infection returns and is not treated. Which complications should the nurse include? Select all that apply.', '[{"id": "a", "text": "PID"}, {"id": "b", "text": "Joint infections"}, {"id": "c", "text": "Neurosyphilis"}, {"id": "d", "text": "Infertility"}, {"id": "e", "text": "Newborn blindness"}]'::jsonb, '["a", "b", "d", "e"]', 'Correct: gonorrhea can cause PID, infertility, joint infections, and newborn blindness. Wrong: neurosyphilis is a complication of syphilis.', true),
  ('sti', 42, 'A sexually active client reports several weeks of new symptoms, and the nurse suspects hepatitis B. Which findings support this suspicion? Select all that apply.', '[{"id": "a", "text": "Jaundice"}, {"id": "b", "text": "Strawberry cervix"}, {"id": "c", "text": "Fatigue"}, {"id": "d", "text": "Nausea"}, {"id": "e", "text": "Abdominal pain"}]'::jsonb, '["a", "c", "d", "e"]', 'Correct: hepatitis B causes jaundice, fatigue, nausea, and abdominal pain. Wrong: a strawberry cervix is a sign of trichomoniasis.', true),
  ('sti', 43, 'A couple tells the nurse, "If we use condoms every single time, we''ll be 100% protected from STIs, right?" Which response by the nurse is BEST?', '[{"id": "a", "text": "Condoms reduce risk, but only abstinence is 100% effective."}, {"id": "b", "text": "Yes, condoms used correctly every time are 100% effective."}, {"id": "c", "text": "Condoms protect only against HIV, not against other STIs."}, {"id": "d", "text": "Condoms are unnecessary once both of you have been tested."}]'::jsonb, '["a"]', 'Condoms reduce STI risk, but only abstinence is 100% effective. Claiming condoms give complete protection is inaccurate.', false),
  ('sti', 44, 'A 24-year-old male client has a thick yellow-green urethral discharge and dysuria. Which organism should the nurse suspect is MOST likely responsible?', '[{"id": "a", "text": "Trichomonas vaginalis"}, {"id": "b", "text": "Neisseria gonorrhoeae"}, {"id": "c", "text": "Treponema pallidum"}, {"id": "d", "text": "Chlamydia trachomatis"}]'::jsonb, '["b"]', 'Thick yellow-green discharge plus dysuria is the clue for gonorrhea, caused by Neisseria gonorrhoeae. Trichomonas vaginalis causes a frothy green discharge with a strawberry cervix.', false),
  ('sti', 45, 'After applying permethrin cream for pubic lice, a client asks what else needs to be done at home. Which instruction by the nurse is BEST?', '[{"id": "a", "text": "Avoid sex only during outbreaks."}, {"id": "b", "text": "Take metronidazole with no alcohol."}, {"id": "c", "text": "Wash clothes/bedding in hot water."}, {"id": "d", "text": "Get the Gardasil vaccine this week."}]'::jsonb, '["c"]', 'Pubic lice are treated with permethrin cream, and clothes and bedding are washed in hot water. Avoiding sex during outbreaks is herpes teaching, and metronidazole is for trichomoniasis.', false),
  ('sti', 46, 'Three weeks after a known exposure, a client reports fever, sore throat, and body aches, and an HIV test is later positive. Which statement BEST explains these early findings?', '[{"id": "a", "text": "These findings confirm the client has AIDS."}, {"id": "b", "text": "These are signs of an opportunistic infection."}, {"id": "c", "text": "These indicate a first herpes outbreak only."}, {"id": "d", "text": "HIV causes flu-like symptoms initially."}]'::jsonb, '["d"]', 'HIV presents with flu-like symptoms initially; AIDS is defined by a CD4 count below 200 with opportunistic infections, which develop later.', false),
  ('sti', 47, 'A pregnant client with untreated chlamydia asks whether the infection could affect her baby. Which complication should the nurse include in the response as the MOST likely newborn effect?', '[{"id": "a", "text": "Neonatal herpes"}, {"id": "b", "text": "Congenital birth defects"}, {"id": "c", "text": "Newborn eye infection"}, {"id": "d", "text": "Liver failure"}]'::jsonb, '["c"]', 'Chlamydia complications include newborn eye infection. Neonatal herpes is an HSV complication and congenital birth defects are a syphilis complication.', false),
  ('sti', 48, 'A client is treated for gonorrhea and says, "My boyfriend doesn''t have any symptoms, so he doesn''t need to come in." Which response by the nurse is BEST?', '[{"id": "a", "text": "Your partner needs treatment only if he develops symptoms later."}, {"id": "b", "text": "Your treatment alone will protect your partner from the infection."}, {"id": "c", "text": "Your partner should wait for a symptom check in about six months."}, {"id": "d", "text": "Both partners are treated, and partner treatment prevents reinfection."}]'::jsonb, '["d"]', 'Gonorrhea treatment includes both partners, and partner notification and treatment prevents reinfection. An asymptomatic partner can still reinfect the client.', false),
  ('sti', 49, 'A nurse reviews findings for several clients in a sexual health clinic. Which findings suggest a viral STI that has no cure but can be managed? Select all that apply.', '[{"id": "a", "text": "Painless chancre on the genitals"}, {"id": "b", "text": "CD4 count below 200 with weight loss"}, {"id": "c", "text": "Painless warts and an abnormal Pap"}, {"id": "d", "text": "Painful blisters with flu-like symptoms"}, {"id": "e", "text": "Frothy green discharge, strawberry cervix"}]'::jsonb, '["b", "c", "d"]', 'Correct: painful blisters with flu-like symptoms (herpes), a CD4 count below 200 with weight loss (HIV/AIDS), and painless warts with an abnormal Pap (HPV) are viral STIs with no cure. Wrong: trichomoniasis (frothy green discharge, strawberry cervix) is a curable parasitic STI, and a painless chancre (syphilis) is a curable bacterial STI.', true),
  ('sti', 50, 'A 22-year-old client reports burning urination, an abnormal discharge, and pelvic pain. Her partner was recently treated for an STI that is often asymptomatic in women. Which actions should the nurse anticipate? Select all that apply.', '[{"id": "a", "text": "Azithromycin as a single dose"}, {"id": "b", "text": "Report to the health department"}, {"id": "c", "text": "Permethrin cream for the area"}, {"id": "d", "text": "Acyclovir to shorten outbreaks"}, {"id": "e", "text": "Treat for gonorrhea as well"}]'::jsonb, '["a", "b", "e"]', 'Correct: these findings suggest chlamydia, treated with azithromycin as a single dose (or doxycycline × 7 days); chlamydia is reportable; and chlamydia and gonorrhea often co-occur, so both are treated. Wrong: permethrin is for pubic lice and acyclovir is for herpes.', true),
  ('complications', 1, 'A nurse in the emergency department receives four clients in early pregnancy at the same time. Which client should the nurse see FIRST?', '[{"id": "a", "text": "9 weeks; bleeding with a closed cervix; BP 118/76, HR 84"}, {"id": "b", "text": "7 weeks; unilateral abdominal pain and bleeding; BP 84/50, HR 128"}, {"id": "c", "text": "12 weeks; extreme nausea/vomiting; uterus larger than expected for dates"}, {"id": "d", "text": "10 weeks; no symptoms; ultrasound shows the fetus died and was not expelled"}]'::jsonb, '["b"]', 'Unilateral pain with bleeding plus low BP/high HR points to a ruptured ectopic pregnancy, which means hemorrhagic shock and is an emergency. The client with molar pregnancy findings is urgent but not an emergency, and the threatened miscarriage client is stable with a closed cervix.', false),
  ('complications', 2, 'A client at 7 weeks of pregnancy is being evaluated for one-sided lower abdominal pain and vaginal bleeding. Over 30 minutes her BP falls from 116/74 to 86/52 mm Hg, her HR rises from 88 to 126/min, and the pain is worsening. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Prepare to administer the prescribed methotrexate"}, {"id": "b", "text": "Draw a serum hCG to begin trending it to zero"}, {"id": "c", "text": "Secure IV access and fluids; prep for surgery"}, {"id": "d", "text": "Offer emotional support and grief counseling"}]'::jsonb, '["c"]', 'Falling BP and rising HR with unilateral pain and bleeding signal a ruptured ectopic pregnancy and hemorrhagic shock; the priority is IV access, fluids, and prep for surgery. Methotrexate is used only if the ectopic is unruptured, and hCG monitoring and emotional support are not the first priority in shock.', false),
  ('complications', 3, 'A client with a confirmed unruptured ectopic pregnancy is waiting in the emergency department for her first dose of methotrexate. On arrival she had unilateral pelvic pain, light vaginal bleeding, BP 118/72 mm Hg, and HR 82/min. Which new findings suggest the tube may have ruptured and require IMMEDIATE follow-up? Select all that apply.', '[{"id": "a", "text": "Pain that now radiates to the shoulder"}, {"id": "b", "text": "A positive hCG on the repeat test"}, {"id": "c", "text": "BP that is now 88/54 mm Hg"}, {"id": "d", "text": "HR that is now 124/min"}, {"id": "e", "text": "Light bleeding, unchanged since arrival"}]'::jsonb, '["a", "c", "d"]', '(a) Shoulder pain is referred from diaphragm irritation by blood, suggesting rupture. (c) and (d) Low BP and high HR are the vital-sign changes of a ruptured ectopic. (b) A positive hCG is expected — after treatment hCG is monitored until it reaches zero, so a positive result does not signal rupture. (e) Vaginal bleeding is already part of the ectopic picture; unchanged light bleeding is not a new rupture finding.', true),
  ('complications', 4, 'A client with a suspected ectopic pregnancy is resting on a stretcher when she reports a new ache in her right shoulder. She has had no injury and says it feels different from a pulled muscle. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Blood may be irritating the diaphragm, suggesting rupture"}, {"id": "b", "text": "Lying flat on the stretcher is the likely cause of the ache"}, {"id": "c", "text": "Shoulder pain is an early sign of a threatened miscarriage"}, {"id": "d", "text": "This referred pain is expected and does not need follow-up"}]'::jsonb, '["a"]', 'In ectopic pregnancy, shoulder pain is referred from diaphragm irritation by blood, which suggests the tube has ruptured and internal hemorrhage is occurring. It is not a sign of threatened miscarriage (bleeding with a closed cervix) and must not be dismissed as expected.', false),
  ('complications', 5, 'A nurse reviews the records of four clients who have each been diagnosed with an ectopic pregnancy and unilateral pain. Which client is the MOST appropriate candidate for methotrexate?', '[{"id": "a", "text": "Pain now also felt in the shoulder; blood irritating the diaphragm"}, {"id": "b", "text": "Low BP and high HR; IV fluids running; surgical team notified"}, {"id": "c", "text": "Ultrasound shows blood in the abdomen from the fallopian tube"}, {"id": "d", "text": "Tube intact on ultrasound; stable vitals; agrees to hCG checks"}]'::jsonb, '["d"]', 'Methotrexate is used if the ectopic is unruptured — an intact tube with stable vitals — followed by hCG monitoring until zero. Shoulder pain from blood, low BP/high HR, and blood in the abdomen all indicate rupture, which is treated with surgery.', false),
  ('complications', 6, 'A nurse is preparing methotrexate for a client with an unruptured ectopic pregnancy. A nursing student who is 10 weeks pregnant offers to draw up the dose and asks what precautions apply. Which response by the nurse is BEST?', '[{"id": "a", "text": "No precautions are needed for a single intramuscular dose."}, {"id": "b", "text": "Methotrexate is teratogenic, so it is handled with gloves."}, {"id": "c", "text": "It acts only on the fallopian tube, so it is safe to handle."}, {"id": "d", "text": "Gloves are needed only if the vial is cracked or leaking."}]'::jsonb, '["b"]', 'Methotrexate is teratogenic and must be handled with gloves, which matters even more for a pregnant student. It stops cell division, so it is not safe to handle without precautions.', false),
  ('complications', 7, 'A client with an unruptured ectopic pregnancy received methotrexate and is being discharged home with follow-up appointments. Which statements by the client indicate understanding of the teaching? Select all that apply.', '[{"id": "a", "text": "\"I will need hCG monitoring until it is zero.\""}, {"id": "b", "text": "\"If the tube ruptures, more methotrexate will fix it.\""}, {"id": "c", "text": "\"Once my bleeding stops, I can skip the hCG checks.\""}, {"id": "d", "text": "\"Methotrexate stops cell division in the pregnancy.\""}, {"id": "e", "text": "\"One hCG test next week will show if it worked.\""}]'::jsonb, '["a", "d"]', '(d) Correct: methotrexate stops cell division. (a) Correct: hCG is monitored until zero. (e) Wrong: a single test is not enough; monitoring continues until hCG reaches zero. (b) Wrong: a ruptured ectopic is treated with surgery, not methotrexate. (c) Wrong: bleeding stopping does not end follow-up; hCG must reach zero.', true),
  ('complications', 8, 'A 27-year-old client with a positive hCG at 6 weeks of pregnancy reports sharp pain on the left side of her lower abdomen and vaginal bleeding. BP is 120/76 mm Hg and HR is 86/min, and her uterus is not larger than expected for dates. Which complication is the nurse MOST concerned about?', '[{"id": "a", "text": "Placenta previa"}, {"id": "b", "text": "Molar pregnancy"}, {"id": "c", "text": "Ectopic pregnancy"}, {"id": "d", "text": "Threatened miscarriage"}]'::jsonb, '["c"]', 'Unilateral (one-sided) pain plus bleeding is the key sign of ectopic pregnancy, an emergency because the tube can rupture. Previa causes painless bleeding in the 2nd or 3rd trimester, molar pregnancy causes a uterus larger than expected for dates, and threatened miscarriage is defined by bleeding with a closed cervix rather than one-sided pain.', false),
  ('complications', 9, 'A client with an unruptured ectopic pregnancy in the fallopian tube has stable vital signs. She asks the nurse, "Why can''t we just wait and see if this pregnancy keeps growing?" Which response by the nurse is BEST?', '[{"id": "a", "text": "\"The tube can rupture and cause internal hemorrhage.\""}, {"id": "b", "text": "\"The pregnancy may move into the uterus on its own.\""}, {"id": "c", "text": "\"Waiting is safe until the hCG level reaches zero.\""}, {"id": "d", "text": "\"The risk is low because the pain is on one side only.\""}]'::jsonb, '["a"]', 'An ectopic pregnancy most commonly implants in the fallopian tube, and the risk is tube rupture leading to internal hemorrhage, an emergency. One-sided pain is a warning sign, not reassurance, and hCG is monitored to zero after treatment rather than while waiting.', false),
  ('complications', 10, 'A client with an ectopic pregnancy suddenly becomes pale and lightheaded. The provider confirms the fallopian tube has ruptured and the client is in hemorrhagic shock. Which actions does the nurse anticipate? Select all that apply.', '[{"id": "a", "text": "Give methotrexate IM now"}, {"id": "b", "text": "Prep the client for surgery"}, {"id": "c", "text": "Start IV fluids"}, {"id": "d", "text": "Recheck hCG before any surgery"}, {"id": "e", "text": "Establish IV access"}]'::jsonb, '["b", "c", "e"]', '(b), (c), (e) Correct: a ruptured ectopic means hemorrhagic shock, and the priority is IV access, fluids, and prep for surgery. (a) Wrong: methotrexate is for an unruptured ectopic; surgery is used if ruptured. (d) Wrong: hCG is monitored until zero as follow-up and must not delay surgery for a rupture.', true),
  ('complications', 11, 'A client at 10 weeks of pregnancy arrives with vaginal bleeding and cramping. On speculum exam her cervix is dilated, and no tissue has passed yet. She asks whether the pregnancy can continue. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "\"Rest at home may allow this pregnancy to continue.\""}, {"id": "b", "text": "\"A D&C will be needed to remove the retained tissue.\""}, {"id": "c", "text": "\"This is a threatened loss; the pregnancy may continue.\""}, {"id": "d", "text": "\"With a dilated cervix, this loss cannot be stopped.\""}]'::jsonb, '["d"]', 'Bleeding with a dilated cervix is an inevitable miscarriage, which cannot be stopped. A pregnancy may continue only in a threatened miscarriage (closed cervix), and a D&C for retained tissue applies to an incomplete miscarriage, but no tissue has passed here.', false),
  ('complications', 12, 'A client at 8 weeks of pregnancy reports light vaginal bleeding. Her cervix is closed, and ultrasound shows a fetal heartbeat. She asks, "Am I losing the baby?" Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Your cervix is closed, so the pregnancy may continue.\""}, {"id": "b", "text": "\"Bleeding at this stage means the loss cannot be stopped.\""}, {"id": "c", "text": "\"You will likely need a D&C to remove retained tissue.\""}, {"id": "d", "text": "\"Bleeding this early means the tube may have ruptured.\""}]'::jsonb, '["a"]', 'Bleeding with a closed cervix is a threatened miscarriage, and the pregnancy may continue. A loss that cannot be stopped requires a dilated cervix (inevitable), and a D&C is anticipated when tissue is retained (incomplete).', false),
  ('complications', 13, 'A nurse reviews the findings of five clients who are 8 to 14 weeks pregnant and have vaginal bleeding. Which findings indicate a pregnancy loss that cannot be prevented? Select all that apply.', '[{"id": "a", "text": "Fetus died but not expelled on US"}, {"id": "b", "text": "Spotting, closed cervix, and a heartbeat"}, {"id": "c", "text": "Bleeding with a closed cervix"}, {"id": "d", "text": "Bleeding with a dilated cervix"}, {"id": "e", "text": "Some tissue expelled, some retained"}]'::jsonb, '["a", "d", "e"]', '(d) Correct: bleeding with a dilated cervix is inevitable and cannot be stopped. (e) Correct: an incomplete miscarriage has some tissue expelled and some retained and may need a D&C. (a) Correct: in a missed miscarriage the fetus has died but has not been expelled, detected by US. (b) and (c) Wrong: bleeding with a closed cervix is a threatened miscarriage, and the pregnancy may continue.', true),
  ('complications', 14, 'A client at 11 weeks of pregnancy passed some tissue at home and continues to bleed. Ultrasound shows that products of conception remain in the uterus. Which intervention is the provider MOST likely to plan?', '[{"id": "a", "text": "Methotrexate to stop cell division"}, {"id": "b", "text": "A D&C to remove the retained tissue"}, {"id": "c", "text": "Bed rest and fetal heart rate monitoring"}, {"id": "d", "text": "Discharge, since the tissue has already passed"}]'::jsonb, '["b"]', 'When some tissue is expelled and some is retained (incomplete miscarriage), a D&C may be needed. Discharge fits a complete miscarriage, in which all products of conception have passed, and methotrexate is the treatment for an unruptured ectopic.', false),
  ('complications', 15, 'At a routine 12-week visit, a client who has had no bleeding, cramping, or other symptoms has an ultrasound showing the fetus has died but has not been expelled. She says, "How can this be? I''ve felt completely fine." Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "\"Bleeding comes first in a loss, so the scan may be wrong.\""}, {"id": "b", "text": "\"Your cervix is closed, so the pregnancy may still continue.\""}, {"id": "c", "text": "\"A missed miscarriage has no symptoms and is found on US.\""}, {"id": "d", "text": "\"All products of conception passed without you noticing.\""}]'::jsonb, '["c"]', 'In a missed miscarriage the fetus has died but is not expelled; there are no symptoms, and it is detected by US. A closed cervix with a pregnancy that may continue describes threatened miscarriage, which does not apply when the fetus has died.', false),
  ('complications', 16, 'A client at 8 weeks of pregnancy had heavy bleeding and cramping at home and passed tissue. Her bleeding is now light, and ultrasound shows the uterus is empty. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Inevitable miscarriage; the cervix is dilated and loss is ongoing"}, {"id": "b", "text": "Incomplete miscarriage; a D&C is needed for retained tissue"}, {"id": "c", "text": "Threatened miscarriage; the pregnancy may still continue"}, {"id": "d", "text": "Complete miscarriage; all products of conception passed"}]'::jsonb, '["d"]', 'An empty uterus after passing tissue means all products of conception passed — a complete miscarriage. An incomplete miscarriage would show retained tissue on ultrasound and may need a D&C.', false),
  ('complications', 17, 'A client at 9 weeks of pregnancy is admitted with bleeding and a dilated cervix. She is tearful and her partner is at the bedside. Which nursing actions are appropriate? Select all that apply.', '[{"id": "a", "text": "Explain that the pregnancy may continue"}, {"id": "b", "text": "Monitor bleeding and vitals"}, {"id": "c", "text": "Provide emotional support"}, {"id": "d", "text": "Offer grief counseling and referrals"}, {"id": "e", "text": "Prepare for a possible D&C"}]'::jsonb, '["b", "c", "d", "e"]', 'Bleeding with a dilated cervix is an inevitable miscarriage. (b), (c), (d), (e) Correct: nursing care for miscarriage includes emotional support, monitoring bleeding and vitals, a possible D&C, and grief counseling and referrals. (a) Wrong: the pregnancy may continue only when the cervix is closed (threatened); a dilated cervix means the loss cannot be stopped.', true),
  ('complications', 18, 'A nurse on a gynecology unit receives report on four clients who are experiencing a miscarriage. Which client should the nurse assess FIRST?', '[{"id": "a", "text": "Threatened miscarriage; spotting; cervix closed; vitals stable"}, {"id": "b", "text": "Missed miscarriage; no symptoms; awaiting D&C; tearful"}, {"id": "c", "text": "Incomplete miscarriage; heavy bleeding; BP 88/52, HR 122"}, {"id": "d", "text": "Complete miscarriage; light bleeding; asking for grief resources"}]'::jsonb, '["c"]', 'Nursing care for miscarriage centers on monitoring bleeding and vitals; heavy bleeding with low BP and a high HR is the unstable finding. The other clients need emotional support and grief counseling but are physiologically stable.', false),
  ('complications', 19, 'A client is recovering after a D&C for an incomplete miscarriage. Her bleeding is light and vitals are stable, but she is crying quietly and says, "I keep wondering what I did wrong." Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Offer grief counseling and referrals"}, {"id": "b", "text": "Teach her to avoid pregnancy for 6–12 months"}, {"id": "c", "text": "Schedule weekly hCG checks until zero"}, {"id": "d", "text": "Delay emotional topics until bleeding stops"}]'::jsonb, '["a"]', 'Nursing care after miscarriage includes emotional support and offering grief counseling and referrals. Avoiding pregnancy for 6–12 months and weekly hCG checks to zero are the follow-up for molar pregnancy, not miscarriage.', false),
  ('complications', 20, 'A nurse is reviewing the charts of four clients who experienced a pregnancy loss. Based on gestational age, which client''s loss is MOST accurately classified as a miscarriage (spontaneous abortion)?', '[{"id": "a", "text": "Loss at 22 weeks after bleeding with a dilated cervix"}, {"id": "b", "text": "Loss at 19 weeks after bleeding with a dilated cervix"}, {"id": "c", "text": "Loss at 24 weeks; fetus died, found on ultrasound"}, {"id": "d", "text": "Loss at 21 weeks; all products of conception passed"}]'::jsonb, '["b"]', 'A miscarriage is a pregnancy loss before 20 weeks, so only the loss at 19 weeks qualifies. The losses at 21, 22, and 24 weeks occurred after the 20-week cutoff even though their findings resemble miscarriage types.', false),
  ('complications', 21, 'A client at 33 weeks of pregnancy arrives reporting bright red vaginal bleeding that began while she was resting. She denies abdominal pain, and her uterus is not rigid. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Perform a vaginal exam to assess the cervix"}, {"id": "b", "text": "Prepare for emergency delivery of the baby"}, {"id": "c", "text": "Administer magnesium sulfate to prevent seizures"}, {"id": "d", "text": "Monitor the fetal heart rate"}]'::jsonb, '["d"]', 'Painless bright red bleeding in the 3rd trimester suggests placenta previa, managed by monitoring the fetal heart rate and planning a C-section; a vaginal exam must never be done because it can cause massive hemorrhage. Emergency delivery is the treatment for abruption (painful, rigid uterus).', false),
  ('complications', 22, 'A nurse is assessing a client at 30 weeks of pregnancy who has vaginal bleeding. Which findings would lead the nurse to suspect placenta previa rather than placental abruption? Select all that apply.', '[{"id": "a", "text": "Bleeding without any pain"}, {"id": "b", "text": "Sudden severe abdominal pain"}, {"id": "c", "text": "Signs of fetal distress"}, {"id": "d", "text": "Bleeding that is bright red"}, {"id": "e", "text": "A rigid, board-like uterus"}]'::jsonb, '["a", "d"]', '(a) and (d) Correct: placenta previa causes painless bright red bleeding in the 2nd or 3rd trimester. (e) Wrong: a rigid, board-like uterus is a sign of abruption. (b) Wrong: sudden severe abdominal pain is an abruption sign. (c) Wrong: fetal distress is listed among the signs of abruption.', true),
  ('complications', 23, 'A newly licensed nurse caring for a client at 30 weeks of pregnancy with painless bright red bleeding asks why the provider wrote "No vaginal exams." Which explanation by the charge nurse is BEST?', '[{"id": "a", "text": "\"An exam could trigger a seizure if her BP is high.\""}, {"id": "b", "text": "\"An exam could separate the placenta from the uterine wall.\""}, {"id": "c", "text": "\"An exam over a low placenta can cause massive hemorrhage.\""}, {"id": "d", "text": "\"An exam is not needed because a C-section is planned.\""}]'::jsonb, '["c"]', 'In placenta previa the placenta attaches over or near the cervix, and a vaginal exam can cause massive hemorrhage. Premature separation from the uterine wall describes abruption, and although a C-section is planned, that is not the reason exams are forbidden.', false),
  ('complications', 24, 'A client at 34 weeks of pregnancy with placenta previa has had no bleeding for 2 days. She asks, "Once things settle down, can I still plan a vaginal birth?" Which response by the nurse is BEST?', '[{"id": "a", "text": "\"The placenta is blocking the birth canal, so a C-section is planned.\""}, {"id": "b", "text": "\"Yes, a vaginal birth is fine once the bleeding has stopped for 2 days.\""}, {"id": "c", "text": "\"Delivery must happen right away because the uterus is now rigid.\""}, {"id": "d", "text": "\"A vaginal exam will be done at 37 weeks to decide on the plan.\""}]'::jsonb, '["a"]', 'In placenta previa the placenta attaches over or near the cervix, blocking the birth canal, so the plan is a C-section delivery. A vaginal exam is never performed, and immediate delivery for a rigid uterus describes abruption.', false),
  ('complications', 25, 'A client at 31 weeks of pregnancy is admitted with placenta previa. Her bleeding has slowed, and her vitals are stable. Which interventions should the nurse include in the plan of care? Select all that apply.', '[{"id": "a", "text": "Perform a vaginal exam each shift"}, {"id": "b", "text": "Plan for C-section delivery"}, {"id": "c", "text": "Give magnesium sulfate for seizures"}, {"id": "d", "text": "Prepare for a D&C to remove tissue"}, {"id": "e", "text": "Monitor the fetal heart rate"}]'::jsonb, '["b", "e"]', '(b) and (e) Correct: placenta previa is managed with fetal heart rate monitoring and a planned C-section delivery. (a) Wrong: a vaginal exam must never be performed because it can cause massive hemorrhage. (c) Wrong: magnesium sulfate prevents seizures in preeclampsia/eclampsia. (d) Wrong: a D&C removes uterine contents in incomplete miscarriage or molar pregnancy, not previa.', true),
  ('complications', 26, 'A client at 36 weeks of pregnancy is diagnosed with placental abruption after reporting sudden severe abdominal pain and dark red bleeding. She asks whether delivery can wait until her partner arrives in 3 hours. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Yes; we will keep you on bed rest and plan a C-section at term.\""}, {"id": "b", "text": "\"It is life-threatening for you and the baby; delivery is needed now.\""}, {"id": "c", "text": "\"Yes, as long as your blood pressure stays normal for the next 3 hours.\""}, {"id": "d", "text": "\"We will give magnesium sulfate first, then reassess in 3 hours.\""}]'::jsonb, '["b"]', 'Placental abruption is life-threatening for mother and baby and is treated with emergency delivery. Bed rest with a planned C-section is the management for placenta previa, and magnesium sulfate prevents seizures in preeclampsia.', false),
  ('complications', 27, 'A client at 35 weeks of pregnancy who was in a car crash 1 hour ago is being evaluated for placental abruption. Which findings are an expected finding if abruption has occurred? Select all that apply.', '[{"id": "a", "text": "Signs of fetal distress"}, {"id": "b", "text": "Sudden severe abdominal pain"}, {"id": "c", "text": "Dark red bleeding"}, {"id": "d", "text": "Rigid, board-like uterus"}, {"id": "e", "text": "Painless bright red bleeding"}]'::jsonb, '["a", "b", "c", "d"]', '(a), (b), (c), (d) Correct: abruption signs are sudden severe abdominal pain, dark red bleeding, a rigid board-like uterus, and fetal distress. (e) Wrong: painless bright red bleeding is the key sign of placenta previa.', true),
  ('complications', 28, 'A client at 34 weeks of pregnancy with a confirmed placental abruption is being moved to the birthing unit. Which actions should the nurse anticipate? Select all that apply.', '[{"id": "a", "text": "Prepare for emergency delivery"}, {"id": "b", "text": "Monitor vitals, fluids, and bleeding"}, {"id": "c", "text": "Plan bed rest and a C-section at term"}, {"id": "d", "text": "Give magnesium sulfate to stop bleeding"}, {"id": "e", "text": "Recheck in 1 week if bleeding slows"}]'::jsonb, '["a", "b"]', '(a) and (b) Correct: abruption is treated with emergency delivery while monitoring vitals, fluids, and bleeding. (c) Wrong: bed rest and a planned C-section are previa management. (d) Wrong: magnesium sulfate is given to prevent seizures in preeclampsia/eclampsia, not to stop bleeding. (e) Wrong: abruption is life-threatening and is not managed by waiting.', true),
  ('complications', 29, 'A nurse reviews prenatal data for four clients at a clinic visit. Which client''s findings are MOST consistent with preeclampsia?', '[{"id": "a", "text": "16 weeks; high BP and proteinuria; no headache"}, {"id": "b", "text": "30 weeks; normal BP; mild ankle swelling after work"}, {"id": "c", "text": "12 weeks; high BP; extreme nausea/vomiting; large uterus"}, {"id": "d", "text": "28 weeks; high BP, proteinuria, and headache"}]'::jsonb, '["d"]', 'Preeclampsia is high BP plus proteinuria after 20 weeks gestation, with signs such as headache. The client at 16 weeks has high BP and proteinuria but is before 20 weeks, and extreme nausea/vomiting with a large uterus at 12 weeks suggests molar pregnancy.', false),
  ('complications', 30, 'A client at 32 weeks of pregnancy reports a headache and blurry vision. Her BP is 164/110 mm Hg, her urine shows proteinuria, and her hands and face are swollen. Which medication order is the nurse MOST likely to receive?', '[{"id": "a", "text": "Magnesium sulfate to prevent seizures"}, {"id": "b", "text": "Calcium gluconate to prevent seizures"}, {"id": "c", "text": "Methotrexate to stop cell division"}, {"id": "d", "text": "Magnesium sulfate to cure the condition"}]'::jsonb, '["a"]', 'These findings after 20 weeks indicate preeclampsia, and magnesium sulfate may be given to prevent seizures. Magnesium does not cure it — delivery is the only cure — and calcium gluconate is the antidote for magnesium toxicity, not seizure prevention.', false),
  ('complications', 31, 'A client at 26 weeks of pregnancy who had a normal BP at her last visit calls the prenatal clinic. Which reported findings should the nurse report to the health care provider as possible signs of preeclampsia? Select all that apply.', '[{"id": "a", "text": "Swelling of her hands and face"}, {"id": "b", "text": "Painless bright red bleeding"}, {"id": "c", "text": "High BP on her home monitor"}, {"id": "d", "text": "A severe headache"}, {"id": "e", "text": "Blurry vision since this morning"}]'::jsonb, '["a", "c", "d", "e"]', '(a), (c), (d), (e) Correct: at 26 weeks (after 20 weeks), headache, blurry vision, swelling of hands/face, and high BP are signs of preeclampsia. (b) Wrong: painless bright red bleeding is the key sign of placenta previa, not preeclampsia.', true),
  ('complications', 32, 'A client at 33 weeks of pregnancy with preeclampsia is receiving magnesium sulfate. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"My blood pressure will be checked often.\""}, {"id": "b", "text": "\"The magnesium is to help prevent seizures.\""}, {"id": "c", "text": "\"The magnesium will cure this, so I can go to term.\""}, {"id": "d", "text": "\"Delivering the baby is the real cure for this.\""}]'::jsonb, '["c"]', 'Magnesium sulfate is given to prevent seizures; delivery is the only cure for preeclampsia, so the client misunderstands. BP monitoring and seizure prevention are accurate parts of the plan.', false),
  ('complications', 33, 'A client at 37 weeks of pregnancy who has preeclampsia suddenly has a tonic-clonic seizure in bed. Which action should the nurse take FIRST?', '[{"id": "a", "text": "Prepare the client for emergency delivery"}, {"id": "b", "text": "Maintain seizure precautions for safety"}, {"id": "c", "text": "Administer calcium gluconate IV push"}, {"id": "d", "text": "Obtain a urine sample for proteinuria"}]'::jsonb, '["b"]', 'Preeclampsia plus seizures is eclampsia, and the emergency care begins with seizure precautions (seizure safety), followed by IV magnesium sulfate and preparation for emergency delivery. Calcium gluconate is the antidote for magnesium toxicity, not a seizure treatment.', false),
  ('complications', 34, 'A nurse is precepting a new graduate who is caring for a client with eclampsia receiving IV magnesium sulfate. Which statement by the new graduate requires follow-up by the preceptor?', '[{"id": "a", "text": "\"We keep her seizure precautions in place.\""}, {"id": "b", "text": "\"We should prepare her for emergency delivery.\""}, {"id": "c", "text": "\"Calcium gluconate is the antidote for mag toxicity.\""}, {"id": "d", "text": "\"Calcium gluconate is what we give to stop her seizures.\""}]'::jsonb, '["d"]', 'Magnesium sulfate IV is given for eclampsia seizures; calcium gluconate is the antidote for mag toxicity, so this statement is incorrect. Seizure precautions and preparation for emergency delivery are correct parts of eclampsia care.', false),
  ('complications', 35, 'A triage nurse in the emergency department receives five clients within 10 minutes. Which clients'' findings require IMMEDIATE follow-up? Select all that apply.', '[{"id": "a", "text": "After D&C for molar pregnancy; due for weekly hCG"}, {"id": "b", "text": "35 weeks; painful dark red bleeding; rigid uterus"}, {"id": "c", "text": "37 weeks with preeclampsia; now having a seizure"}, {"id": "d", "text": "13-year-old; sudden severe scrotal pain for 3 hours"}, {"id": "e", "text": "11 weeks; uterus large for dates; high hCG; stable"}]'::jsonb, '["b", "c", "d"]', '(b) Correct: painful dark red bleeding with a rigid uterus is abruption, an emergency. (c) Correct: preeclampsia plus seizures is eclampsia, an emergency. (d) Correct: sudden severe scrotal pain suggests testicular torsion, an emergency needing surgery within 6h. (e) Wrong: a uterus large for dates with high hCG suggests molar pregnancy, which is urgent but not an emergency. (a) Wrong: weekly hCG monitoring after D&C is routine follow-up.', true),
  ('complications', 36, 'A 14-year-old client reports scrotal pain that began suddenly 90 minutes ago, with swelling, redness, and vomiting. When the nurse gently lifts the scrotum, the pain does not improve. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "The findings fit testicular torsion, a surgical emergency"}, {"id": "b", "text": "The findings fit prostatitis, needing 4–6 weeks of antibiotics"}, {"id": "c", "text": "Pain not eased by lifting the scrotum makes torsion unlikely"}, {"id": "d", "text": "Swelling and redness suggest an infection treated with NSAIDs"}]'::jsonb, '["a"]', 'Sudden severe scrotal pain with swelling, redness, nausea/vomiting, and pain NOT relieved by lifting the scrotum are signs of testicular torsion, a surgical emergency. Pain not relieved by lifting supports torsion rather than ruling it out, and prostatitis presents with painful urination, fever and chills, and pelvic pain.', false),
  ('complications', 37, 'A nurse in a urology clinic is triaging four male clients who called with genital or pelvic concerns. Which client should the nurse see FIRST?', '[{"id": "a", "text": "52-year-old; fever, chills, and low back/pelvic pain for 2 days"}, {"id": "b", "text": "45-year-old; day 10 of antibiotics for prostatitis; mild pelvic pain"}, {"id": "c", "text": "16-year-old; sudden severe scrotal pain that began 5 hours ago"}, {"id": "d", "text": "60-year-old; painful ejaculation and painful urination for a week"}]'::jsonb, '["c"]', 'Sudden severe scrotal pain suggests testicular torsion, a surgical emergency that needs detorsion within 6h to save the testicle; at 5 hours the window is nearly closed. The other clients have findings of prostatitis, treated with a long course of antibiotics, fluids, and NSAIDs.', false),
  ('complications', 38, 'A 15-year-old client is brought to the emergency department by a parent because of scrotal pain. Which assessment findings support testicular torsion? Select all that apply.', '[{"id": "a", "text": "Fever and chills with painful urination"}, {"id": "b", "text": "Absent cremasteric reflex"}, {"id": "c", "text": "Pain relieved by lifting the scrotum"}, {"id": "d", "text": "Nausea and vomiting"}, {"id": "e", "text": "Sudden onset of severe scrotal pain"}]'::jsonb, '["b", "d", "e"]', '(b), (d), (e) Correct: torsion signs are sudden, severe scrotal pain, nausea/vomiting, and an absent cremasteric reflex. (a) Wrong: fever and chills with painful urination are signs of prostatitis. (c) Wrong: in torsion the pain is NOT relieved by lifting the scrotum.', true),
  ('complications', 39, 'The parent of a 13-year-old with sudden severe scrotal pain that started 4 hours ago asks whether surgery can wait until morning, when the family''s own urologist is available. Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Waiting is fine if the pain eases when the scrotum is lifted.\""}, {"id": "b", "text": "\"Detorsion is needed within 6 hours to save the testicle.\""}, {"id": "c", "text": "\"Surgery can wait if antibiotics are started tonight.\""}, {"id": "d", "text": "\"Waiting is safe as long as he is not vomiting.\""}]'::jsonb, '["b"]', 'Testicular torsion cuts off blood supply to the testicle and requires immediate surgical detorsion within 6h to save it; at 4 hours, waiting until morning would exceed that window. In torsion the pain is not relieved by lifting the scrotum, and antibiotics are the treatment for prostatitis.', false),
  ('complications', 40, 'A 47-year-old client is diagnosed with prostatitis. His temperature is 38.9°C (102°F) with chills, and he reports pelvic pain that makes him reluctant to drink. Which plan of care is the nurse MOST likely to reinforce?', '[{"id": "a", "text": "Immediate surgical detorsion within 6 hours"}, {"id": "b", "text": "A 3-day antibiotic course and fluid restriction"}, {"id": "c", "text": "A single-dose antibiotic and NSAIDs for pain"}, {"id": "d", "text": "Antibiotics for 4–6 weeks, fluids, and NSAIDs"}]'::jsonb, '["d"]', 'Prostatitis is treated with a long course of antibiotics (4–6 weeks), fluids, and NSAIDs for pain. A short or single-dose course and fluid restriction contradict this plan, and surgical detorsion within 6h is the treatment for testicular torsion.', false),
  ('complications', 41, 'A client with prostatitis is on day 9 of an antibiotic, and his fever and chills went away several days ago. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"Antibiotics can stop once my fever and chills are gone.\""}, {"id": "b", "text": "\"I will keep drinking plenty of fluids each day.\""}, {"id": "c", "text": "\"I can take an NSAID if the pelvic pain comes back.\""}, {"id": "d", "text": "\"This antibiotic course will last 4 to 6 weeks.\""}]'::jsonb, '["a"]', 'Prostatitis requires a long antibiotic course of 4–6 weeks, so stopping on day 9 because the fever resolved is incorrect. Fluids and NSAIDs for pain are part of the treatment plan.', false),
  ('complications', 42, 'A nurse on a women''s health unit reviews the findings for five pregnant clients. For which clients does the nurse anticipate a D&C as the NEXT step in treatment? Select all that apply.', '[{"id": "a", "text": "7 weeks; unruptured ectopic; stable vitals"}, {"id": "b", "text": "32 weeks; placenta over the cervix"}, {"id": "c", "text": "11 weeks; some tissue expelled, some retained"}, {"id": "d", "text": "8 weeks; bleeding with a closed cervix"}, {"id": "e", "text": "12 weeks; snowstorm pattern on ultrasound"}]'::jsonb, '["c", "e"]', '(c) Correct: incomplete miscarriage (some tissue retained) may need a D&C. (e) Correct: a snowstorm pattern indicates molar pregnancy, treated with a D&C to remove uterine contents. (d) Wrong: bleeding with a closed cervix is threatened, and the pregnancy may continue. (a) Wrong: an unruptured ectopic is treated with methotrexate. (b) Wrong: placenta previa is managed with fetal heart rate monitoring and a planned C-section.', true),
  ('complications', 43, 'A 56-year-old client comes to the clinic reporting 4 days of discomfort "down there." Which findings would the nurse expect if the cause is prostatitis? Select all that apply.', '[{"id": "a", "text": "Fever and chills"}, {"id": "b", "text": "Painful ejaculation"}, {"id": "c", "text": "Low back/pelvic pain"}, {"id": "d", "text": "Painful urination"}, {"id": "e", "text": "Absent cremasteric reflex"}]'::jsonb, '["a", "b", "c", "d"]', '(a), (b), (c), (d) Correct: prostatitis causes painful urination, low back/pelvic pain, fever and chills, and painful ejaculation. (e) Wrong: an absent cremasteric reflex is a sign of testicular torsion.', true),
  ('complications', 44, 'A client at 10 weeks of pregnancy has extreme nausea and vomiting, vaginal bleeding, and a uterus larger than expected for dates. Her hCG is markedly elevated. Which ultrasound result would the nurse recognize as an expected finding for the MOST likely complication?', '[{"id": "a", "text": "A fetal heartbeat with a closed cervix"}, {"id": "b", "text": "A fetus that died but was not expelled"}, {"id": "c", "text": "A \"snowstorm\" pattern with no viable fetus"}, {"id": "d", "text": "A pregnancy implanted in the fallopian tube"}]'::jsonb, '["c"]', 'Bleeding, a uterus larger than expected for dates, hyperemesis, and markedly elevated hCG indicate molar pregnancy, which shows a snowstorm pattern on ultrasound and has no viable fetus. A fetus that died but was not expelled is a missed miscarriage, which has no symptoms.', false),
  ('complications', 45, 'Ultrasound confirms a molar pregnancy in a client at 11 weeks who has been vomiting for several days. Her vital signs are stable. Which treatment should the nurse anticipate as the PRIORITY?', '[{"id": "a", "text": "Methotrexate to stop cell division"}, {"id": "b", "text": "A D&C to remove the uterine contents"}, {"id": "c", "text": "Bed rest and fetal heart rate monitoring"}, {"id": "d", "text": "An emergency C-section delivery"}]'::jsonb, '["b"]', 'Molar pregnancy is treated with a D&C to remove the uterine contents, followed by weekly hCG monitoring. Methotrexate may be used later only for persistent gestational trophoblastic disease, and bed rest with fetal heart rate monitoring is previa management.', false),
  ('complications', 46, 'A client is being discharged after a D&C for a molar pregnancy. Which statements by the client indicate understanding of the follow-up teaching? Select all that apply.', '[{"id": "a", "text": "\"A plateau or rise in hCG means malignancy risk.\""}, {"id": "b", "text": "\"We can try to get pregnant again next month.\""}, {"id": "c", "text": "\"I''ll use contraception while my hCG is monitored.\""}, {"id": "d", "text": "\"Once my hCG drops by half, I can stop testing.\""}, {"id": "e", "text": "\"I''ll have my hCG checked weekly until it is zero.\""}]'::jsonb, '["a", "c", "e"]', '(e) Correct: hCG is monitored weekly until zero. (a) Correct: any plateau or rise means malignancy risk. (c) Correct: contraception is used during monitoring. (b) Wrong: pregnancy should be avoided for 6–12 months. (d) Wrong: monitoring continues until hCG reaches zero, not until it drops by half.', true),
  ('complications', 47, 'A client is having weekly hCG levels drawn after a D&C for a molar pregnancy. Her results over the past 4 weeks were 9,400, then 2,100, then 1,180, then 1,190 mIU/mL. Which action by the nurse is MOST appropriate?', '[{"id": "a", "text": "Tell her the steady decline shows treatment is done"}, {"id": "b", "text": "Reduce hCG checks to monthly since levels are low"}, {"id": "c", "text": "Advise her it is now safe to plan another pregnancy"}, {"id": "d", "text": "Report the plateau, which signals malignancy risk"}]'::jsonb, '["d"]', 'hCG must be monitored to zero, and any plateau or rise means malignancy risk (possible choriocarcinoma); 1,180 to 1,190 is a plateau, not a decline. Reducing checks or planning pregnancy is unsafe because pregnancy should be avoided for 6–12 months.', false),
  ('complications', 48, 'Two weeks after a D&C for a molar pregnancy, a client whose hCG is falling steadily says, "We want to try for another baby as soon as my level hits zero." Which response by the nurse is BEST?', '[{"id": "a", "text": "\"Use contraception and avoid pregnancy for 6–12 months.\""}, {"id": "b", "text": "\"That is fine; pregnancy is safe once the hCG is zero.\""}, {"id": "c", "text": "\"Wait 20 weeks, and then a new pregnancy is safe to try.\""}, {"id": "d", "text": "\"Contraception is needed only until your next hCG check.\""}]'::jsonb, '["a"]', 'After molar pregnancy, the client uses contraception during monitoring and avoids pregnancy for 6–12 months. Reaching zero does not end this period, and 20 weeks is the miscarriage cutoff, not the waiting time.', false),
  ('complications', 49, 'A client''s hCG has stayed above zero for several weeks after a D&C for a molar pregnancy, and the provider prescribes methotrexate. The client says, "I thought that drug was for ectopic pregnancy." Which response by the nurse is BEST?', '[{"id": "a", "text": "\"It helps the uterus finish expelling the tissue.\""}, {"id": "b", "text": "\"It is given to prevent a fallopian tube rupture.\""}, {"id": "c", "text": "\"It may be used for persistent trophoblastic disease.\""}, {"id": "d", "text": "\"It replaces the need for further weekly hCG checks.\""}]'::jsonb, '["c"]', 'Persistent hCG after a molar D&C means possible malignant transformation, and methotrexate may be used for persistent gestational trophoblastic disease. hCG monitoring to zero must continue, and preventing tube rupture applies to ectopic pregnancy.', false),
  ('complications', 50, 'A nurse on a medical-surgical unit receives report on four clients. Which client should the nurse see FIRST?', '[{"id": "a", "text": "After D&C for molar pregnancy; asking about contraception"}, {"id": "b", "text": "Unruptured ectopic on methotrexate; new shoulder pain"}, {"id": "c", "text": "Prostatitis on day 3 of antibiotics; mild pelvic pain"}, {"id": "d", "text": "Missed miscarriage awaiting D&C; tearful, no bleeding"}]'::jsonb, '["b"]', 'New shoulder pain in a client with an ectopic pregnancy is referred pain from diaphragm irritation by blood, suggesting rupture and internal hemorrhage — an emergency. The other clients need teaching, comfort, or emotional support but are not unstable.', false),
  ('bph', 1, 'A 64-year-old client reports trouble starting urination, a weak stream with dribbling, and waking three times a night to urinate. The DRE reveals a smooth, enlarged prostate. Which condition does the nurse MOST likely suspect?', '[{"id": "a", "text": "Prostate cancer that may metastasize to other organs"}, {"id": "b", "text": "Urinary tract infection causing frequency and urgency"}, {"id": "c", "text": "Benign prostatic hyperplasia compressing the urethra"}, {"id": "d", "text": "Urinary retention caused by a hard, nodular prostate"}]'::jsonb, '["c"]', 'Weak stream, hesitancy and nocturia with a smooth, enlarged prostate on DRE fit BPH, in which the enlarging prostate compresses the urethra. Prostate cancer causes similar urinary symptoms but presents with a hard, nodular prostate on DRE.', false),
  ('bph', 2, 'During a DRE on a 70-year-old client who reports hesitancy and nocturia, the provider palpates a hard, nodular prostate. The client''s PSA result is markedly elevated. Which test does the nurse anticipate NEXT to confirm the cause?', '[{"id": "a", "text": "Biopsy of the prostate"}, {"id": "b", "text": "Uroflowmetry to measure urine flow rate"}, {"id": "c", "text": "Post-void residual ultrasound of the bladder"}, {"id": "d", "text": "Urinalysis to rule out infection"}]'::jsonb, '["a"]', 'A hard, nodular prostate and a markedly elevated PSA suggest prostate cancer, and a biopsy is required to confirm cancer. Uroflowmetry, post-void residual ultrasound and urinalysis evaluate urinary symptoms but cannot confirm cancer.', false),
  ('bph', 3, 'A 58-year-old client is being evaluated in a urology clinic. Which statements made by the client describe symptoms consistent with BPH? Select all that apply.', '[{"id": "a", "text": "\"I have trouble starting urination.\""}, {"id": "b", "text": "\"My doctor felt a hard, nodular prostate.\""}, {"id": "c", "text": "\"I keep leaking a little after urination.\""}, {"id": "d", "text": "\"My bladder feels full after voiding.\""}, {"id": "e", "text": "\"I wake at night to urinate.\""}]'::jsonb, '["a", "c", "d", "e"]', 'Trouble starting urination (hesitancy), leaking after urination (dribbling), a bladder that feels full after voiding (incomplete emptying) and waking at night to urinate (nocturia) are all BPH symptoms. A hard, nodular prostate is a DRE finding that suggests prostate cancer, not BPH, in which the prostate is smooth and enlarged.', true),
  ('bph', 4, 'A 61-year-old client with nocturia and a weak stream has a smooth, enlarged prostate on DRE and a mildly elevated PSA. He asks, "Does a high PSA mean I have cancer?" Which response by the nurse is BEST?', '[{"id": "a", "text": "A raised PSA confirms prostate cancer, so no biopsy will be needed."}, {"id": "b", "text": "PSA is markedly elevated in BPH, so your result is not a concern."}, {"id": "c", "text": "PSA stays normal in BPH, so any rise in it points to cancer."}, {"id": "d", "text": "PSA is elevated in both BPH and cancer; a biopsy confirms cancer."}]'::jsonb, '["d"]', 'PSA is mildly elevated in BPH and markedly elevated in cancer, so an elevated PSA alone does not diagnose cancer; a biopsy confirms cancer. Saying PSA is markedly elevated in BPH reverses the note''s comparison.', false),
  ('bph', 5, 'A 76-year-old client with BPH is starting tamsulosin (Flomax). He lives alone and gets up several times each night to use the bathroom. Which teaching point is MOST important for the nurse to include?', '[{"id": "a", "text": "Expect at least 6 months before any improvement in urine flow is noticed."}, {"id": "b", "text": "Orthostatic hypotension and dizziness may occur when waking to urinate."}, {"id": "c", "text": "Report decreased libido, which is the main side effect of this medication."}, {"id": "d", "text": "The medication shrinks the prostate by blocking testosterone conversion."}]'::jsonb, '["b"]', 'Alpha-blockers such as tamsulosin cause orthostatic hypotension and dizziness, a safety concern for an older client who gets up at night to void. The 6-month onset, prostate shrinkage and decreased libido describe 5-alpha-reductase inhibitors such as finasteride.', false),
  ('bph', 6, 'A 65-year-old client has been prescribed finasteride (Proscar) for BPH. Which statements by the client indicate understanding of this medication? Select all that apply.', '[{"id": "a", "text": "\"It works by relaxing smooth muscle in my urethra.\""}, {"id": "b", "text": "\"It shrinks my prostate by blocking testosterone conversion.\""}, {"id": "c", "text": "\"I may not see an effect for 6 months or longer.\""}, {"id": "d", "text": "\"I should report orthostatic hypotension as its main effect.\""}, {"id": "e", "text": "\"It can cause decreased libido or erectile dysfunction.\""}]'::jsonb, '["b", "c", "e"]', 'Finasteride shrinks the prostate by blocking testosterone conversion, takes 6+ months to see effect, and can cause decreased libido and erectile dysfunction. Relaxing smooth muscle in the prostate/urethra and orthostatic hypotension describe alpha-blockers such as tamsulosin and doxazosin, not finasteride.', true),
  ('bph', 7, 'A 66-year-old client started finasteride (Proscar) 2 months ago. He states, "My stream is still weak, so this pill isn''t working. I''m going to stop taking it." Which response by the nurse is BEST?', '[{"id": "a", "text": "Finasteride should have relaxed your urethra within a few days."}, {"id": "b", "text": "Finasteride takes 6+ months to see its effect on the prostate."}, {"id": "c", "text": "A weak stream at 2 months means the prostate has become cancerous."}, {"id": "d", "text": "Stopping is reasonable since the drug is meant to relax smooth muscle."}]'::jsonb, '["b"]', 'Finasteride shrinks the prostate but takes 6+ months to see effect, so a weak stream at 2 months does not mean treatment failure. Relaxing smooth muscle in the urethra is the action of alpha-blockers such as tamsulosin, not finasteride.', false),
  ('bph', 8, 'A 72-year-old client with BPH takes doxazosin and dutasteride. Since starting therapy, he reports feeling lightheaded each time he stands up from his recliner. The nurse recognizes which as the MOST likely cause?', '[{"id": "a", "text": "Orthostatic hypotension from dutasteride"}, {"id": "b", "text": "Prostate shrinkage from dutasteride"}, {"id": "c", "text": "Urinary retention from untreated BPH"}, {"id": "d", "text": "Orthostatic hypotension from doxazosin"}]'::jsonb, '["d"]', 'Doxazosin is an alpha-blocker whose side effects are orthostatic hypotension and dizziness. Dutasteride is a 5-alpha-reductase inhibitor whose side effects are decreased libido and erectile dysfunction, not orthostatic hypotension.', false),
  ('bph', 9, 'A 47-year-old client asks about his risk for BPH. His history: BMI in the obese range, a desk job with no regular exercise, a father treated for BPH, and a weak stream with dribbling for 2 months. Which findings are risk factors for BPH? Select all that apply.', '[{"id": "a", "text": "Obesity"}, {"id": "b", "text": "Age of 47 years"}, {"id": "c", "text": "Sedentary lifestyle"}, {"id": "d", "text": "Family history of BPH"}, {"id": "e", "text": "Weak stream with dribbling"}]'::jsonb, '["a", "c", "d"]', 'Obesity, a sedentary lifestyle and a family history are listed risk factors for BPH. Age is a risk factor only for men over 50, so 47 years does not qualify. A weak stream with dribbling is a symptom of BPH, not a risk factor.', true),
  ('bph', 10, 'A nurse at a community health fair reviews the histories of four men who report no urinary symptoms. Which client has the MOST risk factors for developing BPH?', '[{"id": "a", "text": "A 56-year-old with obesity, a sedentary lifestyle, and family history"}, {"id": "b", "text": "A 44-year-old with obesity, a sedentary lifestyle, and family history"}, {"id": "c", "text": "A 58-year-old runner of normal weight with no family history of BPH"}, {"id": "d", "text": "A 52-year-old with an active job and no family history of prostate disease"}]'::jsonb, '["a"]', 'Men over 50 with a family history, obesity and a sedentary lifestyle carry the most listed BPH risk factors. The 44-year-old shares the lifestyle and family factors but lacks the age factor of men over 50.', false),
  ('bph', 11, 'A 69-year-old client with BPH states, "Even right after I urinate, my bladder still feels full." The provider wants to know how much urine is left in the bladder. Which test does the nurse MOST likely anticipate?', '[{"id": "a", "text": "Uroflowmetry flow-rate study"}, {"id": "b", "text": "Prostate-specific antigen blood test"}, {"id": "c", "text": "Post-void residual ultrasound"}, {"id": "d", "text": "Digital rectal exam of the prostate"}]'::jsonb, '["c"]', 'A post-void residual ultrasound checks how much urine remains after voiding, which evaluates the client''s incomplete emptying. Uroflowmetry measures urine flow rate, not the volume left behind.', false),
  ('bph', 12, 'A 63-year-old client is scheduled for a BPH work-up. The nurse explains the purpose of each test. Which explanations are accurate? Select all that apply.', '[{"id": "a", "text": "Uroflowmetry measures how much urine remains after voiding."}, {"id": "b", "text": "Urinalysis rules out infection as a cause of the symptoms."}, {"id": "c", "text": "Post-void residual ultrasound checks urine left after voiding."}, {"id": "d", "text": "PSA is a blood test that confirms cancer without a biopsy."}, {"id": "e", "text": "DRE palpates the prostate for size and consistency."}]'::jsonb, '["b", "c", "e"]', 'Urinalysis rules out infection, post-void residual ultrasound checks how much urine remains after voiding, and DRE palpates the prostate for size and consistency. Uroflowmetry measures urine flow rate, not residual urine. PSA is elevated in both BPH and cancer, so a biopsy, not PSA, confirms cancer.', true),
  ('bph', 13, 'A 59-year-old client with BPH describes a weak stream that has slowly worsened over the past year. The provider wants objective data on how fast his urine flows. Which test BEST provides this information?', '[{"id": "a", "text": "Uroflowmetry"}, {"id": "b", "text": "Post-void residual ultrasound"}, {"id": "c", "text": "Digital rectal exam"}, {"id": "d", "text": "Urinalysis"}]'::jsonb, '["a"]', 'Uroflowmetry measures urine flow rate, which objectively evaluates a weak stream. A post-void residual ultrasound measures how much urine remains after voiding, not the flow rate.', false),
  ('bph', 14, 'A 63-year-old client reports new urinary frequency and urgency. The provider suspects BPH but wants to exclude another cause of these symptoms before starting medication. Which test does the nurse anticipate FIRST?', '[{"id": "a", "text": "Uroflowmetry to measure urine flow rate"}, {"id": "b", "text": "PSA to confirm the diagnosis of BPH"}, {"id": "c", "text": "Post-void residual ultrasound for emptying"}, {"id": "d", "text": "Urinalysis to rule out infection"}]'::jsonb, '["d"]', 'Urinalysis rules out infection, which excludes another cause of frequency and urgency. PSA does not confirm BPH because it is elevated in both BPH and cancer; BPH is confirmed clinically with symptoms.', false),
  ('bph', 15, 'A 62-year-old client has hesitancy and nocturia. Which findings in his work-up support BPH rather than prostate cancer? Select all that apply.', '[{"id": "a", "text": "Hard, nodular prostate on DRE"}, {"id": "b", "text": "Smooth, enlarged prostate on DRE"}, {"id": "c", "text": "Markedly elevated PSA level"}, {"id": "d", "text": "Mildly elevated PSA level"}, {"id": "e", "text": "Hesitancy, weak stream, and nocturia"}]'::jsonb, '["b", "d"]', 'A smooth, enlarged prostate and a mildly elevated PSA are BPH findings. A hard, nodular prostate and a markedly elevated PSA point to prostate cancer. Hesitancy, weak stream and nocturia occur in both conditions, so they do not distinguish BPH from cancer.', true),
  ('bph', 16, 'The nurse reviews phone messages left by four clients being treated for BPH. Which message requires IMMEDIATE follow-up?', '[{"id": "a", "text": "Decreased libido 3 months after starting finasteride"}, {"id": "b", "text": "Mild dizziness on standing after first dose of doxazosin"}, {"id": "c", "text": "Cannot start urination since last night despite feeling full"}, {"id": "d", "text": "Weak stream that is slowly improving since starting tamsulosin"}]'::jsonb, '["c"]', 'Inability to void with a full bladder suggests urinary retention, a key complication of BPH. Decreased libido with finasteride and dizziness with doxazosin are listed side effects, and an improving stream shows the alpha-blocker is working.', false),
  ('bph', 17, 'The nurse reviews DRE documentation for four clients evaluated for urinary hesitancy. Which finding should the nurse report to the health care provider as MOST concerning for cancer?', '[{"id": "a", "text": "Smooth, enlarged prostate"}, {"id": "b", "text": "Hard, nodular prostate"}, {"id": "c", "text": "Enlarged prostate with weak stream"}, {"id": "d", "text": "Mildly elevated PSA with nocturia"}]'::jsonb, '["b"]', 'A hard, nodular prostate on DRE raises suspicion of prostate cancer, because nodules suggest cancer. A smooth, enlarged prostate and a mildly elevated PSA are typical of BPH.', false),
  ('bph', 18, 'A 68-year-old client is starting tamsulosin (Flomax) for BPH. Which statements by the client indicate a need for further teaching? Select all that apply.', '[{"id": "a", "text": "\"It relaxes smooth muscle in my prostate and urethra.\""}, {"id": "b", "text": "\"It will shrink my prostate over about 6 months.\""}, {"id": "c", "text": "\"I might feel dizzy when I stand up.\""}, {"id": "d", "text": "\"Decreased libido is its main side effect.\""}, {"id": "e", "text": "\"It should improve my urine flow.\""}]'::jsonb, '["b", "d"]', 'Statements that tamsulosin shrinks the prostate over 6 months and that decreased libido is its main side effect need correction; those describe 5-alpha-reductase inhibitors such as finasteride. Tamsulosin correctly relaxes smooth muscle in the prostate/urethra to improve urine flow, and dizziness with orthostatic hypotension is its side effect.', true),
  ('bph', 19, 'A 67-year-old client with BPH asks how his new prescription for tamsulosin will help him void, since his provider said the drug will not make his prostate smaller. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "It shrinks the prostate by blocking testosterone conversion over 6 months."}, {"id": "b", "text": "It removes the excess prostate tissue that compresses the urethra."}, {"id": "c", "text": "It treats the infection that is causing the hesitancy and frequency."}, {"id": "d", "text": "It relaxes smooth muscle in the prostate/urethra to improve urine flow."}]'::jsonb, '["d"]', 'Alpha-blockers such as tamsulosin relax smooth muscle in the prostate/urethra, improving urine flow without shrinking the prostate. Blocking testosterone conversion to shrink the prostate is the action of finasteride and dutasteride.', false),
  ('bph', 20, 'A 71-year-old client has taken tamsulosin and finasteride for more than a year. He still has hesitancy, a weak stream, and incomplete emptying. Which treatment does the nurse anticipate the provider will discuss NEXT?', '[{"id": "a", "text": "A prostate biopsy to confirm that the enlargement is benign"}, {"id": "b", "text": "TURP, the most common surgery for BPH refractory to medication"}, {"id": "c", "text": "Adding doxazosin to shrink the prostate over the next 6 months"}, {"id": "d", "text": "Waiting 6 more months for finasteride to begin its effect"}]'::jsonb, '["b"]', 'TURP is the most common surgical treatment for BPH refractory to medication, as in this client after more than a year of therapy. Doxazosin is an alpha-blocker that relaxes smooth muscle, not a drug that shrinks the prostate, and finasteride''s 6+ month onset has already passed.', false),
  ('bph', 21, 'A 60-year-old client asks the nurse which of his prescribed medications could explain his new decreased libido. His list includes tamsulosin, doxazosin, finasteride, dutasteride, and Flomax from an old prescription. Which medications could cause this effect? Select all that apply.', '[{"id": "a", "text": "Tamsulosin"}, {"id": "b", "text": "Finasteride"}, {"id": "c", "text": "Doxazosin"}, {"id": "d", "text": "Dutasteride"}, {"id": "e", "text": "Flomax"}]'::jsonb, '["b", "d"]', 'Finasteride and dutasteride are 5-alpha-reductase inhibitors whose side effects are decreased libido and erectile dysfunction. Tamsulosin (Flomax) and doxazosin are alpha-blockers whose side effects are orthostatic hypotension and dizziness.', true),
  ('bph', 22, 'A 60-year-old client with new hesitancy, a weak stream, and nocturia says, "My brother had prostate cancer with these exact symptoms, so I must have cancer too." Which response by the nurse is BEST?', '[{"id": "a", "text": "These urinary symptoms occur in both BPH and prostate cancer."}, {"id": "b", "text": "These symptoms occur only with cancer, so a biopsy is the next step."}, {"id": "c", "text": "These symptoms rule out cancer, which does not cause urinary problems."}, {"id": "d", "text": "Family history raises cancer risk only and does not affect BPH risk."}]'::jsonb, '["a"]', 'Hesitancy, weak stream and nocturia occur in BPH, and prostate cancer has similar symptoms, so symptoms alone cannot tell them apart. Family history is also a listed BPH risk factor, so the last distractor is incorrect.', false),
  ('bph', 23, 'A 57-year-old client newly diagnosed with BPH asks, "Why would a bigger prostate make it hard for me to urinate?" Which response by the nurse BEST explains the cause of his symptoms?', '[{"id": "a", "text": "The enlarged prostate presses on the kidneys and lowers their urine production."}, {"id": "b", "text": "The prostate releases hormones that weaken the muscle of the bladder."}, {"id": "c", "text": "The prostate surrounds the urethra, so as it grows it compresses the urethra."}, {"id": "d", "text": "The enlarged prostate spreads to the bladder and blocks the outlet."}]'::jsonb, '["c"]', 'The prostate surrounds the urethra, so when it grows it compresses the urethra and causes urinary symptoms. Spreading to other organs describes malignant prostate cancer, not non-cancerous BPH.', false),
  ('bph', 24, 'A 66-year-old client has a hard, nodular prostate on DRE and a markedly elevated PSA. He asks what these results mean. Which statements by the nurse are accurate? Select all that apply.', '[{"id": "a", "text": "\"These findings raise suspicion of prostate cancer.\""}, {"id": "b", "text": "\"A biopsy is required to confirm cancer.\""}, {"id": "c", "text": "\"Prostate cancer is malignant and may metastasize.\""}, {"id": "d", "text": "\"These findings are typical of benign prostate growth.\""}, {"id": "e", "text": "\"Your symptoms alone are enough to confirm the diagnosis.\""}]'::jsonb, '["a", "b", "c"]', 'A hard, nodular prostate and a markedly elevated PSA suggest prostate cancer, which is malignant and may metastasize, and a biopsy is required for confirmation. BPH typically shows a smooth, enlarged prostate with a mildly elevated PSA. Confirmation by clinical findings and symptoms applies to BPH, not cancer.', true),
  ('bph', 25, 'A 64-year-old client has taken finasteride for 5 months and reports decreased libido and erectile dysfunction. His urinary symptoms are slowly improving. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "These are signs of orthostatic hypotension caused by finasteride."}, {"id": "b", "text": "These are side effects of finasteride to discuss with the provider."}, {"id": "c", "text": "These are signs that the enlarged prostate has become malignant."}, {"id": "d", "text": "These are effects of smooth muscle relaxation in the urethra."}]'::jsonb, '["b"]', 'Decreased libido and erectile dysfunction are side effects of 5-alpha-reductase inhibitors such as finasteride. Orthostatic hypotension and smooth muscle relaxation relate to alpha-blockers, not finasteride.', false),
  ('bph', 26, 'A 62-year-old client with nocturia and hesitancy is scheduled for a DRE and asks what the provider is checking during the exam. Which response by the nurse is MOST accurate?', '[{"id": "a", "text": "How much urine remains in the bladder after you finish voiding."}, {"id": "b", "text": "How fast your urine flows when you urinate into a special device."}, {"id": "c", "text": "The size and consistency of the prostate; nodules suggest cancer."}, {"id": "d", "text": "Whether an infection is present anywhere in the urinary tract."}]'::jsonb, '["c"]', 'A DRE palpates the prostate for size and consistency, and nodules raise suspicion of cancer. Residual urine is measured by post-void residual ultrasound and flow rate by uroflowmetry.', false),
  ('bph', 27, 'A nurse in a urology clinic reviews the work-up results for five clients with urinary symptoms. Which client findings raise suspicion of prostate cancer and require follow-up? Select all that apply.', '[{"id": "a", "text": "A 68-year-old with nodules palpated on DRE"}, {"id": "b", "text": "A 59-year-old with a smooth, enlarged prostate"}, {"id": "c", "text": "A 72-year-old with a markedly elevated PSA"}, {"id": "d", "text": "A 64-year-old with a hard, nodular prostate"}, {"id": "e", "text": "A 61-year-old with a mildly elevated PSA"}]'::jsonb, '["a", "c", "d"]', 'Nodules on DRE, a hard nodular prostate and a markedly elevated PSA all point to possible prostate cancer. A smooth, enlarged prostate and a mildly elevated PSA are typical BPH findings.', true),
  ('bph', 28, 'A 74-year-old client with BPH reports nocturia four times nightly and says his bladder feels full after voiding. A post-void residual ultrasound shows a large volume of urine remaining. The nurse monitors MOST closely for which key complication?', '[{"id": "a", "text": "Urinary retention"}, {"id": "b", "text": "Metastasis to other organs"}, {"id": "c", "text": "Orthostatic hypotension"}, {"id": "d", "text": "Erectile dysfunction"}]'::jsonb, '["a"]', 'Incomplete emptying with urine remaining after voiding places this client at risk for urinary retention, a key complication of BPH. Metastasis relates to prostate cancer, and orthostatic hypotension and erectile dysfunction are medication side effects.', false),
  ('bph', 29, 'A 69-year-old client has taken finasteride (Proscar) for 8 months and now reports a stronger stream and less nocturia. Which interpretation of this change by the nurse is MOST accurate?', '[{"id": "a", "text": "The drug has relaxed smooth muscle in the urethra within days."}, {"id": "b", "text": "The prostate has stopped growing because the BPH became cancer."}, {"id": "c", "text": "The improvement is caused by orthostatic hypotension lowering pressure."}, {"id": "d", "text": "The drug has shrunk the prostate, an effect that takes 6+ months."}]'::jsonb, '["d"]', 'Finasteride shrinks the prostate by blocking testosterone conversion and takes 6+ months to see effect, which matches improvement at 8 months. Relaxing smooth muscle in the urethra is how alpha-blockers such as tamsulosin work.', false),
  ('bph', 30, 'A 57-year-old client was just told he has BPH. Which statements by the nurse are accurate when teaching him about the condition? Select all that apply.', '[{"id": "a", "text": "\"BPH is a non-cancerous enlargement of the prostate.\""}, {"id": "b", "text": "\"Like cancer, BPH may metastasize to other organs.\""}, {"id": "c", "text": "\"The enlarging prostate compresses the urethra.\""}, {"id": "d", "text": "\"TURP is the most common surgery if medication fails.\""}, {"id": "e", "text": "\"Urinary retention is a key complication to watch for.\""}]'::jsonb, '["a", "c", "d", "e"]', 'BPH is non-cancerous enlargement of the prostate that compresses the urethra; urinary retention is a key complication, and TURP is the most common surgical treatment for BPH refractory to medication. Metastasis describes malignant prostate cancer, not BPH.', true),
  ('bph', 31, 'After teaching, a 58-year-old client newly diagnosed with BPH makes several statements about his condition. Which statement by the client indicates understanding?', '[{"id": "a", "text": "\"My prostate enlargement is non-cancerous, but it compresses my urethra.\""}, {"id": "b", "text": "\"BPH can metastasize, so I will need scans of my bones every year.\""}, {"id": "c", "text": "\"A biopsy is required to confirm that my diagnosis is really BPH.\""}, {"id": "d", "text": "\"A hard, nodular prostate is the usual exam finding in BPH.\""}]'::jsonb, '["a"]', 'BPH is non-cancerous enlargement of the prostate that compresses the urethra. BPH is confirmed by clinical findings and symptoms, whereas a biopsy is required to confirm cancer.', false),
  ('bph', 32, 'During an admission interview, a 66-year-old client says, "I stand at the toilet for a long time before anything comes out." Which BPH symptom should the nurse document as the BEST description of this report?', '[{"id": "a", "text": "Dribbling"}, {"id": "b", "text": "Urgency"}, {"id": "c", "text": "Urinary hesitancy"}, {"id": "d", "text": "Incomplete emptying"}]'::jsonb, '["c"]', 'Urinary hesitancy means trouble starting urination, which matches the client''s report. Dribbling is leaking after urination, and incomplete emptying is a bladder that feels full after voiding.', false),
  ('bph', 33, 'A nurse reviews a 64-year-old client''s description of his urinary symptoms. Which client statements are correctly matched with the BPH symptom they describe? Select all that apply.', '[{"id": "a", "text": "\"I leak a little after I finish\" — dribbling"}, {"id": "b", "text": "\"I have trouble starting to urinate\" — urgency"}, {"id": "c", "text": "\"I wake twice at night to urinate\" — nocturia"}, {"id": "d", "text": "\"I need to urinate more often\" — nocturia"}, {"id": "e", "text": "\"I feel full after voiding\" — incomplete emptying"}]'::jsonb, '["a", "c", "e"]', 'Leaking after urination is dribbling, waking at night to urinate is nocturia, and a bladder that feels full after voiding is incomplete emptying. Trouble starting urination is hesitancy, not urgency, and needing to urinate more often is frequency, not nocturia.', true),
  ('bph', 34, 'A 63-year-old client takes finasteride and was just prescribed tamsulosin as well. He asks why he needs a second drug for the same problem. Which response by the nurse is BEST?', '[{"id": "a", "text": "Tamsulosin speeds up how quickly finasteride is able to shrink the prostate gland."}, {"id": "b", "text": "Tamsulosin improves urine flow; finasteride takes 6+ months to shrink the prostate."}, {"id": "c", "text": "Both drugs block testosterone conversion, so together the shrinking effect is doubled."}, {"id": "d", "text": "Tamsulosin prevents the decreased libido that finasteride can cause."}]'::jsonb, '["b"]', 'Alpha-blockers relax smooth muscle in the prostate/urethra to improve urine flow, whereas finasteride shrinks the prostate but takes 6+ months to see effect. Blocking testosterone conversion is the action of finasteride and dutasteride only.', false),
  ('bph', 35, 'A 61-year-old client is concerned about his risk for BPH and wants to know what he can change. His history includes obesity, a sedentary lifestyle, a family history of BPH, and age over 50. Which risk factors should the nurse BEST target in teaching?', '[{"id": "a", "text": "Family history and age over 50"}, {"id": "b", "text": "Age over 50 and obesity"}, {"id": "c", "text": "Family history and sedentary lifestyle"}, {"id": "d", "text": "Obesity and sedentary lifestyle"}]'::jsonb, '["d"]', 'Of the listed BPH risk factors, obesity and a sedentary lifestyle can be changed by the client. Age over 50 and family history are risk factors that cannot be changed.', false),
  ('bph', 36, 'A 70-year-old client starting doxazosin for BPH asks what side effects to watch for. Which effects should the nurse include in the teaching? Select all that apply.', '[{"id": "a", "text": "Decreased libido"}, {"id": "b", "text": "Orthostatic hypotension"}, {"id": "c", "text": "Erectile dysfunction"}, {"id": "d", "text": "Dizziness"}, {"id": "e", "text": "Prostate shrinkage"}]'::jsonb, '["b", "d"]', 'Doxazosin is an alpha-blocker; its side effects are orthostatic hypotension and dizziness. Decreased libido and erectile dysfunction are side effects of 5-alpha-reductase inhibitors, and shrinking the prostate is their therapeutic action, not an effect of doxazosin.', true),
  ('bph', 37, 'A nurse reviews the record of a 67-year-old client on a urology unit. The PSA is mildly elevated, but the DRE notes several nodules on the prostate. Which finding is MOST important for the nurse to discuss with the provider?', '[{"id": "a", "text": "The mildly elevated PSA, which confirms cancer"}, {"id": "b", "text": "The mildly elevated PSA, which rules out BPH"}, {"id": "c", "text": "The nodules, which confirm a diagnosis of BPH"}, {"id": "d", "text": "The prostate nodules, which raise suspicion of cancer"}]'::jsonb, '["d"]', 'On DRE, nodules suggest cancer even when the PSA is only mildly elevated, because a mildly elevated PSA is also seen in BPH. A PSA result does not confirm cancer; a biopsy confirms cancer.', false),
  ('bph', 38, 'A 72-year-old client with BPH has been taking doxazosin for 3 weeks. At follow-up, which finding BEST indicates the medication is having its intended effect?', '[{"id": "a", "text": "Improved urine flow when he voids"}, {"id": "b", "text": "Smaller prostate size on repeat DRE"}, {"id": "c", "text": "Decreased libido since starting it"}, {"id": "d", "text": "Dizziness when he stands up quickly"}]'::jsonb, '["a"]', 'Alpha-blockers such as doxazosin relax smooth muscle in the prostate/urethra, resulting in improved urine flow. Prostate shrinkage is the action of 5-alpha-reductase inhibitors, and dizziness is a side effect rather than the intended effect.', false),
  ('bph', 39, 'A 66-year-old client asks how his PSA result will be used. Which statements by the nurse about PSA are accurate? Select all that apply.', '[{"id": "a", "text": "\"PSA is a blood test.\""}, {"id": "b", "text": "\"PSA is mildly elevated in BPH.\""}, {"id": "c", "text": "\"PSA is markedly elevated in cancer.\""}, {"id": "d", "text": "\"A high PSA confirms cancer without a biopsy.\""}, {"id": "e", "text": "\"PSA can be elevated in both BPH and cancer.\""}]'::jsonb, '["a", "b", "c", "e"]', 'PSA is a blood test that is mildly elevated in BPH and markedly elevated in cancer, so it can be elevated in both conditions. A biopsy, not PSA, confirms cancer.', true),
  ('bph', 40, 'A 68-year-old client with BPH is reviewed for the expected finding on DRE. He has hesitancy, a weak stream, nocturia, and a mildly elevated PSA. Which DRE finding does the nurse expect?', '[{"id": "a", "text": "Hard, nodular prostate"}, {"id": "b", "text": "Smooth, enlarged prostate"}, {"id": "c", "text": "Enlarged prostate with nodules"}, {"id": "d", "text": "Hard prostate of normal size"}]'::jsonb, '["b"]', 'BPH produces a smooth, enlarged prostate on DRE. A hard or nodular prostate suggests prostate cancer.', false),
  ('bph', 41, 'A 65-year-old client asks why his provider ordered a PSA and a DRE when his urinary symptoms already suggest BPH. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "The PSA and DRE are the only tests that can confirm a diagnosis of BPH in men."}, {"id": "b", "text": "The PSA measures how much urine remains in the bladder after voiding."}, {"id": "c", "text": "Prostate cancer has similar symptoms; these tests help tell BPH from cancer."}, {"id": "d", "text": "The DRE measures the urine flow rate to grade the severity of BPH."}]'::jsonb, '["c"]', 'Prostate cancer causes urinary symptoms similar to BPH, and DRE (smooth vs hard, nodular) and PSA (mildly vs markedly elevated) help tell them apart. Residual urine is checked by post-void residual ultrasound and flow rate by uroflowmetry.', false),
  ('bph', 42, 'A 69-year-old client with BPH is on combination therapy with tamsulosin and dutasteride. Which client statements indicate a need for further teaching? Select all that apply.', '[{"id": "a", "text": "\"Dutasteride may take 6 months or more to work.\""}, {"id": "b", "text": "\"Tamsulosin is the drug that shrinks my prostate.\""}, {"id": "c", "text": "\"Tamsulosin can make me dizzy when I stand.\""}, {"id": "d", "text": "\"Dutasteride may lower my libido.\""}, {"id": "e", "text": "\"Dutasteride works by relaxing my urethra.\""}]'::jsonb, '["b", "e"]', 'Saying tamsulosin shrinks the prostate or that dutasteride relaxes the urethra reverses the two drug actions and needs correction: alpha-blockers such as tamsulosin relax smooth muscle, and 5-alpha-reductase inhibitors such as dutasteride shrink the prostate. Dutasteride''s 6+ month onset, decreased libido, and tamsulosin-related dizziness are correct.', true),
  ('bph', 43, 'A 67-year-old client with a weak stream asks whether a test can tell him if his enlarged prostate is benign. His DRE shows a smooth, enlarged prostate and his PSA is mildly elevated. Which statement by the nurse is MOST accurate about how BPH is confirmed?', '[{"id": "a", "text": "BPH is confirmed by a prostate biopsy in every case."}, {"id": "b", "text": "BPH is confirmed clinically together with the symptoms."}, {"id": "c", "text": "BPH is confirmed only by a markedly elevated PSA."}, {"id": "d", "text": "BPH is confirmed by a hard, nodular DRE finding."}]'::jsonb, '["b"]', 'BPH is confirmed by clinical findings plus symptoms, whereas a biopsy is required to confirm prostate cancer. A markedly elevated PSA and a hard, nodular prostate suggest cancer.', false),
  ('bph', 44, 'A 75-year-old client with BPH has had dribbling and a bladder that feels full after voiding for months. Today he calls and says, "Since this morning I have not been able to pass any urine, and my bladder feels very full." Which interpretation by the nurse is the PRIORITY?', '[{"id": "a", "text": "An expected BPH symptom of incomplete emptying"}, {"id": "b", "text": "A sign that his prostate has become malignant"}, {"id": "c", "text": "A side effect of a BPH drug such as tamsulosin"}, {"id": "d", "text": "Possible urinary retention, a key complication of BPH"}]'::jsonb, '["d"]', 'A new inability to void with a very full bladder signals urinary retention, a key complication of BPH, rather than the ongoing symptom of incomplete emptying. Malignancy is suggested by a hard, nodular prostate or markedly elevated PSA, not by retention.', false),
  ('bph', 45, 'A 64-year-old client with BPH reports hesitancy and a weak stream and wants faster symptom relief than his previous medication gave. Which drugs relax smooth muscle in the prostate and urethra rather than shrinking the prostate over 6+ months? Select all that apply.', '[{"id": "a", "text": "Doxazosin"}, {"id": "b", "text": "Finasteride"}, {"id": "c", "text": "Dutasteride"}, {"id": "d", "text": "Tamsulosin"}, {"id": "e", "text": "Proscar"}]'::jsonb, '["a", "d"]', 'Tamsulosin and doxazosin are alpha-blockers that relax smooth muscle in the prostate/urethra to improve urine flow. Finasteride (Proscar) and dutasteride shrink the prostate by blocking testosterone conversion and take 6+ months to see effect.', true),
  ('bph', 46, 'A 63-year-old client with BPH says he is embarrassed to describe his symptoms. After the nurse provides privacy, he says, "I have to go so often, and when I need to go, I have to go right away." Which symptom does the nurse MOST accurately document?', '[{"id": "a", "text": "Frequency and urgency"}, {"id": "b", "text": "Hesitancy and dribbling"}, {"id": "c", "text": "Nocturia and hesitancy"}, {"id": "d", "text": "Incomplete emptying"}]'::jsonb, '["a"]', 'Needing to urinate more often and urgently describes frequency and urgency. Hesitancy is trouble starting urination and dribbling is leaking after urination.', false),
  ('bph', 47, 'A 66-year-old client asks why he was told to watch for a full bladder and inability to void while waiting for his BPH medication to take effect. Which response by the nurse BEST explains this teaching?', '[{"id": "a", "text": "Inability to void is a side effect of finasteride."}, {"id": "b", "text": "A full bladder means the BPH has become malignant."}, {"id": "c", "text": "Urinary retention is a key complication of BPH."}, {"id": "d", "text": "Inability to void is caused by orthostatic hypotension."}]'::jsonb, '["c"]', 'Because the enlarged prostate compresses the urethra, urinary retention is a key complication of BPH. Finasteride''s side effects are decreased libido and erectile dysfunction, and orthostatic hypotension is an alpha-blocker side effect.', false),
  ('bph', 48, 'A 73-year-old client with BPH has completed a full medication trial. He continues to have hesitancy, a weak stream, and nocturia, and his provider recommends TURP. Which statements by the nurse about this plan are accurate? Select all that apply.', '[{"id": "a", "text": "\"TURP is the most common surgery for BPH.\""}, {"id": "b", "text": "\"TURP is used when BPH is refractory to medication.\""}, {"id": "c", "text": "\"TURP is chosen because a biopsy confirmed BPH.\""}, {"id": "d", "text": "\"TURP is used only after the prostate is hard and nodular.\""}, {"id": "e", "text": "\"Doxazosin will shrink the prostate instead of surgery.\""}]'::jsonb, '["a", "b"]', 'TURP is the most common surgical treatment for BPH refractory to medication, which fits this client. BPH is confirmed clinically with symptoms, not by biopsy; a hard, nodular prostate suggests cancer; and doxazosin relaxes smooth muscle rather than shrinking the prostate.', true),
  ('bph', 49, 'A 60-year-old client starting tamsulosin asks which side effect is MOST likely to affect his safety at home. Which side effect should the nurse identify?', '[{"id": "a", "text": "Dizziness from orthostatic hypotension"}, {"id": "b", "text": "Erectile dysfunction from hormone changes"}, {"id": "c", "text": "Decreased libido after several months"}, {"id": "d", "text": "Prostate shrinkage that takes 6+ months"}]'::jsonb, '["a"]', 'Alpha-blockers such as tamsulosin cause orthostatic hypotension and dizziness, which threaten safety. Decreased libido, erectile dysfunction and 6+ month prostate shrinkage relate to finasteride and dutasteride.', false),
  ('bph', 50, 'A 65-year-old client with hesitancy and a weak stream has these results: urinalysis negative for infection, reduced flow on uroflowmetry, a smooth, enlarged prostate on DRE, and a mildly elevated PSA. Which conclusion is MOST supported by these data?', '[{"id": "a", "text": "Prostate cancer that requires a biopsy to confirm"}, {"id": "b", "text": "Urinary tract infection that needs antibiotic treatment"}, {"id": "c", "text": "A normal prostate with symptoms caused by hormonal changes"}, {"id": "d", "text": "Classic BPH, confirmed clinically with the symptoms"}]'::jsonb, '["d"]', 'Negative urinalysis rules out infection, and a smooth, enlarged prostate with a mildly elevated PSA and reduced flow fit BPH, which is confirmed clinically plus symptoms. Biopsy is required only when cancer is suspected, as with a hard, nodular prostate or markedly elevated PSA.', false),
  ('overview', 1, 'A nurse in a reproductive health clinic reviews four telephone messages left overnight. Which client should the nurse call back FIRST?', '[{"id": "a", "text": "A client taking finasteride for 2 months who reports no change in a weak stream"}, {"id": "b", "text": "A client with a positive hCG who reports unilateral pain and vaginal bleeding"}, {"id": "c", "text": "A client with painless genital warts who asks when her Pap screening is due"}, {"id": "d", "text": "A client receiving Depo-Provera who asks whether she needs calcium/Vit D"}]'::jsonb, '["b"]', 'Unilateral pain + bleeding + positive hCG points to ectopic pregnancy, and one-sided pain is treated as an emergency. Finasteride shrinks the prostate over 6+ months, so no change at 2 months is expected and not urgent.', false),
  ('overview', 2, 'A client with regular 28-day cycles is on cycle day 24. She had unprotected intercourse on cycle day 14 and asks what is happening in her body right now. Which statements by the nurse are accurate? Select all that apply.', '[{"id": "a", "text": "You are in the luteal phase, which covers days 15–28."}, {"id": "b", "text": "If an egg was fertilized, it will implant in the fallopian tube."}, {"id": "c", "text": "The corpus luteum is now producing progesterone."}, {"id": "d", "text": "If no egg was fertilized, progesterone will rise and start menstruation."}, {"id": "e", "text": "If an egg was fertilized, hCG will save the corpus luteum."}]'::jsonb, '["a", "c", "e"]', 'Day 24 falls within days 15–28, the luteal phase (a), when the corpus luteum makes progesterone (c); if fertilization occurred, hCG saves the corpus luteum (e). Fertilization happens in the tube but implantation is in the uterus, so (b) is wrong. Without fertilization progesterone drops, not rises, before menstruation, so (d) is wrong.', true),
  ('overview', 3, 'A 19-year-old client calls the clinic on Friday morning requesting emergency contraception after unprotected intercourse that occurred on Monday morning of the same week. Which response by the nurse is BEST?', '[{"id": "a", "text": "Plan B will still work because you are inside its 72-hour window."}, {"id": "b", "text": "Emergency contraception is no longer possible, so plan a pregnancy test."}, {"id": "c", "text": "A Depo-Provera injection given today will act as emergency contraception."}, {"id": "d", "text": "A copper IUD can still be placed within 5 days and is most effective."}]'::jsonb, '["d"]', 'Monday to Friday morning is about 96 hours, past the 72h window for Plan B but within 5 days for a copper IUD, which is the most effective option. Telling her nothing can be done ignores the copper IUD window.', false),
  ('overview', 4, 'A nurse reviews the health histories of four clients who are requesting the combined pill (estrogen + progestin). Which client''s history should the nurse report to the health care provider before the pill is prescribed?', '[{"id": "a", "text": "Age 33; smokes daily; no other health problems"}, {"id": "b", "text": "Age 30; migraine without aura; normal blood pressure"}, {"id": "c", "text": "Age 30; migraine with aura; no other health problems"}, {"id": "d", "text": "Age 25; chlamydia treated last year along with her partner"}]'::jsonb, '["c"]', 'Migraine with aura is an estrogen contraindication for the combined pill. Smoking is a contraindication for smokers >35, so a 33-year-old smoker does not meet it, and migraine without aura is not listed.', false),
  ('overview', 5, 'A nurse is screening several clients who want to start the combined pill (estrogen + progestin). Which clients'' findings should the nurse report to the health care provider before the pill is started? Select all that apply.', '[{"id": "a", "text": "Age 28 with a DVT/PE hx"}, {"id": "b", "text": "Age 37 who smokes daily"}, {"id": "c", "text": "Age 31 with chlamydia treated last year"}, {"id": "d", "text": "Age 40 with liver disease"}, {"id": "e", "text": "Age 34 who smokes daily"}]'::jsonb, '["a", "b", "d"]', 'DVT/PE hx (a), smoking after age 35 (b) and liver disease (d) are listed contraindications to the combined pill. A treated chlamydia infection (c) is not a listed contraindication, and a 34-year-old smoker (e) has not passed the >35 age cut-off.', true),
  ('overview', 6, 'A client had a Paragard IUD placed 6 weeks ago and has just started a relationship with a new partner. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "With an IUD, condoms are no longer needed for STIs."}, {"id": "b", "text": "I will check for the IUD strings once a month."}, {"id": "c", "text": "Using condoms is the only method that prevents STIs for us."}, {"id": "d", "text": "Infection and perforation are alerts I should know about."}]'::jsonb, '["a"]', 'Condoms are the only method preventing STIs, so stopping condoms because of an IUD is unsafe and needs correction. Checking strings monthly and knowing that perforation and infection are IUD alerts are correct.', false),
  ('overview', 7, 'A client has received Depo-Provera every 3 months for 4 years and reports that she rarely eats dairy foods and takes no supplements. Which teaching point is the PRIORITY for this client?', '[{"id": "a", "text": "Check the strings monthly to confirm placement."}, {"id": "b", "text": "Bone density loss can occur; monitor calcium/Vit D."}, {"id": "c", "text": "Take the pill at the same time each day to stay protected."}, {"id": "d", "text": "Return for the next injection in 6 months."}]'::jsonb, '["b"]', 'The alert for Depo-Provera is bone density loss, so calcium/Vit D must be monitored, which matters most in a client with low dairy intake. The injection is every 3 months, not 6, and string checks belong to the IUD.', false),
  ('overview', 8, 'A nurse evaluates contraception teaching given to several clients at a family planning clinic. Which client statements indicate understanding? Select all that apply.', '[{"id": "a", "text": "My tubal ligation can be reversed if I change my mind."}, {"id": "b", "text": "Depo-Provera means an IM injection every 3 months."}, {"id": "c", "text": "Plan B has to be taken within 72 hours to work."}, {"id": "d", "text": "Since I take the pill, I do not need condoms for STIs."}, {"id": "e", "text": "I will check my IUD strings monthly."}]'::jsonb, '["b", "c", "e"]', 'Depo-Provera is an IM injection every 3 months (b), Plan B is taken within 72h (c), and IUD strings are checked monthly (e). Tubal ligation is permanent and irreversible (a), and condoms are the only method preventing STIs, so the pill does not replace them (d).', true),
  ('overview', 9, 'A client with regular 28-day cycles has a positive pregnancy test on what would have been cycle day 30. She asks why her period has not started. Which explanation by the nurse is BEST?', '[{"id": "a", "text": "hCG saves the corpus luteum, so progesterone does not drop."}, {"id": "b", "text": "The LH surge is continuing, so ovulation is still happening."}, {"id": "c", "text": "Estrogen is rising after GnRH, so the luteal phase is starting."}, {"id": "d", "text": "Fertilization stopped FSH, so the cycle has reset to day 1."}]'::jsonb, '["a"]', 'When fertilization occurs, hCG saves the corpus luteum, so progesterone does not drop and menstruation does not occur. The LH surge happens around day 14 and triggers ovulation; it does not explain a missed period.', false),
  ('overview', 10, 'Four clients ask whether they should be referred for an infertility evaluation. Each has had regular unprotected intercourse without conceiving. Which client''s data BEST supports a referral for infertility evaluation?', '[{"id": "a", "text": "Age 34; trying for 10 months"}, {"id": "b", "text": "Age 29; trying for 11 months"}, {"id": "c", "text": "Age 36; trying for 7 months"}, {"id": "d", "text": "Age 33; trying for 9 months"}]'::jsonb, '["c"]', 'At age 35 or older, infertility is defined after more than 6 months of trying, so a 36-year-old trying for 7 months qualifies. Clients younger than 35 need more than 12 months, so 10 or 11 months does not yet qualify.', false),
  ('overview', 11, 'A couple has been trying to conceive for 14 months, and the female partner is 31. The nurse prepares them for the infertility workup. Which factors does the nurse anticipate will be evaluated? Select all that apply.', '[{"id": "a", "text": "Sperm count and motility"}, {"id": "b", "text": "Ovulation in the female partner"}, {"id": "c", "text": "Cremasteric reflex in the male partner"}, {"id": "d", "text": "Patency of the fallopian tubes"}, {"id": "e", "text": "Presence of a varicocele"}]'::jsonb, '["a", "b", "d", "e"]', 'Female causes include ovulation (b) and the tubes (d); male causes include sperm count/motility (a) and varicocele (e). The cremasteric reflex (c) is assessed for testicular torsion, not infertility.', true),
  ('overview', 12, 'Infertility testing for a 30-year-old client shows open fallopian tubes and a normal partner sperm count/motility, but she is not ovulating. Which medication is the provider MOST likely to prescribe?', '[{"id": "a", "text": "Metronidazole"}, {"id": "b", "text": "Clomid"}, {"id": "c", "text": "Methotrexate"}, {"id": "d", "text": "Depo-Provera"}]'::jsonb, '["b"]', 'The problem identified is lack of ovulation, and Clomid stimulates ovulation. Depo-Provera is a contraceptive injection and would not help a client trying to conceive.', false),
  ('overview', 13, 'A client undergoing an infertility workup learns that both of her fallopian tubes are blocked. She asks why that would prevent pregnancy when her ovaries are healthy. Which response by the nurse is BEST?', '[{"id": "a", "text": "Implantation normally happens in the tube, so the embryo cannot attach."}, {"id": "b", "text": "Fertilization normally happens in the tube, before implantation in the uterus."}, {"id": "c", "text": "The tubes make the progesterone that keeps the corpus luteum working."}, {"id": "d", "text": "The tubes release the LH surge that triggers ovulation each month."}]'::jsonb, '["b"]', 'Fertilization occurs in the tube and implantation in the uterus, so blocked tubes stop the egg and sperm from meeting. Implantation does not normally occur in the tube; that confuses the two sites.', false),
  ('overview', 14, 'A client''s routine screening is positive for chlamydia. The client has no symptoms and says, “Since I feel fine, my partner does not need to do anything.” Which response by the nurse is BEST?', '[{"id": "a", "text": "You are right; partners need care only if they develop symptoms of their own."}, {"id": "b", "text": "Your partner should get the HPV vaccine instead of treatment."}, {"id": "c", "text": "Chlamydia clears by itself when there are no symptoms."}, {"id": "d", "text": "It is often asymptomatic, can cause PID, and your partner needs treatment."}]'::jsonb, '["d"]', 'Chlamydia is often asymptomatic yet can progress to PID, and the partner must be treated. Feeling well does not mean the infection is gone or that the partner is safe.', false),
  ('overview', 15, 'A client reports dysuria and a yellow-green discharge, and testing confirms the STI these findings suggest. Which additional action by the nurse is MOST important?', '[{"id": "a", "text": "Treat chlamydia too, since it often co-occurs"}, {"id": "b", "text": "Give acyclovir, since outbreaks often recur"}, {"id": "c", "text": "Teach no alcohol while taking Flagyl for this"}, {"id": "d", "text": "Schedule Pap screening for cervical cancer risk"}]'::jsonb, '["a"]', 'Yellow-green discharge with dysuria fits gonorrhea, which often co-occurs with chlamydia, so both are treated. Avoiding alcohol with Flagyl applies to trichomoniasis, not gonorrhea.', false),
  ('overview', 16, 'A client reports frothy green discharge, and the cervix has a strawberry appearance. Metronidazole is prescribed. Which statements by the client indicate understanding of the teaching? Select all that apply.', '[{"id": "a", "text": "I will avoid alcohol while I take Flagyl."}, {"id": "b", "text": "My partner has no symptoms, so he does not need medicine."}, {"id": "c", "text": "Acyclovir will be added if the discharge comes back."}, {"id": "d", "text": "My partner also needs metronidazole."}, {"id": "e", "text": "Condoms are not needed once this course is finished."}]'::jsonb, '["a", "d"]', 'Trichomoniasis is treated with metronidazole for both partners (d), and no alcohol is allowed with Flagyl (a). The partner needs treatment even without symptoms (b); acyclovir treats herpes, not trichomoniasis (c); and condoms remain the only method preventing STIs (e).', true),
  ('overview', 17, 'A client has a new rash on the palms and soles. Two months ago, the client had a painless genital sore that healed without treatment. Which medication is the nurse MOST likely to prepare?', '[{"id": "a", "text": "Acyclovir"}, {"id": "b", "text": "Metronidazole"}, {"id": "c", "text": "Penicillin G"}, {"id": "d", "text": "Azithromycin"}]'::jsonb, '["c"]', 'A painless chancre followed by a palm/sole rash is the progression of syphilis, which is treated with Penicillin G and is reportable. Acyclovir treats herpes, whose lesions are painful blisters.', false),
  ('overview', 18, 'A client with recurrent painful genital blisters is prescribed acyclovir. During an outbreak, the client asks whether intercourse is safe as long as the medication is being taken. Which response by the nurse is BEST?', '[{"id": "a", "text": "Yes, acyclovir cures the infection once the course is done."}, {"id": "b", "text": "Avoid sex during outbreaks; acyclovir does not cure herpes."}, {"id": "c", "text": "Yes, once you have taken acyclovir for 24 hours."}, {"id": "d", "text": "Yes, if your partner has had the Gardasil vaccine."}]'::jsonb, '["b"]', 'Herpes (HSV-2) is treated with acyclovir but has no cure, and sex is avoided during outbreaks. Gardasil protects against HPV, not herpes.', false),
  ('overview', 19, 'A client who is 30 weeks pregnant has a history of recurrent painful genital blisters treated with acyclovir. She has not told her obstetric provider because “it is not related to the baby.” Which response by the nurse is BEST?', '[{"id": "a", "text": "That is fine, because acyclovir has cured the infection."}, {"id": "b", "text": "Herpes affects the mother, so the baby is not at risk."}, {"id": "c", "text": "You can stop acyclovir until after the baby is born."}, {"id": "d", "text": "Herpes has a neonatal risk, so tell your provider."}]'::jsonb, '["d"]', 'Recurrent painful blisters fit herpes (HSV-2), which carries a neonatal risk, so the obstetric provider must be told. Acyclovir does not cure herpes, so option (a) is false.', false),
  ('overview', 20, 'A 20-year-old client who uses a copper IUD for contraception is starting a sexual relationship with a new partner and asks how to lower the risk of STIs. Which recommendations by the nurse are appropriate? Select all that apply.', '[{"id": "a", "text": "Start the combined pill for added STI protection"}, {"id": "b", "text": "Use condoms, because the IUD does not prevent STIs"}, {"id": "c", "text": "Take acyclovir before sex to prevent herpes"}, {"id": "d", "text": "Receive the HPV (Gardasil) vaccine"}, {"id": "e", "text": "Receive the Hepatitis B vaccine"}]'::jsonb, '["b", "d", "e"]', 'Condoms are the only method preventing STIs (b), and HPV (Gardasil) and Hepatitis B vaccines are recommended (d, e). The combined pill offers no STI protection (a), and acyclovir is herpes treatment with no cure, not a preventive (c).', true),
  ('overview', 21, 'A 24-year-old client has painless genital warts and an abnormal Pap result. Which follow-up does the nurse emphasize as MOST important for this client''s long-term health?', '[{"id": "a", "text": "Avoiding alcohol until the medication is finished"}, {"id": "b", "text": "Taking acyclovir daily to cure the warts"}, {"id": "c", "text": "Completing Penicillin G and reporting the case"}, {"id": "d", "text": "Continuing Pap screening due to cervical cancer risk"}]'::jsonb, '["d"]', 'Painless warts with an abnormal Pap fit HPV, which carries cervical cancer risk, so Pap screening is the key follow-up. Acyclovir treats herpes and does not cure HPV.', false),
  ('overview', 22, 'A client living with HIV who has been taking ART inconsistently has a new CD4 count of 180 cells/mm³. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "The CD4 count shows progression to AIDS."}, {"id": "b", "text": "The CD4 count shows ART has cured the HIV."}, {"id": "c", "text": "The CD4 count fits the early flu-like stage."}, {"id": "d", "text": "The CD4 count is above the AIDS threshold."}]'::jsonb, '["a"]', 'HIV progresses from a flu-like illness to AIDS when the CD4 count is <200, and 180 is below that cut-off. ART is not a cure.', false),
  ('overview', 23, 'A nurse evaluates discharge teaching for several clients at a sexual health clinic. Which client statements indicate understanding? Select all that apply.', '[{"id": "a", "text": "Syphilis: once I finish Penicillin G, no report is filed."}, {"id": "b", "text": "HIV: AIDS is diagnosed when my CD4 is <200."}, {"id": "c", "text": "HPV: my warts are painless, so I can skip Pap screening."}, {"id": "d", "text": "Herpes: acyclovir cured it once the blisters healed."}, {"id": "e", "text": "Gonorrhea: it often co-occurs with chlamydia, so I''ll be tested."}]'::jsonb, '["b", "e"]', 'AIDS is defined by a CD4 count <200 (b), and gonorrhea often co-occurs with chlamydia (e). Syphilis is reportable (a), HPV carries cervical cancer risk requiring Pap screening (c), and acyclovir does not cure herpes (d).', true),
  ('overview', 24, 'A client reports a frothy green vaginal discharge, and the speculum exam shows a strawberry cervix. Which treatment plan is the nurse MOST likely to reinforce?', '[{"id": "a", "text": "Acyclovir for the client during outbreaks"}, {"id": "b", "text": "Penicillin G and a report to the health department"}, {"id": "c", "text": "Metronidazole for both partners and no alcohol"}, {"id": "d", "text": "Cryotherapy and continued Pap screening"}]'::jsonb, '["c"]', 'Frothy green discharge with a strawberry cervix fits trichomoniasis, treated with metronidazole (Flagyl) for both partners with no alcohol. Penicillin G is the treatment for syphilis.', false),
  ('overview', 25, 'A client with an unruptured ectopic pregnancy received methotrexate in the emergency department and returns for weekly follow-up. Which finding BEST indicates that treatment has been effective?', '[{"id": "a", "text": "hCG has leveled off above zero"}, {"id": "b", "text": "hCG is now at zero"}, {"id": "c", "text": "hCG is rising each week"}, {"id": "d", "text": "Bleeding stopped; hCG still positive"}]'::jsonb, '["b"]', 'After methotrexate for an unruptured ectopic, hCG is monitored to zero, so a level of zero shows the treatment worked. Bleeding stopping while hCG remains positive does not confirm success.', false),
  ('overview', 26, 'A nurse in an urgent care clinic reviews the triage notes for five clients. Which findings require IMMEDIATE follow-up? Select all that apply.', '[{"id": "a", "text": "Positive hCG with one-sided pain and bleeding"}, {"id": "b", "text": "Painless warts and a recent abnormal Pap"}, {"id": "c", "text": "Sickle cell disease and an erection for 5 hours"}, {"id": "d", "text": "Sudden severe scrotal pain; absent cremasteric reflex"}, {"id": "e", "text": "Recurrent painful blisters while taking acyclovir"}]'::jsonb, '["a", "c", "d"]', 'One-sided pain with bleeding and positive hCG suggests ectopic pregnancy, an emergency (a); an erection >4h is a urological emergency (c); and sudden severe scrotal pain with an absent cremasteric reflex suggests testicular torsion needing surgery within 6 hours (d). HPV warts need Pap screening but are not an emergency (b), and recurrent herpes blisters are expected with a condition that has no cure (e).', true),
  ('overview', 27, 'A client at 35 weeks of pregnancy arrives with painful dark red vaginal bleeding, and the uterus is rigid on palpation. Which action does the nurse anticipate as the PRIORITY?', '[{"id": "a", "text": "Preparing the client for emergency delivery"}, {"id": "b", "text": "Keeping the client on bed rest and planning a later C-section"}, {"id": "c", "text": "Giving magnesium sulfate and observing"}, {"id": "d", "text": "Performing a vaginal exam to assess the cervix"}]'::jsonb, '["a"]', 'Painful dark red bleeding with a rigid uterus indicates placental abruption, which is life-threatening and requires emergency delivery. Bed rest with a planned C-section is the plan for painless placenta previa bleeding.', false),
  ('overview', 28, 'A client at 32 weeks of pregnancy is admitted with painless bright red bleeding. Which action by a nursing student requires immediate intervention by the nurse?', '[{"id": "a", "text": "Keeping the client on bed rest"}, {"id": "b", "text": "Explaining that a C-section is being planned"}, {"id": "c", "text": "Checking the client''s vital signs"}, {"id": "d", "text": "Preparing to perform a vaginal exam"}]'::jsonb, '["d"]', 'Painless bright red bleeding suggests placenta previa, in which a vaginal exam must not be done. Bed rest and a planned C-section are correct parts of previa care.', false),
  ('overview', 29, 'A nurse on an antepartum unit receives report on four clients. Which client should the nurse see FIRST?', '[{"id": "a", "text": "30 weeks, placenta previa, no bleeding today, on bed rest"}, {"id": "b", "text": "Day 2 after D&C for molar pregnancy, hCG drawn today"}, {"id": "c", "text": "34 weeks, new painful dark red bleeding, rigid uterus"}, {"id": "d", "text": "32 weeks, preeclampsia on magnesium sulfate, no seizures"}]'::jsonb, '["c"]', 'Painful dark red bleeding with a rigid uterus suggests placental abruption, which is life-threatening for mother and baby and requires emergency delivery. The previa client without current bleeding and the preeclampsia client without seizures are stable for now.', false),
  ('overview', 30, 'A client at 36 weeks with preeclampsia suddenly has a seizure. Which interventions does the nurse anticipate? Select all that apply.', '[{"id": "a", "text": "Give calcium gluconate to stop the seizure"}, {"id": "b", "text": "Give magnesium sulfate"}, {"id": "c", "text": "Give a phenylephrine injection"}, {"id": "d", "text": "Prepare for delivery, the only cure"}, {"id": "e", "text": "Keep on bed rest and plan a later C-section"}]'::jsonb, '["b", "d"]', 'Preeclampsia plus seizures is eclampsia: give magnesium sulfate (b), and delivery is the only cure (d). Calcium gluconate is the antidote for magnesium, not a seizure treatment (a); phenylephrine is used for priapism (c); and bed rest with a planned C-section is previa care (e).', true),
  ('overview', 31, 'A client with eclampsia is receiving IV magnesium sulfate. The provider tells the nurse the client is now showing signs of magnesium toxicity. Which medication should the nurse prepare IMMEDIATELY?', '[{"id": "a", "text": "Phenylephrine"}, {"id": "b", "text": "Additional magnesium sulfate"}, {"id": "c", "text": "Calcium gluconate"}, {"id": "d", "text": "Methotrexate"}]'::jsonb, '["c"]', 'Calcium gluconate is the antidote for magnesium sulfate. Giving more magnesium sulfate would worsen the toxicity.', false),
  ('overview', 32, 'A 15-year-old client reports sudden, severe scrotal pain that began 2 hours ago while playing basketball. The cremasteric reflex is absent. Which action by the nurse is the PRIORITY?', '[{"id": "a", "text": "Apply scrotal support and reassess in 4 hours"}, {"id": "b", "text": "Prepare the client for surgery to save the testicle"}, {"id": "c", "text": "Obtain a sperm count to check for a varicocele"}, {"id": "d", "text": "Anticipate aspiration and a phenylephrine injection"}]'::jsonb, '["b"]', 'Sudden severe scrotal pain with an absent cremasteric reflex indicates testicular torsion, which needs surgery within 6 hours to save the testicle; waiting 4 more hours would bring him to the 6-hour limit. Aspiration and phenylephrine treat priapism.', false),
  ('overview', 33, 'A 24-year-old client with sickle cell disease arrives at the emergency department with an erection that began 5 hours ago. Which actions does the nurse anticipate? Select all that apply.', '[{"id": "a", "text": "Wait until the erection has lasted 6 hours"}, {"id": "b", "text": "Treat as a urological emergency"}, {"id": "c", "text": "Prepare to aspirate"}, {"id": "d", "text": "Prepare for surgery to save the testicle"}, {"id": "e", "text": "Prepare for a phenylephrine injection"}]'::jsonb, '["b", "c", "e"]', 'An erection >4h is a urological emergency (b), treated with aspiration (c) and phenylephrine injection (e). The 6-hour window applies to testicular torsion surgery, not priapism (a, d).', true),
  ('overview', 34, 'A client had a D&C for a molar pregnancy and returns for weekly hCG monitoring. Her results over 3 weeks are 52,000, then 18,000, then 26,000 mIU/mL. Which interpretation by the nurse is MOST accurate?', '[{"id": "a", "text": "Rising hCG signals possible malignancy (choriocarcinoma)."}, {"id": "b", "text": "The trend shows the D&C removed all trophoblast overgrowth."}, {"id": "c", "text": "Monitoring can stop because hCG fell after the initial week."}, {"id": "d", "text": "The values reflect a normal corpus luteum supported by hCG."}]'::jsonb, '["a"]', 'After D&C, hCG is monitored weekly to zero, and a rise (18,000 to 26,000) signals malignancy (choriocarcinoma). One early drop does not end monitoring because hCG must reach zero.', false),
  ('overview', 35, 'A nurse reviews the data for a client at 12 weeks of pregnancy who has been referred for evaluation. Which findings should make the nurse suspect a molar pregnancy? Select all that apply.', '[{"id": "a", "text": "Vaginal bleeding"}, {"id": "b", "text": "Uterus small for dates"}, {"id": "c", "text": "High hCG level"}, {"id": "d", "text": "Uterus large for dates"}, {"id": "e", "text": "hCG falling toward zero"}]'::jsonb, '["a", "c", "d"]', 'Molar pregnancy signs are high hCG (c), vaginal bleeding (a) and a uterus large for dates (d). A uterus small for dates (b) is the opposite of the expected finding, and hCG falling toward zero (e) is the goal after D&C, not a sign of the condition.', true),
  ('overview', 36, 'A client who speaks limited English arrives for a sexual health assessment with her 14-year-old daughter, who offers to interpret. Which action by the nurse is BEST?', '[{"id": "a", "text": "Accept the daughter''s offer to save time"}, {"id": "b", "text": "Ask the client''s spouse to interpret by phone"}, {"id": "c", "text": "Use certified interpreters only"}, {"id": "d", "text": "Use simple yes/no questions and gestures"}]'::jsonb, '["c"]', 'Only certified interpreters are used, never family members or children. A spouse on the phone is still a family member.', false),
  ('overview', 37, 'A nurse is beginning a sexual health assessment with a 45-year-old client who appears uncomfortable and avoids eye contact. Which question by the nurse is BEST?', '[{"id": "a", "text": "You have just one partner at this time, correct?"}, {"id": "b", "text": "What concerns do you have about your sexual health?"}, {"id": "c", "text": "Do you and your partner use condoms each time?"}, {"id": "d", "text": "I assume your husband is your partner, is that right?"}]'::jsonb, '["b"]', 'Sexual health is assessed with nonjudgmental, open-ended questions. The other options are closed questions, and assuming a husband does not affirm all sexual orientations.', false),
  ('overview', 38, 'A 28-year-old client who identifies as nonbinary and speaks limited English arrives with a partner for a sexual health assessment. Which actions by the nurse are appropriate? Select all that apply.', '[{"id": "a", "text": "Provide privacy for the interview"}, {"id": "b", "text": "Use closed questions to keep it brief"}, {"id": "c", "text": "Use nonjudgmental, open-ended questions"}, {"id": "d", "text": "Ask the partner to interpret to save time"}, {"id": "e", "text": "Affirm the client''s gender identity"}]'::jsonb, '["a", "c", "e"]', 'The nurse provides privacy (a), uses nonjudgmental, open-ended questions (c) and affirms all gender identities (e). Closed questions (b) do not fit the recommended approach, and only certified interpreters are used, never family members (d).', true),
  ('overview', 39, 'During a wellness visit, a client says, “My STI tests are all negative, so my sexual health must be fine.” Which response by the nurse is BEST?', '[{"id": "a", "text": "Sexual health also includes emotional, mental, and social well-being."}, {"id": "b", "text": "Negative tests mean no further sexual health assessment is needed."}, {"id": "c", "text": "Sexual health refers to the absence of disease, so you are correct."}, {"id": "d", "text": "Our visit covers contraception rather than feelings about sexuality."}]'::jsonb, '["a"]', 'Sexual health is physical, emotional, mental, and social well-being related to sexuality and is not just the absence of disease. Option (c) repeats the misconception the nurse needs to correct.', false),
  ('overview', 40, 'A client declines a recommended treatment because of cultural beliefs. Using the LEARN model, the nurse has listened to the client''s perspective and explained the nurse''s perception of the situation. Which action should the nurse take NEXT?', '[{"id": "a", "text": "Negotiate an agreement on the plan"}, {"id": "b", "text": "Recommend care options"}, {"id": "c", "text": "Listen again to the client''s full perspective"}, {"id": "d", "text": "Acknowledge differences and similarities"}]'::jsonb, '["d"]', 'LEARN proceeds Listen, Explain, Acknowledge, Recommend, Negotiate, so after Listen and Explain the nurse should Acknowledge differences and similarities. Recommending care options comes after acknowledging.', false),
  ('overview', 41, 'A client from a different cultural background disagrees with the plan for STI treatment. Which nurse actions are consistent with the LEARN model? Select all that apply.', '[{"id": "a", "text": "Listen to the client''s perspective"}, {"id": "b", "text": "Explain the nurse''s view before listening to the client"}, {"id": "c", "text": "Acknowledge differences and similarities"}, {"id": "d", "text": "Recommend care options"}, {"id": "e", "text": "Negotiate an agreement"}]'::jsonb, '["a", "c", "d", "e"]', 'LEARN = Listen to the patient''s perspective (a), Explain your perception, Acknowledge differences and similarities (c), Recommend care options (d), and Negotiate an agreement (e). Explaining before listening (b) reverses the model, which begins with listening.', true),
  ('overview', 42, 'A 70-year-old client reports urinary problems that have developed gradually over the past year. Which findings does the nurse expect if the problems are caused by BPH? Select all that apply.', '[{"id": "a", "text": "Yellow-green discharge with dysuria"}, {"id": "b", "text": "Hesitancy"}, {"id": "c", "text": "Weak stream"}, {"id": "d", "text": "Nocturia"}, {"id": "e", "text": "Incomplete emptying"}]'::jsonb, '["b", "c", "d", "e"]', 'BPH symptoms include hesitancy (b), weak stream (c), nocturia (d) and incomplete emptying (e). Yellow-green discharge with dysuria (a) is the key symptom of gonorrhea.', true),
  ('overview', 43, 'A client with BPH started finasteride 6 weeks ago and says, “This pill isn''t working; I still have a weak stream.” Which response by the nurse is BEST?', '[{"id": "a", "text": "Finasteride works by relaxing the urethra right away."}, {"id": "b", "text": "Stop the finasteride and ask about switching to Clomid."}, {"id": "c", "text": "Finasteride shrinks the prostate over 6+ months."}, {"id": "d", "text": "A weak stream at 6 weeks means TURP syndrome."}]'::jsonb, '["c"]', 'Finasteride shrinks the prostate and takes 6+ months, so little change at 6 weeks is expected. Relaxing the urethra describes tamsulosin, the alpha-blocker.', false),
  ('overview', 44, 'A client is 12 hours post-op after TURP with a 3-way Foley and continuous bladder irrigation (CBI). Which assessment does the nurse recognize as an expected finding?', '[{"id": "a", "text": "Bright red urine in the drainage bag"}, {"id": "b", "text": "Pink urine in the drainage bag"}, {"id": "c", "text": "New confusion and restlessness"}, {"id": "d", "text": "A new seizure with low sodium"}]'::jsonb, '["b"]', 'After TURP with a 3-way Foley and CBI, pink urine is normal. Bright red urine indicates hemorrhage, and confusion or seizures suggest TURP syndrome.', false),
  ('overview', 45, 'A nurse on a urology unit receives report on four clients. Which client should the nurse assess FIRST?', '[{"id": "a", "text": "Day 1 after TURP with CBI; urine draining pink"}, {"id": "b", "text": "BPH on tamsulosin; nocturia twice nightly"}, {"id": "c", "text": "After TURP; asking about retrograde ejaculation"}, {"id": "d", "text": "Sickle cell disease; erection for 4.5 hours"}]'::jsonb, '["d"]', 'An erection lasting longer than 4 hours is a urological emergency, and sickle cell is a common cause. Pink urine after TURP is normal, and nocturia and retrograde ejaculation are not emergencies.', false),
  ('overview', 46, 'A client is on day 1 after TURP with a 3-way Foley and CBI running. Which findings require IMMEDIATE follow-up? Select all that apply.', '[{"id": "a", "text": "New confusion"}, {"id": "b", "text": "Pink urine in the drainage bag"}, {"id": "c", "text": "3-way Foley draining with CBI running"}, {"id": "d", "text": "Worry about retrograde ejaculation"}, {"id": "e", "text": "Bright red urine in the drainage bag"}]'::jsonb, '["a", "e"]', 'New confusion can signal TURP syndrome (hyponatremia from irrigant absorption) (a), and bright red urine means hemorrhage (e). Pink urine (b) and a 3-way Foley with CBI (c) are expected, and retrograde ejaculation is harmless (d).', true),
  ('overview', 47, 'A client who had a TURP yesterday with CBI becomes newly confused, and his serum sodium is lower than it was before surgery. Which complication does the nurse suspect is the MOST likely cause?', '[{"id": "a", "text": "Hemorrhage shown by bright red urine"}, {"id": "b", "text": "Retrograde ejaculation affecting fertility"}, {"id": "c", "text": "Priapism related to the 3-way Foley"}, {"id": "d", "text": "TURP syndrome from irrigant absorption"}]'::jsonb, '["d"]', 'TURP syndrome is hyponatremia from irrigant absorption, causing confusion and seizures. Hemorrhage shows as bright red urine, not low sodium with confusion.', false),
  ('overview', 48, 'Two weeks after TURP, a client reports that little or no semen comes out during orgasm. He and his partner hope to have a child. Which statement by the nurse is MOST accurate?', '[{"id": "a", "text": "This is retrograde ejaculation; it is harmless but may affect fertility."}, {"id": "b", "text": "This is TURP syndrome, and it needs emergency treatment."}, {"id": "c", "text": "This signals hemorrhage, so the irrigation must be increased."}, {"id": "d", "text": "This is harmless and will have no effect on your fertility."}]'::jsonb, '["a"]', 'Retrograde ejaculation after TURP is harmless but may affect fertility, which matters for this couple. Option (d) wrongly states there is no effect on fertility.', false),
  ('overview', 49, 'A 26-year-old client scheduled for a vasectomy is reviewing the consent form with the nurse. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "I understand this method is meant to be permanent."}, {"id": "b", "text": "I need to sign an informed consent before the procedure."}, {"id": "c", "text": "If we want children later, it can easily be reversed."}, {"id": "d", "text": "We will still need condoms to prevent STIs."}]'::jsonb, '["c"]', 'Vasectomy is permanent and irreversible, so expecting an easy reversal needs correction. Informed consent is required, and condoms are the only method that prevents STIs.', false),
  ('overview', 50, 'A client started the combined pill (estrogen + progestin) 2 months ago. She tells the nurse she takes it at breakfast on workdays and at bedtime on weekends. Which response by the nurse is BEST?', '[{"id": "a", "text": "Taking it at any hour of the day gives equal protection."}, {"id": "b", "text": "Switch to taking it on the days you have intercourse."}, {"id": "c", "text": "That is fine as long as each dose is within 72 hours."}, {"id": "d", "text": "The pill should be taken at the same time daily."}]'::jsonb, '["d"]', 'The combined pill is taken at the same time daily. The 72-hour window applies to Plan B, not to routine pill dosing.', false)
  ) AS v(source_key, display_order, stem, options, correct_answer, rationale, is_multi)
  JOIN _repro_seed_map m USING (source_key)
 CROSS JOIN _repro_seed_config c;

DO $$
DECLARE
  v_bad text;
BEGIN
  SELECT string_agg(format('%s=%s', m.source_key, coalesce(n.cnt, 0)), ', ')
    INTO v_bad
    FROM _repro_seed_map m
    LEFT JOIN (SELECT category, count(*) AS cnt FROM test_questions GROUP BY category) n
      ON n.category = m.category
   WHERE coalesce(n.cnt, 0) <> 50;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'Reproductive seed post-check failed (expected 50 per topic): %', v_bad;
  END IF;
END $$;

COMMIT;
